/* 平成22年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h22.committeeSessions.push(...[{"id":"h22-20101109-4","meetingId":"h22-c-settlement","date":"2010年11月9日","dateIso":"2010-11-09","committee":"決算特別委員会","time":"午前１０時０２分～午後５時３１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を165件整理しています。","topics":[{"id":"topic-01","title":"◯鈴木委員長 ただいまより決算特別委員会を開会いたします。それでは、平成２１年度品川区一般会計歳入歳出決算","agenda":"◯鈴木委員長 ただいまより決算特別委員会を開会いたします。それでは、平成２１年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"成果報告書、１７３ページ、教育総務費の事務局費、区固有教員についてお伺いいたします。改めて、区独自の教員採用についての意義、理由についてお教えください。","respondent":"冠木指導課長","answer":"人生について語り合える身近な先生がいてほしい、そんな思いを込めまして、平成２１年度から採用に至っているものです。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問・要望","question":"そこで、今後の展開についてお伺いさせてほしいと求めました。来年度以降の採用予定はどうなっていくのか尋ねました。","respondent":"冠木指導課長","answer":"品川区の固有教員につきましては、現在、第３期生の選考を進めているところです。将来の見通しにつきましては、おおむね５期生を目安として、３０名の固有教員の採用を考えているところです。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問・要望","question":"何年ごとに異動とか、そういうこともあるのかどうかもお伺いさせてほしいと求めました。それから、現在、東京都採用の人が、品川区の区固有教員になったりすることはできるのでしょうか、そういうことも説明を求めました。","respondent":"冠木指導課長","answer":"おおむね６年ぐらいで動いているというのが現状ですけれども、区の人材ですので、異動等も有効に考えてまいりたいと思ってあります。現実に、今、１名、東京都の採用であった方が、区固有教員に再チャレンジしていただきまして、実際に勤めている方がいらっしゃいます。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"今現在、どこの学校にいるかというのはどうか尋ねました。","respondent":"冠木指導課長","answer":"失礼いたしました。現在の８名の配置先ですけれども、荏原第四中学校、１名が教員委員会事務局です。","id":"exchange-004"},{"speaker":"沢田委員","kind":"意見","question":"３０名ということですが、何か協調体制とか、区としてお考えがありましたらお教えくださいとの意見を述べました。","respondent":"冠木指導課長","answer":"そういったことで、区別、差別ということは一切ございませんし、今後も、そういうことのないようにしてまいりたいと考えています。そのうえで、この区固有教員には、品川区の教育施策を力強く牽引していっていただきたいという期待があります。","id":"exchange-005"},{"speaker":"沢田委員","kind":"質問","question":"ちょっと厳しい労働環境だったのかなと思うんですけれども、現状についてのご認識はどういう形なのかと思いまして、お伺いします。そういったデータがあるのかどうか、ちょっとわからないですけれども、あれば教えてほしいと求めました。","respondent":"冠木指導課長","answer":"全部で８６６名いますけれども、すべて品川区の教育のために力強く、毎日の仕事に精を出しています。逆に言うと、長く品川区にいたくてもいられないというような状況もございまして、数字から分析できることはあまりないのかなと思ってあります。","id":"exchange-006"},{"speaker":"浅野委員","kind":"質問","question":"１７６ページの図書館経費、それから１８１ページの児童・生徒健康管理費の中から、就学時健康診断謝礼についてお伺いします。蔵書の数ですとか、また貸し出しの傾向なども変わってきているのではないかと思いますが、この傾向についてまずお伺いします。","respondent":"小川品川図書館長","answer":"蔵書の数につきましては、毎年、一定程度の予算を獲得いたしまして、一定の蔵書を保っているところです。貸出状況につきましては、ここ数年、着実に伸びておりまして、前年と比べましても、３％、６％増というところで、少しずつ伸びている状況です。","id":"exchange-007"},{"speaker":"浅野委員","kind":"質問","question":"どのような形で取り組んでいくのかということを、まず１点、お伺いします。こちらのほうの考え方、最近ではブルーレイもはやってきておりますが、資料整備の方向性等についてお伺いします。","respondent":"小川品川図書館長","answer":"品川区立図書館１０館のうち、五反田の４館のみで取り扱っているものでして、できるだけ図書館としてふさわしい資料の収集に努めているところです。ＣＤの収集につきましても、図書館としては、ある程度精査していくことが必要であると考えているところです。","id":"exchange-008"},{"speaker":"浅野委員","kind":"提案","question":"さて、過日の第２回定例会の一般質問で、会派のほうから、国民読書年に合わせて、電子書籍に関する提案をさせていただいたかと思います。","respondent":"小川品川図書館長","answer":"電子書籍に関しましては、委員、ご指摘のとおり、多くのメリットがあるということは、こちらも認識しております。すぐに電子書籍の導入等を考えてはございませんが、きちんと対処して、検討していきたいと考えているところです。","id":"exchange-009"},{"speaker":"浅野委員","kind":"質問・要望","question":"ここのところは要望です。この点についてお伺いします。","respondent":"和氣学務課長","answer":"就学時健康診断謝礼ですが、医師への謝礼ということで、基本的に、１校当たり４名の医師に健康診断をお願いしております。８項目にわたりまして健康診断をいたしますので、最低その４名を配置してお願いをしているところで、校医を中心にお願いをしています。","id":"exchange-010"},{"speaker":"浅野委員","kind":"質問","question":"ということは、１校当たり４名の方に対します、校医以外への謝礼という認識でよろしいわけですね。１１月３０日までに実施をされると出ていたんですけれども、こちらの就学時健康診断の受診率は、どのような形で推移をしているのかお伺いします。","respondent":"和氣学務課長","answer":"そこで、私どもといたしましては、すべての子どもに受診をお願いしていますけれども、残念ながら、少し受けていらっしゃらない方もいるようです。この数字については、私のほうでまだ押さえておりませんが、ごくわずかいらっしゃると聞いております。","id":"exchange-011"},{"speaker":"浅野委員","kind":"質問","question":"そしてまた、ここ数年間、どのような形で推移をしているのかお伺いします。こちらの件についてお伺いします。","respondent":"冠木指導課長","answer":"就学相談の件数ですけれども、平成２１年度は９４件、平成２０年度は６６件、平成１９年度が７７件です。というケースではございませんで、これは全体像ということでご理解いただければありがたいと思います。","id":"exchange-012"},{"speaker":"浅野委員","kind":"提案","question":"例えば特別支援学級のほうの提案とかをされるかと思いますけれども、この点については、これからも丁寧に行ってほしいと求めました。どのような形で、また校医がやられているのかと思いますけれども、ここら辺についてもお願いしますとの意見を述べました。","respondent":"和氣学務課長","answer":"その後、何か課題があれば、追いかけているです。","id":"exchange-013"},{"speaker":"浅野委員","kind":"質問","question":"学校保健委員会を平成１８年に立ち上げて、平成１９年には、この中でも発見できるかと思います。今までは口腔ですとか、歯の件で質問があったかと思いますけれども、この点についてはいかがか尋ねました。","respondent":"冠木指導課長","answer":"そういった虐待の発見についても、そういった機会を利して、早期発見に努めてまいりたいと思います。","id":"exchange-014"},{"speaker":"菊地委員","kind":"質問","question":"お聞きしたいのは、援助を超える差額というのは、どのように負担されているのか。この辺をまずお聞かせ願いたいと思います。","respondent":"和氣学務課長","answer":"値上げもやってまいりましたので、引き続き、この金額を維持してまいりたいと考えています。最終的には学校が決めてまいりますので、高価なアルバムではなくて、抑えるようにお願いをしています。","id":"exchange-015"},{"speaker":"菊地委員","kind":"質問","question":"どうしようかということに心を砕かざるを得ない状況にあるわけですから、そうした見直しをすべきだと考えますけれどもいかがでしょうか。同時に、今、義務教育を受けている児童・生徒すべてを対象にして補助していくということを考えるべきではないかと思うんですけれどもどうか尋ねました。","respondent":"和氣学務課長","answer":"私どもは補助をしたいと考えていますので、所得制限は、このまま継続してまいりたいと思ってあります。それほど大きな差はございませんので、今、適正な金額であるかなと考えています。","id":"exchange-016"},{"speaker":"菊地委員","kind":"質問・要望","question":"この辺は、改めて、これがほんとうに適正な負担なのかどうかというところは、もう一度、ご答弁いただきたい。実際の準備として１０万円、２０万円とかかるわけですから、ご答弁をほしいと求めました。","respondent":"和氣学務課長","answer":"その意味で、私どもとしては、お困りの家庭にはしっかりと援助をしていると考えているところです。その金額自体は、学校が保護者の負担を十分に考えて、十分に協議をしたうえでつくっていただくほうが先決かなと考えています。","id":"exchange-017"},{"speaker":"菊地委員","kind":"意見","question":"家庭に重い負担を押しつけられているというのは、日本の場合は、家計の割合、５３.４％という高い率なんです。ぜひ改善をしてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"石田委員","kind":"質問","question":"１７５ページ、１７５ページと１７６ページ、英語教育関係についてお伺いします。平成２１年度、情報モラル教育についてお伺いした際に、どのような改訂になったのか。","respondent":"田村庶務課長、冠木指導課長","answer":"私のほうから、校庭整備についての考え方をご説明いたします。その辺を学校が調整して、水をまいて飛散防止を図っていくという配慮をしつつ、グラウンドを利用しているという状況です。例えば５、６年生では、さらに情報モラル教育について進めていきたいと考えているところです。","id":"exchange-019"},{"speaker":"石田委員","kind":"質問","question":"そこで改めて、品川区は、聞く、話す英語教育について、何が一番必要だと考えておられるでしょうか。平成１９年度の決算特別委員会の際に、どのように改善をされたのか、説明を求めました。","respondent":"冠木指導課長","answer":"今、導入いたしまして、かなりの部分で解決はしてまいりました。その方が小学校に行ってみたり、そんな工夫をする中で、それぞれの思いというものは改善しつつあると思ってあります。","id":"exchange-020"},{"speaker":"石田委員","kind":"提案","question":"お伺いしますが、以前も提案をさせていただいたんですが、戻ってきていただく。日本の子どもたちを教えていただいていると思うんですが、どのようなお考えを持っているのか、説明を求めました。","respondent":"冠木指導課長","answer":"これは、非常に効果の上がる取り組みだと考えていますので、これについては、ぜひ続けていきたいと考えています。なお、語学派遣、語学留学については、少し研究をしてまいりたいと考えています。","id":"exchange-021"},{"speaker":"石田委員","kind":"質問・要望","question":"時間があるので、１点だけ、１７５ページ、学校案内パンフレット作成費についてと、学校公開についてお伺いします。現在、私立に行かれた方が全体でどのぐらいいるのか教えていただきたいのと、どのような取り組みをされているのかお知らせください。","respondent":"和氣学務課長","answer":"どんな多彩な取り組みをしているのか、どこに重点を置いているのか、それぞれの学校の魅力を最大限アピールする努力をしています。そういう中で、私どもは、確実に公立学校への進学を進めてまいりたいと思っています。","id":"exchange-022"},{"speaker":"渡辺委員","kind":"質問","question":"私は、１８０ページの学校図書館運営費のところから伺っていきたいと思います。伺いたいところは、ここ数年ずっと言われ続けている中で、これはもう日本全国大きな課題だと思います。","respondent":"冠木指導課長","answer":"この５年間ぐらいで、５年前ぐらいにはピークだったのですけれども、３０分から１時間という子どもの方が山が高くなってまいりました。各学校では読書の時間をつくったり、読書感想文等々の取り組みを行って、子どもたちの活字離れを防ぐ取り組みをしています。","id":"exchange-023"},{"speaker":"渡辺委員","kind":"質問","question":"この講演の中の例で、１枚の絵を見せて、「季節はいつですか」と問う。昨年４月の文部科学省の指導要領の中に、あるいは、同趣旨での取り組みがありましたらお知らせください。","respondent":"冠木指導課長","answer":"区立図書館と学校図書館が、どういうふうに連携して子どもたちに本を勧めていくかというような取り組みを、今進めております。第二延山小学校が、平成１９年から研究を進めているところでございまして、その成果を見ながら全区に発信をしていきたいと思っているところです。","id":"exchange-024"},{"speaker":"渡辺委員","kind":"質問","question":"そういう中では、今の時代の流れの中で、世界基準というのも入ってくると思います。そういった視点で、今、ありましたコミュニケーションというくくりで、今後の展開や行政の考え方を伺えればと思います。","respondent":"冠木指導課長","answer":"先ほど、私はこう思う、なぜならこうだからというようなところをしっかりと伝えていくのが真のコミュニケーションかなと考えています。やはり市民科の中でそれぞれの子どもたちが自分をどう考え、そして、コミュニケーションについても力強く進めてまいりたいと思ってあります。","id":"exchange-025"},{"speaker":"山元委員","kind":"質問・要望","question":"実際参加された方たちの中から、何かこうしてほしいという要望があれば教えてほしいと求めました。１１９件とありますが、どういうものなのか、内容を教えてほしいと求めました。","respondent":"田村庶務課長","answer":"当日の参加が１００名の予定だったのが、５６名ということで、天気に影響されたです。同じ箇所を何回もだと、なかなか新たな層を開拓できないということで、今後、場所も含めて、少し目新しいものを含めて考えていきたいと思います。","id":"exchange-026"},{"speaker":"山元委員","kind":"質問・要望","question":"もう１点、埋蔵文化財調査費ということで、１０件と書いてありますが、何かお宝が見つかったのでしょうか。その内容をちょっと教えてほしいと求めました。","respondent":"田村庶務課長","answer":"それ以外に、大井鹿島の遺跡も１件、発掘調査に入りました。それから、大井林町の古墳についても、立会調査ということで、全体で９件の埋蔵文化財の調査をしたということで、計上したものです。","id":"exchange-027"},{"speaker":"山元委員","kind":"質問・要望","question":"先ほど、我が党からも図書館の話がありましたが、私は、障害者のことでちょっとお伺いをさせてほしいと求めました。ある程度借りて行かれている方がわかるかと思いますが、年代的に、どういう方がお借りになっているのか教えてほしいと求めました。","respondent":"小川品川図書館長","answer":"点字図書が１４０件ほど、録音雑誌等が１,０００件ちょっと、雑誌関係で２,０００件強というような状況です。２０歳から６０歳代の間が４０人程度、６５歳以上の方が５０人程度ということで、常時利用される方が約１００人程度いらっしゃるという状況です。","id":"exchange-028"},{"speaker":"山元委員","kind":"質問・要望","question":"６,２８５点、ある程度こういうものを買ってもらいたいとか、そういうことを参考にして購入なさっているのでしょうか。どういう形で、内容的にどういうものを購入なさっているのか教えてほしいと求めました。","respondent":"小川品川図書館長","answer":"障害者資料の購入の仕方ですが、障害者資料につきましては、購入する場合と、それから、ボランティア団体に制作をしていただく場合と二つあります。そちらのほうのタイトルを障害者資料に転換していくような形で、購入したり、制作したりしているような状況です。","id":"exchange-029"},{"speaker":"山元委員","kind":"質問","question":"もう１点、品川区には区立の図書館がありますけれども、現実、地元に障害者の方が何人かいらっしゃると思うんです。地元の図書館の中には、例えば、手でさわる本とか、いろいろあると思うんですが、大体、どのぐらい扱っているのか教えていただけますか。","respondent":"小川品川図書館長","answer":"現在、蔵書数につきましては、平成２２年３月３１日現在で、さわる絵本、拡大写本、点字、録音図書等を含めまして、４,０００点弱の資料があります。","id":"exchange-030"},{"speaker":"高橋委員","kind":"質問","question":"受け入れていただけるのでしょうか。そのための準備等はされているか尋ねました。","respondent":"田村庶務課長","answer":"ですから、この中にも、既に、特別支援学校に通っている方で、実際にすまいるスクールに通われている方もいらっしゃいます。ですから、今、委員お尋ねのように、そういう方で、すまいるスクールにぜひ入りたいという方がいれば、お受けするという形になると思います。","id":"exchange-031"},{"speaker":"高橋委員","kind":"質問","question":"同じ場所で放課後のサポートが受けられれば、より効果があるし、安心だと思います。そうすると、こちらの都立の特別支援学校の中で、すまいるスクールを品川区が運営することはどうお考えか尋ねました。","respondent":"田村庶務課長","answer":"プラン２１にも記載していますように、支援学校のほうに赴いて、そこにすまいるスクールの分室みたいなものをつくって対応するということは考えておりません。","id":"exchange-032"},{"speaker":"高橋委員","kind":"質問","question":"これについて、福祉の面での放課後サポート、こちらを特別支援学校の中の一部の場所を使ってやるということについてどうお考えか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"高橋委員","kind":"意見","question":"では、ＰＴＡの方々に協力いただいて、放課後支援をしている、現在、港養護学校でそれをやっているんですが、それについて、どのようなものだかお答えいただけるとありがたいんですがお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"高橋委員","kind":"質問・要望","question":"１学期に一、それでは、放課後のサポートが足りないのではないですかという趣旨なんです。それで、区民が通われているので、その区民のサポートができないでしょうかというお話なんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"高橋委員","kind":"質問","question":"１８０ページの就学援助費についてお尋ねします。引き落としになっているものがあれば、答えるよう求めました。","respondent":"和氣学務課長","answer":"就学援助につきましては、毎年６月に申請をしていただいて、一定の基準をクリアした方に支給をしております。ただし、例えば、給食費を滞納しているという場合については、あらかじめ、その部分を差し引いて支給をするということがあります。","id":"exchange-036"},{"speaker":"高橋委員","kind":"質問","question":"給食費以外にも、滞納があった場合は差し引かれるのか尋ねました。","respondent":"和氣学務課長","answer":"給食費以外はございません。給食費のみ、滞納の場合、差し引いて支給いたしますが、それ以外については特にそういう方法はとってございません。","id":"exchange-037"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、それが、それぞれ支払うべきところに支払われないという例はあるのでしょうか。あれば、お教えください。","respondent":"和氣学務課長","answer":"基本的に、私ども、教材費等については、滞納がないように、各学校で請求をしております。私どもとしては、給食費について滞納がある場合は、あらかじめ差し引いて支給をするです。","id":"exchange-038"},{"speaker":"高橋委員","kind":"質問","question":"それ以外については、今、把握されていないということですが、それは調べていなくて把握できていないのか。それとも、区として、そこを調べる権限がないということなのか尋ねました。","respondent":"和氣学務課長","answer":"校長先生の口座に振り込んで、滞納を差し引いて、残りをお渡しする。ですから、そういう意味で言いますと、就学援助の目的にちゃんと使っていただけるように、私どもも適正な管理をしているです。","id":"exchange-039"},{"speaker":"高橋委員","kind":"質問","question":"今、ちょっとお話がありましたが、就学援助費については、きちっと支払われているということですね。その集めた会計については、私費会計ということだと思いますが、ちょっとこの私費会計についてご説明いただけますか尋ねました。","respondent":"和氣学務課長","answer":"私費会計という形で、例えば教材費であるとか、各学校で徴収をしております。その歳入、歳出については、厳しく管理をしています。","id":"exchange-040"},{"speaker":"高橋委員","kind":"質問・要望","question":"その私費について、例えば小学校、中学校それぞれ、年間幾らぐらいになるのでしょうか。横領というのでしょうか、使ってしまうような事件があったと伺っていますが、その観点でご説明ほしいと求めました。","respondent":"和氣学務課長","answer":"私費としていただいている金額は、平均ですけれども、小学校１年生で言いますと、年間で５万５,５５０円です。８年生が９万５,０００円で、９年生になりますと、１７万円という金額になってあります。","id":"exchange-041"},{"speaker":"高橋委員","kind":"質問","question":"今、それぞれ金額をいただいたんですが、学校全体で大変な金額になるということですので、今、校長先生の決裁もあるということでしたけれども、学校の私費会計全体として、監査といいますか、そういうチェックする仕組みはどこかにあるのか尋ねました。","respondent":"和氣学務課長","answer":"ですから、その段階で、何がどう使われているということがわかるような仕組みにしていますので、大丈夫かと思います。さまざまな事務改善とかを進めていますが、会計について調査をして、改善すべきことがあれば改善するというような取り組みもしています。","id":"exchange-042"},{"speaker":"高橋委員","kind":"質問","question":"お伺いしたんですが、その手当の点と、人材の確保の点についてお願いします。","respondent":"和氣学務課長、冠木指導課長","answer":"手当ですが、クラブ活動については、実技指導補助員ということで、１回４,０００円をお支払いさせていただきまして、平成２１年度の実績で言いますと、延べ１,５５１日分配置をしています。 小中一貫で、あるいは、中学校の合同部活動というようなところで対応をしています。なお、東京都から出ている日曜日等の部活動については、１日、１,７００円と聞いております。","id":"exchange-043"},{"speaker":"高橋委員","kind":"質問・要望","question":"区のほうで上乗せをしたりして、人材確保をしていただいて、中学校の部活動のさらなる充実を図ってほしいと求めました。これは要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"藤原委員","kind":"質問","question":"１７６ページ、図書館経費、１８０ページ、学校図書館、１８１ページ、給食調理業務代行委託について、お伺いします。図書館についてお伺いしますけれども、今後の図書館のあり方について、お伺いしたいんです。","respondent":"小川品川図書館長、和氣学務課長、田村庶務課長","answer":"ご指摘の図書館の貸出がなぜ増えているかですが、品川区立図書館に限ったことではなく、全国的に、図書館の貸出冊数は増えているという状況です。… 調理代行ですが、いま、順次、進めているところですが、最終的に、平成２５年度ですべての学校について終了すると考えています。そこは答えしますが… その分、調理代行にかわるということで、平成１７年度から調理代行に進みまして、平成２４年度で一応完結する予定で進んでいます。","id":"exchange-045"},{"speaker":"藤原委員","kind":"質問","question":"それから、給食代行なんですけれども、コスト、わかりませんというのは、せっかく小さな区役所、大きな効果ではないですか。プラス質実剛健なんですから、決算で、コストはこうなりますということを言っていただければいいんですけれども、でも、もういいです。","respondent":"小川品川図書館長、和氣学務課長","answer":"今年８月から、武蔵小山の行政サービスコーナーのサービスに上乗せした形で、図書サービスを開始させていただいたものです。今後、そういった利用の仕方の図書館利用者に利便性が図れるという面で、検討しています。 失礼しました、数字が出てまいりました。１校当たり２,０００万円なんですが、平成１６年度、３億３,０００万円ほどのコスト削減につながっているです。","id":"exchange-046"},{"speaker":"藤原委員","kind":"質問・要望","question":"これは要望になるんですけれども、質を下げないで、よろしくお願いいたします。この辺のコストについて、今後の運営でどのように考えているか、答えるよう求めました。","respondent":"小川品川図書館長","answer":"それ以前には、多いときに、常勤以外も含めまして１７０名弱いる時代もございました。図書館は、これまでも年々、そのように見直しを実施しておりまして、今後も、そういった見直しを図っていきたいと考えています。","id":"exchange-047"},{"speaker":"藤原委員","kind":"質問・要望","question":"見直しできるところはしていっていただきたいと思うんですけれども、その内容等もちゃんと精査して、その辺はよろしくお願いしたい。それから、もっとダイナミックに何か施策ができないのかという思いもあるんですけれども、今後の展開として何かお考えがあるなら説明を求めました。","respondent":"小川品川図書館長","answer":"品川図書館からの学校図書館の支援ですが、平成１７年度から５年かけて、学校図書館の環境の整備を図ってまいりました。まずは、平成２１年度に全校がスタートラインに立ちましたので、その状況を着実に根付かせることがまず肝心だと考えております。","id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問","question":"１７６ページの特別支援教育費と、１７５ページ、プラン２１推進事業で、学校選択制のことをお伺いします。数はここまでなんですが、それから、介助員、学習支援員、どのような基準で配置されているのか説明を求めました。","respondent":"冠木指導課長","answer":"学習支援員、まず通常学級へ学習支援員を配置した数ですが、中学校は４名です。義務教育９年間が終わったところで、一つ特別支援教育の目標にしていますので、日にちを減らしたりというような対応をしています。","id":"exchange-049"},{"speaker":"飯沼委員","kind":"質問・要望","question":"教員から、発達障害に該当するような子どもがクラスに３人ぐらいいると、もう授業が大変な状況になるといった声も伺っているんです。個別指導計画とか、教育支援計画、このような子どもに対しても一人ひとり計画が立てられているのかどうか説明を求めました。","respondent":"冠木指導課長","answer":"実際に多動の状況が出てしまって、とても担任が対応し切れないというようなケースも、一つのケースですけれどもあります。そういった意味で、介助員、学習支援員については、総合的に判断をして配置をしています。","id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これは要望にしておきますけれども、どうぞよろしくお願いいたします。成果報告書の５６ページに、まずはじめに、学校選択制の評価についてお聞かせほしいと求めました。","respondent":"和氣学務課長","answer":"そしてまた、保護者の教育に対する関心を喚起しながら、学校自身が変わる大きな動機づけになった。その意味で、学校選択制が今も教育の現状を変える大きな力を果たしたと評価しています。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問・要望","question":"「何のメリットがあるんですか」と反対に聞かれた、この声は、１人や２人ではないんです。それからもう１点、地域からの声を真摯に受けとめてほしいのですがいかがか尋ねました。","respondent":"和氣学務課長","answer":"そういうことに対する認識が非常に弱かったり、今、模索をしています。それをさらに広めながら、品川区全体として、どう学校と地域がかかわっていくのか、そのことをさらに進めてまいりたいと思ってあります。","id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問","question":"平成２２年度のアンケートの結果が、どう変化しているのか。地域に対する反発ばかりではなくて、質問に答えてください。","respondent":"和氣学務課長","answer":"その数字でも、６０％となっています。そういう広報を抑えていたところもありますので、改めて、いろいろ考えてまいりたいと思います。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問・要望","question":"学校が地域の学校でなくなっている、学校選択制が子どもと地域との分断を進めているという考えがあるんですが、これについていかがでしょうか。１０年が経ちましたので、見直しを求めますがいかがか尋ねました。","respondent":"和氣学務課長","answer":"聞いたことがありませんし、「そうでしょう」とか、「そう思われる」ということしか書いてないんですね。逆に言ったら、今まで放置されて建前で格差と言われたことをしっかりとなくしていくということを、私どもはやっているということです。","id":"exchange-054"},{"speaker":"山内委員","kind":"質問・要望","question":"私からは、１７３ページの教育総務費の中から、事務局費と、それから教育指導費のあたりでお伺いさせてほしいと求めました。昭和３９年生まれ以降の方といったことがあるかと思うんですけれども、まず、それをお伺いさせてください。","respondent":"冠木指導課長","answer":"３期生の募集というところで、新卒者、要は教員免許取得見込みの方から受験できるという形にしています。経験者のほうは、昭和４２年４月２日以降に、というような具体的な年齢をお示ししています。","id":"exchange-055"},{"speaker":"山内委員","kind":"質問","question":"それから、固有教員の給与の基準といったものは、どういった形なのか。そのあたりをお伺いしたいと思います。","respondent":"冠木指導課長","answer":"都費の教員も区費の教員も同じ学校で働くですので、基本的に、都費の教員の給料表を横引きする形でやらせていただいているところです。臨時的任用教員の採用予定を１０名と、選考の過程で３名の採用となったもので、その差が出てきているものです。","id":"exchange-056"},{"speaker":"山内委員","kind":"質問","question":"予算書を見ますと、固有教員５人と出ていて、１年間任用教員が１０名と出ています。副校長といったところの管理職につける見込みで、教育委員会としましては、何かと支えていくのかといったところをお伺いさせてください。","respondent":"冠木指導課長","answer":"区の固有教員については、品川区の教育施策を十分に理解してというようなところで採用している教員です。優秀な資質、能力のある者を採用していますので、将来的には、そういった道も開けるように、今後、整備等をしていくという考えです。","id":"exchange-057"},{"speaker":"山内委員","kind":"質問","question":"１年間任用の先生というのは、１年間任用でそちらに赴任をしていただく、そういった形だということを伺っているんです。派遣研修をされた方は、平成２１年度は３名といったことで、それに対して補充が３名だったといった認識でよろしいのか尋ねました。","respondent":"冠木指導課長","answer":"平成２１年度に実施しました１年間任用教員の考え方としては、区内で、１年間任用教員を発令していくという考え方が一つあります。当初の考え方としては、そこで育てて固有教員の道も開いていこうという考えも、一方でございました。","id":"exchange-058"},{"speaker":"山内委員","kind":"質問","question":"そうしますと、１年間任用で採用された先生は、後々、区の独自採用といった形で試験を受けていただいて、区の固有教員になられるといった道を開くといった考えでいいんか尋ねました。","respondent":"冠木指導課長","answer":"現実に１名が、１年間任用教員から、めでたく合格したというケースはあります。この１年間任用教員の考え方というのは、平成２２年度に向けては、１年間任用という教員の制度は持っておりません。","id":"exchange-059"},{"speaker":"山内委員","kind":"質問・要望","question":"そのあたり、二つ、教えていただきたい。大体どれぐらいで、今、何名ほどで相談を受けているのかといったところをお伺いさせてください。","respondent":"冠木指導課長","answer":"金額の内訳といいますか、主な支出ですけれども、私ども、教育心理相談員ということで、教育センターのほうに７名の職員を配置しています。教員が教育相談的な力量を高めていくということで、教育相談の研修をやる折に、その講師謝礼という形で支出をしているです。","id":"exchange-060"},{"speaker":"山内委員","kind":"質問・要望","question":"相談が延べ２,９２１件、これは１グループの方々が複数回相談をされているといったことになるのでしょうけれども、そういった相談の内容なのか。教員も来るのか、生徒本人が来るというのはちょっと考えられないのかなと思うんですけれども、そのあたりもちょっと教えてほしいと求めました。","respondent":"冠木指導課長","answer":"要は中学生、高校生のみという形で相談にお出でになる方はほんの少しでございまして、平成２１年度については４ケースです。ほとんどは、保護者、お父様、お母様と一緒の相談ということになってあります。","id":"exchange-061"},{"speaker":"山内委員","kind":"確認","question":"わかりました。最後に確認ですが、教員からの相談というのは、ここでは受けないのか尋ねました。","respondent":"冠木指導課長","answer":"区費でスクールカウンセラーを週に１回配置していますので、そちらのほうに、教員のほうは相談するケースが多うあります。","id":"exchange-062"},{"speaker":"山内委員","kind":"質問","question":"最後になりますけれども、ちょっとこれはここの教育指導のところに入ると思うんですけれども、ゆとり教育について伺いたいと思います。もしあればですけれども、生徒、教員、保護者の反応、そのあたりを伺いたいと思います。","respondent":"冠木指導課長","answer":"土曜日授業については、日数の多少はありますけれども、全校で実施しています。保護者、それから子どもたちの評判も上々です。","id":"exchange-063"},{"speaker":"阿部委員","kind":"質問・要望","question":"その辺の情報共有の体制がどうなっているのか、教育委員会の情報というのはなかなかそっちには行かないのかなと思って伺ってみます。質問させていただきたいんですが、どういったくくりになっているのか、教えてほしいと求めました。","respondent":"冠木指導課長、和氣学務課長、吉岡保育課長","answer":"固有教員の年齢ですけれども、採用時の年齢ということで、今、８名採用していますが、２０歳代が４名、３０歳代が１名、４０歳代が３名です。前回のインフルエンザの流行に絡みまして、医師会のほうからも、学校の情報をちゃんと提供してほしいという要望がございました。毎週１回… ５行目、６行目、保育士等非常勤職員経費および育児休業等代替人材派遣委託等というところに介助員の経費が入ってあります。","id":"exchange-064"},{"speaker":"阿部委員","kind":"質問・要望","question":"これだけ項目が違うとなるとどうなんでしょうか、幼稚園と保育園、あるいは私立と公立で随分違ってくるものなのでしょうか。それ以前に、仕組みとして、大きく異なるところがあるのか尋ねました。","respondent":"冠木指導課長、吉岡保育課長","answer":"これから進めてまいりますけれども、若手も採ってまいりますし、バランスは考えてまいります。 幼稚園の場合で大体一人当たり１００万円ちょっと、それから、保育園の場合で大体１２０万円ちょっとぐらいかなと考えています。それから、私立幼稚園については、子ども一人当たり１０万円という基準で補助をしています。","id":"exchange-065"},{"speaker":"阿部委員","kind":"質問","question":"３０人しかいない中で、採用はないわけですから、ご留意ほしいと求めました。人に対してつけるか、クラスに対してつけるかというのは、支援の考え方としては異なってくると思うんですけれども、なぜ、違うのか尋ねました。","respondent":"吉岡保育課長","answer":"それからもう一つ、私立幼稚園の補助金は、一人当たり１０万円ではなく２０万円です。あくまでも幼児教育ということになりますので、やはり一人ひとりの子どもにつく必要がある場面が多いと考えているところです。","id":"exchange-066"},{"speaker":"阿部委員","kind":"質問","question":"これは、過去からの経緯なのか、現在の保育や教育に合わせて考え出されたもので、今の違う状態がベストだと考えているのか。それとも今後、何か合わせていく、あるいはよりよい支援の仕組みを考えていくということなのか、その辺はどうお考えか尋ねました。","respondent":"吉岡保育課長","answer":"何回も申し上げておりますけれども、その辺の今までの経過の中で、そういう対応の仕方をとってきたということです。特別支援のあり方についても、今後につきましては、よりよい方向があれば検討してまいるです。","id":"exchange-067"},{"speaker":"阿部委員","kind":"質問","question":"そもそもやっぱり、幼稚園でも保育園でも同じような考え方で接していきましょうというときに、やっぱり一度見直してほしいと思います。どうでしょう、例えば、つけるときの判断基準みたいなものも違いがあるのか尋ねました。","respondent":"吉岡保育課長","answer":"その辺のところの違いは、今の時点では、どうしてもあるだろうと思っています。教育をというのは品川区の考え方ですから、その考え方の中で、それについては追求してまいりたいと考えております。","id":"exchange-068"},{"speaker":"阿部委員","kind":"質問・要望","question":"見直しの方向についてまでは、私から要望を申し上げますと、やはり支援することを第一ステップにしてほしいんです。親に同意を求めるといったことは、保育園でも、進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"山路委員","kind":"質問・要望","question":"１点目は、１７４ページ、生徒指導対策費に関連をいたしまして、職業体験について、２点目は、１７６ページ、図書館経費について、お伺いいたします。特に教育委員会のほうでお伺いした中で、効果のある、生徒が非常に喜んで成果が上がっているものがあったらお知らせほしいと求めました。","respondent":"冠木指導課長","answer":"中学生の職場体験、職業体験につきましては、全校で中学校２年生を対象といたしまして実施をしています。実施期間については、１日から３日程度ということでやってありますけれども、おおむね好評にやらせていただいているです。","id":"exchange-070"},{"speaker":"山路委員","kind":"質問","question":"小学生の段階から導入していこうという研究が行われていることをちょっとお伺いしたんですが、あるいは、品川区の考えがあったらお伺いいたします。","respondent":"冠木指導課長","answer":"もう既に小学校段階からの職場訪問とか、職場体験という活動を、市民科などを中心に取り入れしています。それから、スチューデント・シティということでやらせていただいているところです。","id":"exchange-071"},{"speaker":"山路委員","kind":"質問・要望","question":"こういうものがだんだん話題になってくると思いますが、品川区でもぜひ検討して、先行してモデル事業に取り組んでいただきたいとお願いしておきます。読書の秋ですから、取り組みについて、現時点での評価をお伺いいたします。","respondent":"小川品川図書館長","answer":"１０月が秋の図書館フェアということで、一般向けには講演会を催したり、児童向けには人形劇などを実施したところです。日ごろより、各図書館で週に一度は読み聞かせを実施するなど、きめ細かく読書の利用に向けての活動に取り組んでいるところです。","id":"exchange-072"},{"speaker":"山路委員","kind":"質問","question":"非常に図書館は頑張っていらっしゃるということで、私のほうも、地域の方から評価のお話をお伺いしているわけです。もう１点大事なことは、この辺については、どのような対応をされているのかお伺いいたします。","respondent":"小川品川図書館長、冠木指導課長","answer":"蔵書に関しましても、約６００点ほどのデイジー図書、雑誌を所蔵しています。郵便サービスというものを実施しておりまして、事前に登録をしていただいた利用者に郵送等のサービスをしています。メディアリテラシーの向上につきましては、私ども市民科の中で、情報モラル教育というようなところで進めているところです。","id":"exchange-073"},{"speaker":"山路委員","kind":"質問","question":"もう１点、図書館司書など、どのようにして人材育成をされているか。この点についてお伺いいたします。","respondent":"小川品川図書館長","answer":"ボランティア養成講座等を毎年実施しておりまして、個人的に活動をされたいというような方の育成にも努めているところです。司書の資格がなくても、そうした職員の意気込みを代々と受け継いで、つなげていきたいと考えています。","id":"exchange-074"},{"speaker":"山路委員","kind":"意見","question":"もう１点、読書アドバイザー、どういうところでアドバイスをやられているのか、またどういう形で人材育成をやられているのか、聞かせてくださいとの意見を述べました。","respondent":"小川品川図書館長","answer":"図書館の職員と、それから窓口業務を委託しておりますスタッフも、一義的にはレファレンスができることになっております。東京都や国で研修もしていますので、そちらに積極的に参加をさせ、力を蓄えていくように努めているところです。","id":"exchange-075"},{"speaker":"井桁委員","kind":"質問","question":"小１問題・中１ギャップの予防・解決のための教員加配についてと、１７５ページの教育指導費の中の小中一貫教育推進経費で、お伺いいたします。時間がありましたら、１７５ページ、下になるんですが、学習支援ボランティア経費について、お伺いいたします。","respondent":"冠木指導課長","answer":"品川区のほうに渡していただけるように、引き続き、東京都と国のほうに要望してまいりたいと思ってあります。","id":"exchange-076"},{"speaker":"井桁委員","kind":"質問","question":"小１問題・中１ギャップの予防・解決のための教員加配についてお伺いいたします。小学校が何校なのか、中学校が何校なのか、それから、どのような形で加配をされたのか、お伺いしたいと思います。","respondent":"和氣学務課長","answer":"現在、品川区で加配対象になってありますのが、小学校が３校、中学校は２校です。基本的に、クラス増という形で対応しています。","id":"exchange-077"},{"speaker":"井桁委員","kind":"質問","question":"小学校が３校、中学校が２校、要は、全小学校、全中学校とも学級規模の縮小の選択をされたということでよろしいですね。区として、チームティーチングに関する考え方、取り入れの可能性というのをお伺いしたいと考えています。","respondent":"冠木指導課長","answer":"これは、今後も、そういうような形になってくるのかなと思ってあります。品川区としても非常に成果を上げておりますので、少人数指導についても十分に成果が上がっている事業ですので、進めてまいりたいと思っています。","id":"exchange-078"},{"speaker":"井桁委員","kind":"質問・要望","question":"ぜひ、子どもたちに合った指導方法を、現場と教育委員会のほうとしっかりと連携をとってやっていっていただきたいと考えています。３年間の検証と聞いておりますけれども、やはり区独自という考え方は、今のところおありか尋ねました。","respondent":"和氣学務課長","answer":"一つ、先ほどの回答ですが、小学校を３校とお答えしたんですが、予定が３校で実際は１校です。それも含めて、全体の教育が充実するように、教員の引き続きの増員を要望してまいりたいと考えています。","id":"exchange-079"},{"speaker":"井桁委員","kind":"質問・要望","question":"そこのところをちょっとお伺いしたいと思います。５校程度、もしくは６校だと思うんですが、そのあたりをお伺いしたいと思います。","respondent":"冠木指導課長","answer":"小中一貫教育の取り組みですけれども、施設一体型は４校ありますけれども、１５のグループで小中一貫教育の取り組みを進めているところです。","id":"exchange-080"},{"speaker":"井桁委員","kind":"質問・要望","question":"１５のグループで取り組んでいらっしゃるということなんですが、現在、お考えなのか。学区を変えたことがあるのか、どのような基準で決められたのか、そういったところがちょっとわかれば教えてほしいと求めました。","respondent":"和氣学務課長","answer":"それからずっと経過をしまして、既に子どもたちは２分の１まで減っておりますけれども、今のところは考えております。今のところは、抜本的に変えるということは考えておりません。","id":"exchange-081"},{"speaker":"井桁委員","kind":"質問・要望","question":"ちょっとお伺いをしたいんですが、第２順位のところで特例といいましょうか、このような特例が今まであったのかどうか。例えば荏原平塚学園のときであったりとか、そういったときにも、このようなことがあったのかどうかということをちょっとお伺いしたいと思います。","respondent":"和氣学務課長","answer":"やったという話は聞いておりますけれども、それは随分昔の話で、最近は全くございません。今回は、少しでも周辺の学校に行っていただければということで、こういう特例の措置をとらせていただきました。","id":"exchange-082"},{"speaker":"井桁委員","kind":"質問・要望","question":"この質問は以上で終わります。そういったような試みというのは、やられていますか尋ねました。","respondent":"冠木指導課長","answer":"学習支援ボランティアについて、支出の対象となっているのは３校ですけれども、そういうところはどしどしと学校教育に役立てていただければありがたいと考えています。","id":"exchange-083"},{"speaker":"井上委員","kind":"質問","question":"私からは、１７９ページの学校管理費の学校運営費と、１８１ページの学校給食費、１７４ページ、教育センター運営費についてお伺いいたします。どういうふうな算定基準で各学校に支給されているのかということと、児童数の一番少ない学校と一番大きなところでの金額を説明を求めました。","respondent":"和氣学務課長","answer":"冨士見台中学校が一番小さくて、８８５万２,６８０円ということになります。それはもちろん学級数、児童数で、教材費なんかが大きく違ってまいりますので、このような差が出ていると考えております。","id":"exchange-084"},{"speaker":"井上委員","kind":"質問","question":"そういう予算の中で、今、アレルギー症状を有するアトピー性皮膚炎の子どもたちは、大変増加傾向にあるというデータがあるわけです。角餅石けんというのが、区内でも利用している学校がありますが、教育委員会ではそのことを把握されていますか尋ねました。","respondent":"和氣学務課長","answer":"基本的に、石けんはそれぞれ学校で買っておりまして、さまざまな石けんを買っている、特にインフルエンザ以降、いろいろな石けんを買っているという話は聞いております。","id":"exchange-085"},{"speaker":"井上委員","kind":"質問・要望","question":"養護教諭や学校が、子どもへのリスクに敏感に取り組もうとしても、なかなか難しいという状況があるわけです。指定成分の入っていない無添加石けんの普及に、教育委員会として推奨するという形で取り組んでいただきたいと思うんですがいかがか尋ねました。","respondent":"和氣学務課長","answer":"インフルエンザで手洗いの励行というのが始まりますので、今、委員のご指摘も含めまして、子どもに最良な環境を保障していくのが私どもの役割ですので、さらに研究を進めてまいりたいと考えています。","id":"exchange-086"},{"speaker":"井上委員","kind":"質問・要望","question":"ぜひ、正確な情報で、ハイリスクの子どもたちに気を配るということを、教育委員会のほうで進めていただくということを要望したいと思います。低農薬であることや学校給食用の野菜として適切かどうかという生産過程を、だれが、どのような方法で確認に行っているのかお伺いいたします。","respondent":"和氣学務課長","answer":"もちろん低農薬の野菜を使うということで徹底しておりますので、各学校は、子どもたちの健康に被害がないように慎重に選んでいるところです。","id":"exchange-087"},{"speaker":"井上委員","kind":"提案","question":"そういった食の安全について、生活者ネットワークは、ずっと学校給食の食材規格書の作成を提案してまいりました。同様に提案をしたところ、文部科学省が定めた基準、それはどのような基準だということでおっしゃっているのか具体的にお示しくださいとの意見を述べました。","respondent":"和氣学務課長","answer":"基本的に、文部科学省のほうから基準表がきておりまして、それに基づいて、栄養価だけではなくて、安全についても管理をしなければならないとなっていますので、そういう意味では、それをしっかりと励行しています。","id":"exchange-088"},{"speaker":"井上委員","kind":"質問・要望","question":"ですから、しっかりと、学校給食の関係者も、給食調理者も、保護者にもきちんとわかる給食用物資の規格基準というのはやはり必要だと思います。こういった項目で対応していますということで、改めて、食材規格書を明文化させてつくっていくべきだと思いますので見解を伺います。","respondent":"和氣学務課長","answer":"これまでも学校給食法に基づきまして、衛生管理基準の徹底をしてまいりました。そういう具体的なことも含めまして指示をしていますので、しっかりと保護者にもどんな食材を使っているかというのは説明できるかと思ってあります。","id":"exchange-089"},{"speaker":"井上委員","kind":"質問・要望","question":"関係者の方々の意見を合わせて、ぜひ、前向きに進めてほしいと求めました。参考までにお伺いをするんですけれども、今後、学校給食に取り入れていこうとする考え方はおありか尋ねました。","respondent":"和氣学務課長","answer":"今、そうした動きが世の中で進んでいることもよく承知していますので、それも含めて、確実に安全である、正体がわかる食材をしっかりと購入していくように努めてまいりたいと考えています。","id":"exchange-090"},{"speaker":"井上委員","kind":"質問・要望","question":"７１８件についての内訳をお伺いいたしましたので、当然、有資格者であると思いますのでどういう方々なのかお伺いいたします。どういうふうに対処されたのかということがちょっとなかったので、私は、その辺をお伺いいたしたいと思います。","respondent":"冠木指導課長","answer":"教育相談の具体的な中身についてのご質問ですけれども、先ほど、その１１０ケースの中で学校の相談というのが４５％を占めているところです。","id":"exchange-091"},{"speaker":"井上委員","kind":"質問・要望","question":"クラスの中で一人でいる子への目配り、気配りが、教師には求められていると思います。決して珍しいことではないと思いますので、この事件の後に、品川区の教育委員会と学校はどのような対応をしたのかお伺いいたします。","respondent":"冠木指導課長","answer":"今、虐待等を含めまして、子どもの状況についてのアンケート調査を即刻実施するようにということで通知をしたところです。学校が把握するという取り組みをしているんですけれども、少し前倒ししまして、重点的に指導を徹底するようにということで通知をしたところです。","id":"exchange-092"},{"speaker":"井上委員","kind":"質問","question":"実際に、昨年度、不登校の児童生徒、この中で３２名が適応指導教室へ通っていたということです。平成２１年度は、３２人中何人の子どもが復帰をされたのか、現状をお伺いします。","respondent":"冠木指導課長","answer":"基本的に、９年生が１０名在籍をしておりまして、９年生についてはすべて上級学校への進学を果たしています。それから、９年生ではなくて、７年生、８年生の中で６名が学校への復帰を果たしております。","id":"exchange-093"},{"speaker":"井上委員","kind":"質問","question":"区や学校として認めていくという柔軟な対応もあってもいいと思うんですが、そのことについて見解を伺いたいと思います。もう１点、第三者的な子どもの救済の場も必要と思うんですけれども、それについても見解を伺います。","respondent":"冠木指導課長","answer":"スクールカウンセラーの対応、マイスクール八潮の対応ということで、対応してまいりました。この辺が家庭を訪問するような取り組みなども、今、検討しています。","id":"exchange-094"},{"speaker":"堺委員","kind":"提案","question":"それから、時間がございましたら、同じ１７５ページ、一番最後にあります、すまいるスクールについて、確認をしておきたいと思います。平成２０年の第１回定例会の代表質問の際に、教育委員会として全面的に支援をしていただきたい、こういう提案というか要請をしたところですとの意見を述べました。","respondent":"冠木指導課長","answer":"分離型の小中一貫教育校、これは品川区もそうですけれども、全国的に見てもたくさんあります。連携のさらなる推進のあり方などについて、それぞれの課題について出し合い、検討したところです。","id":"exchange-095"},{"speaker":"堺委員","kind":"確認","question":"ねらいということで教えていただきましたが、７月ですから、どのような検証をされたのか。要するにねらいどおりの成果が上がってきつつあるのかどうか、その辺を含めて確認をしておきたいんですが、お願いします。","respondent":"冠木指導課長","answer":"距離は離れていても、あるいは取り組みが必要なんだろうかというようなところで、たくさんのご意見をいただいたところです。新たな発展のためにどういうふうに品川区で進めていったらいいかということで検討を進めているところですけれども、今回のサミットの意見については。","id":"exchange-096"},{"speaker":"堺委員","kind":"質問","question":"１０月１９日付の「都政新報」に、区長のインタビュー記事が出ています。今後の施設分離型が取り組んでいかなければならない課題等について、どのように取り組んでいかれるのか、その辺をちょっと教えていただけますか。","respondent":"冠木指導課長","answer":"方針も、同じ考え方をもとに指導計画をつくることだというところが、教訓を得たところでもあります。今現在、小中一貫教育を進めるために、指導計画をつくるべく、作業を進めているところです。","id":"exchange-097"},{"speaker":"堺委員","kind":"質問","question":"子どものために、今どうあるべきかということを、絶えず念頭に置きながら積極的に進めていってほしいと求めました。２点目に、これは、その各校の参考になるような事例がございましたら教えていただけますか。","respondent":"冠木指導課長","answer":"いろいろな取り組みがあるんですけれども、実技を伴った指導をしていただいたりというようなところで、地域の人々の教育力を生かしています。","id":"exchange-098"},{"speaker":"堺委員","kind":"質問・要望","question":"８年生を対象にして、社会が求める資質と能力ということで、人生観を構築する機会とする。さまざまな取り組みをされているというお話を伺いましたけれども、それぞれ各学校、この辺についての取り組みについてちょっと教えていただけますか。","respondent":"冠木指導課長","answer":"東京寺子屋授業ということで、商工会議所等々のご支援をいただきまして、大崎中学校が実施したものです。今後も、そういった取り組みを進めてまいりたいと思ってあります。","id":"exchange-099"},{"speaker":"堺委員","kind":"確認","question":"真剣に聞いているというのですか、何とか自分のものにしようというのでしょうか、そういう意欲があらわれているというのでしょうか。そういう意味で、非常に効果があるのではないかという思いから、確認をさせていただいた次第です。","respondent":"冠木指導課長","answer":"先ほどの私の答弁で間違いがございましたので、１点、訂正をします。学校の中の校務分掌で責任のある立場についていただいて、仕事をしていただけるように、私どももバックアップしています。","id":"exchange-100"},{"speaker":"南委員","kind":"質問・要望","question":"学級編制について伺いたいと思います。その基本的なところをまず教えてほしいと求めました。","respondent":"和氣学務課長","answer":"学級編制につきましては、それぞれの学校における子どもたちの数を、年に何度か推計いたしまして、それに基づいて、何クラスになるかということで、東京都のほうに報告をして、最終的には、４月１日現在の数で確定をいたします。","id":"exchange-101"},{"speaker":"南委員","kind":"確認","question":"学校選択制もある中で、最終的な確認は４月１日だというお話なんですけれども、なかなか大変かなと率直に思います。そういうところの困難は、どういうふうに教育委員会は考えているんか尋ねました。","respondent":"和氣学務課長","answer":"これは、どちらにしろ、直前に転勤が決まったりとかで、転入、転出、そういうこともあります。特に数が４０人ぎりぎりの場合については、日常的に連絡を取りながら、数を押さえているところです。","id":"exchange-102"},{"speaker":"南委員","kind":"質問・要望","question":"しかし、それは大きな数ではないですから、そういう対応は、ずっと昔からやってこられたことだと思います。その教員配置、これとの関係でどういうふうになったのか、あわせて伺いたいと思います。","respondent":"和氣学務課長","answer":"すみません、何をお聞きになりたいのか、ちょっとわからないところがあるんですが、先ほどの回答は、井桁委員に回答したように、小学校では１校が対象になり、中学校では２校が加配対象になったです。","id":"exchange-103"},{"speaker":"南委員","kind":"意見","question":"それから、平成２２年度についてということで聞いたんです。そういうふうに言いましたよ、ちゃんと聞いてくださいとの意見を述べました。","respondent":"和氣学務課長","answer":"平成２１年度の学級数が４４７学級という形になっております。中学校については、平成２０年度の学級数が１３６学級で、平成２１年度が１５２学級という数字になってあります。","id":"exchange-104"},{"speaker":"南委員","kind":"確認","question":"そして、１学級何人か、教員配置はどういうふうにされたのか、そこをちょっと伺いたいと思います。最初のところの、３１人以上の児童数のいた学級の状況の確認も含めて、お願いしたいと思います。","respondent":"和氣学務課長、冠木指導課長","answer":"３１人以上の学級がそれだけあるということについては、そういうことでしょうとしか、お答えのしようがありません。平塚小学校のほうが７９人ですので、やっぱり２６人、２７人という数字になってあります。 教員配置につきましては、先ほど、学務課長も説明いたしましたが、東京都のほうの判断が、４月の１週、２週とおくれてまいりますので、期限付の新採ということになってあります。","id":"exchange-105"},{"speaker":"南委員","kind":"質問・要望","question":"期限付の新規採用というのは、ちょっとどういうことなのか、説明していただきたいんです。何月から何月まで採用されるとか、そういうことを教えていただかないと、判断ができませんのでお願いします。","respondent":"冠木指導課長","answer":"期限付の新規採用教員でございまして、１年間の任用ということになります。４月１日から翌年の３月３１日までの任用ということになります。","id":"exchange-106"},{"speaker":"南委員","kind":"質問・要望","question":"間違いだったら教えていただきたいんですけれども、品川区で言うと７年生もそうだと思うんですけれども、そことの関係で生かされていくのかどうか。この東京都の制度の効果を、教育委員会としては、どう評価しているのか、こういう制度の評価について伺いたいと思います。","respondent":"和氣学務課長","answer":"小学校のほうは、１、２年でそのまま継続ですが、中学校は、１年限りだと思いますので、数が変われば変わっていくと考えています。国に対して、教員をさらに充実させてほしいという要望はしておりますので、教員が充実することについてはいいことだとは考えてあります。","id":"exchange-107"},{"speaker":"南委員","kind":"質問・要望","question":"教育委員会自身も要望しているという説明を聞いて、そうではない判断であれば、それはそれで後で言ってほしいと求めました。そういう点で、改めて、少人数学級、とりわけ３０人以下の人数で授業が受けられるような環境整備を、ぜひ、していただきたいと思っているんです。","respondent":"和氣学務課長","answer":"常にお答えしているように、学級の数が減れば教育が充実するというような単純なものではないと私どもは考えてあります。例えば特別支援をどうするかとか、多様な形態で、それぞれの状況に応じた教育を展開してまいりたいと考えています。","id":"exchange-108"},{"speaker":"南委員","kind":"質問・要望","question":"先ほど伺ったのは、要望している、いいことだとおっしゃったではないですか。したがって、もっときちんと子どもにいい教育を与えたいということでやっていただきたいということを、かなり強く強調して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-109"},{"speaker":"大沢委員","kind":"質問・要望","question":"１７５ページの小中一貫教育推進経費、それから、市民科・各教科充実経費、食育研究指定地区事業について、３点、お伺いします。そこの中で、小中一貫教育要領というもの、どのような手続を経て決められていくのか教えてほしいと求めました。","respondent":"冠木指導課長","answer":"カリキュラム検討委員会といいまして、十分な論議を詰めた上で、小中一貫教育要領としてまとめました。今度は文部科学省と十分に吟味をしまして、文部科学省のほうがこれでよかろうというようなことで、私どもの小中一貫教育要領が完成したです。","id":"exchange-110"},{"speaker":"大沢委員","kind":"質問・要望","question":"言うべきことではないんですが、決算特別委員会なので、あえてへ理屈ながらもちょっとお伺いをさせてほしいと求めました。さまざまな教育に精通された方がピックアップしているわけですから、なぜ、ご説明ほしいと求めました。","respondent":"冠木指導課長","answer":"品川区の共通のテーマ、今回の１１月１１日号の広報しながわにも、一つ小中一貫教育要領にも反映しようということで使わせていただいた文言です。","id":"exchange-111"},{"speaker":"大沢委員","kind":"質問","question":"１１月１１号の区の広報で出されるということなんですけれども、私は、自分なりに調べました。個人の尊厳、人間の尊厳と教えないで、人間の尊重ということで子どもたちには教えるわけか尋ねました。","respondent":"冠木指導課長","answer":"実際に子どもたちには、教科書を使って教えるということになります。非常に平易な言葉、子どもたちがわかりやすい言葉で、人間の尊重について説いていきたいと考えております。","id":"exchange-112"},{"speaker":"大沢委員","kind":"質問","question":"小学校６年生、また疑問を感じることもあろうかと思いますので、そこのところをうまくご指導方お願いしたいと思います。それをちょっと説明を求めました。","respondent":"冠木指導課長","answer":"副読本の購入については、「のびゆく品川」、「わたしたちの品川」といった、小学校３年生、それから、中学校７年生で使う社会科の副読本。それから、社会科の地図、東京の地図、その他体育の実技等々の本ということになってあります。","id":"exchange-113"},{"speaker":"大沢委員","kind":"質問","question":"数学に特化しますが、数学では、副読本で問題集みたいなものを教材で配っていないでしょうか。説明を求めました。","respondent":"冠木指導課長","answer":"すみません、答弁が漏れました。算数、数学については、「プラスアルファ」という副教材をつくってあります。","id":"exchange-114"},{"speaker":"大沢委員","kind":"質問","question":"教育委員会ですから、もちろん教育をつかさどっているわけですから、回答のスペースや何かはご存じでしょうか。ちょっとお伺いしたいと思います。","respondent":"冠木指導課長","answer":"今、委員ご指摘の「プラスアルファ」というのは、小中一貫教育で、私どもがつくっている教材ということだと思いますけれども、これについては了解をしています。","id":"exchange-115"},{"speaker":"大沢委員","kind":"質問","question":"それは、数学の問題集ということでいいわけですか。それとも別のものか尋ねました。","respondent":"和氣小中一貫教育担当課長","answer":"例えば５年生、６年生で載っていないものを載せたものですので、問題集ではございません。","id":"exchange-116"},{"speaker":"大沢委員","kind":"質問","question":"今、算数の話をされましたけれども、数学の話で、区内中学校で問題集を使われていませんか尋ねました。","respondent":"冠木指導課長","answer":"「プラスアルファ」というのは副教科書ということでございまして、問題集につきましては、中学校が市販のものを使っている可能性はあります。","id":"exchange-117"},{"speaker":"大沢委員","kind":"質問・要望","question":"それとも、そこに書き込んでしまいなさいとおっしゃっているのか、どちらなのか教えていただきたい。指導方法を教えてほしいと求めました。","respondent":"冠木指導課長","answer":"今、委員のお話は、子どもたちの考える力をどういうふうに育てるかというところかと思ってあります。それから、そういったような指導の仕方をして、成果を上げている学校もあります。","id":"exchange-118"},{"speaker":"大沢委員","kind":"質問・要望","question":"そこのところはばらばらだと、私は思うんです。別にノートを求めるということで、統一的にご指導方、お願いしたいと思うんですけれどもいかがか尋ねました。","respondent":"冠木指導課長","answer":"先進的な研究であるとか、成果を上げている取り組みについては、各学校に発信してまいりたいと思ってあります。","id":"exchange-119"},{"speaker":"西本委員","kind":"質問・要望","question":"現状はどういうふうになっていて、品川区の導入の方向はいかがでしょうか、ということが一つ。これは中学生になるのでしょうか、学校特有ではなくて、学校をまたがっていろいろ問題行動を起こしている中学生が非常に目立ってきています。","respondent":"和氣学務課長、冠木指導課長、田村庶務課長","answer":"私からは、電子黒板について回答させていただきたいと思います。あくまでもツールでしかありませんので、そういう実践例も見ながら… かなり広範囲に問題行動のある児童・生徒への対応というような部分が、ひとつあろうかと思います。現在、生活指導主任会でもそのような対応をしています。プラン２１のＰＲということで、やはりＰＴＡの場合には、毎年、役員も変わるということで、委員ご指摘の部分もあると思います。","id":"exchange-120"},{"speaker":"西本委員","kind":"質問・要望","question":"それが、ＰＴＡ連合会だけではなくて、単体で考えてほしいと求めましたので、その辺はよろしくお願いします。要望です。","respondent":"和氣学務課長、冠木指導課長","answer":"電子黒板のことを含めまして、パソコンの根本的な使い方について、今、改めてプロジェクトチームをつくって検討しています。今、根本的に、学校の先生たちと検討しています。 十分に認識をしておりまして、そういうようなところに非常に足しげく通わせていただきまして、対応をしています。ですけれども、最善の努力をしています。","id":"exchange-121"},{"speaker":"西本委員","kind":"質問・要望","question":"品川区にはいろいろな人材がそろっていますし、団体もおられますので、ぜひ、その人たちの連携を深めていただいて、学校だけでもできない、家庭でもほんとうに助けられないという状況を踏まえて、今後、いろいろ構築してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-122"},{"speaker":"川西委員","kind":"質問","question":"これは、学校評価委員制度のことだと思いますが、目的、そして、委員の選出の範囲、実施してきた成果、改めまして伺います。これについては、予算の分け方、レイアウトや編集の位置づけをどういうふうにしていらっしゃるか、とりあえずここを伺います。","respondent":"冠木指導課長、和氣学務課長","answer":"各学校が実施しております校区外部評価につきましては、この評価を実施することによって、教職員の資質向上。財務の専門家４人から成りまして、これは一遍に全校はできませんので、順番に外部評価を行っているです。 学校案内パンフレットの制作費ですが、各校１３万円ずつを学校に令達して、学校でつくっていただいております。学校の教育内容、教育目的、目標がしっかりわかるものにしてほしいということでお願いをしています。","id":"exchange-123"},{"speaker":"川西委員","kind":"質問","question":"それから、町会長とか、定着して何年もやっていらっしゃる方もいらっしゃると思うんですが、その辺の割り振りを伺います。新１年生になるとか、７年生になるとか、その範囲を超えた配布先を説明を求めました。","respondent":"冠木指導課長、和氣学務課長","answer":"基本的には１年任期でございまして、再任されていく方もいれば、１年間で終了される方もいるです。再任はあるです。 基本的には、学校に置いているところもあれば、いろいろなところに配っている学校もある。それは学校の判断にお任せしています。","id":"exchange-124"},{"speaker":"川西委員","kind":"質問・要望","question":"そういうことで、努力していただけるかどうかということだけお伺いしたいと思います。今、幼稚園向けの校庭となっておりますが、児童数も大変多くなっておりまして、今後の計画について、用地をどういうふうに活用なさるか伺います。","respondent":"冠木指導課長、和氣学務課長、田村庶務課長","answer":"この時期、就学相談をさせていただいておりまして、来年の春に１年生になる方、７年生になる方の相談を受け付けているところです。… 光林荘の映像ですが、例えば新任教諭の研修の中では、もちろんスクリーンとか、プロジェクターとか使っております。… 城南小学校は帯状敷地といいまして、くびれた形の敷地になっているということで、特に具体的な計画があるわけではございません。","id":"exchange-125"},{"speaker":"川西委員","kind":"質問・要望","question":"城南小学校については、５年も、８年も、児童数が少なくならないと思います。こういうくびれている校地を活用して、小学校の建設を考えていただきたいと、地元では思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-126"},{"speaker":"伊藤委員","kind":"質問","question":"私は、１７５ページのプラン２１推進事業に関連をして質問をいたします。１５のグループに入学を予定されている保護者の皆様方に対する説明をする機会をつくっていくとか、私は思うんですが、いかがか尋ねました。","respondent":"冠木指導課長","answer":"新しい教科書も平成２３年４月から始まりますので、小中一貫でどういった取り組みをしていくかという作業を、進めているところです。３月までに、各学校と十分に検討、吟味をしていくということになろうかと思います。","id":"exchange-127"},{"speaker":"伊藤委員","kind":"質問","question":"だけれども、施設分離型については難しいことはわかっているんですけれども、やろうとしたし、やるんですから、検討の段階は過ぎた。２年計画でやっていくとか、そういうことぐらい踏み込んだ答弁をいただけないでしょうか、お願いいたします。","respondent":"冠木指導課長","answer":"鈴ケ森小学校グループも含めまして、今、検討の最終段階にきております。１１月の終わりまでには、それぞれの連携グループから、今年の検討結果がまとまるという段階になっております。","id":"exchange-128"},{"speaker":"伊藤委員","kind":"質問","question":"当然、同じ品川区の小中一貫校として挙げていかなければいけないと思っているわけですから、やっぱり私たちには安心するお話をください。我々としても、小中一貫校のことをいつまでも聞かなければいけないことになるのだから、教育長のお話をぜひ聞きたいと思いますがいかがか尋ねました。","respondent":"冠木指導課長","answer":"作業を進めている指導計画が確固たるものであれば、必ず成果がさらに上がってくると考えていますので、小中一貫教育について進めているところです。来年の教育課程に向けて、今、最善の努力をしています。","id":"exchange-129"},{"speaker":"伊藤委員","kind":"質問","question":"やっぱり日本人ですから、世田谷区で行われている日本語教育ですが、小学校１年生から論語を勉強していることもあった。もともとの日本語教育について、品川区の指導とか、考え方、教育の内容についてお聞かせください、お願いいたします。","respondent":"冠木指導課長","answer":"国際理解教育を進めるうえでも、日本語を十分に知っているということは、非常に大切なことだろうと考えています。品川区においても、そういった視点を忘れることなく、子どもたちの教育を進めてまいりたいと思ってあります。","id":"exchange-130"},{"speaker":"伊藤委員","kind":"意見","question":"だから、ああいう一連のはっきりとした日本語教育を行ったうえで、初めて英語教育等をやるべきだと思うんです。もう一つ踏み込んで、品川区としての、日本語教育の推進の仕方、方向について、もう一つ、大きな考え方をお知らせください、お願いいたしますとの意見を述べました。","respondent":"冠木指導課長","answer":"さらに必要な語彙を理解し効果的に使うようにする。我が国の言語文化を継承し新たな創造へとつないでいく」というふうに明確に記しまして、各学校の教育を進めているところです。","id":"exchange-131"},{"speaker":"伊藤委員","kind":"質問","question":"それから、１７３ページ、学校ＩＴ化推進経費に関連して質問します。説明を求めました。","respondent":"和氣学務課長","answer":"私どもが検討しているのは、今、検討させていただいている最中です。それに伴って、さまざまなシステムについても整備してまいりたいと考えております。","id":"exchange-132"},{"speaker":"伊藤委員","kind":"質問","question":"効果を考えたうえでパソコンを配備するべきであって、どうするか考えるというのは、どうも考え違いのような気がします。これも際限なく議論をしていても意味がないわけですから、期限を区切って、そのことについてのお考えと見通しを説明を求めました。","respondent":"和氣学務課長","answer":"使い道は後から考えるということでは全くございませんで、ほかの区に行ってほんとうに困っているという声をたくさん聞いております。今年度中に方向は出すつもりですので、来年度からまた具体的な使用法、指導法について具体的に進めてまいりたいと考えています。","id":"exchange-133"},{"speaker":"須貝委員","kind":"質問","question":"公教育が学習指導をやるべきなのに、なぜ、通学支援や進学支援を始めたのでしょうか。このようなことは、今の学校教育では学力が定着できないということではないのか尋ねました。","respondent":"冠木指導課長","answer":"それから全国の平均を３ポイントから７ポイント上回るという状況ですし、中学校においても、その成果は上がっております。私どもが実施している品川区の公教育、小中一貫教育は、間違いなく、子どもたちの力、学力を育てております。","id":"exchange-134"},{"speaker":"須貝委員","kind":"質問","question":"その三者面談のときにどうでしょうか、ほかの資料があったら持ってきてください」と、三者面談のときに言うんですよ。学力を教えるところなのに、子どもたち、ああ出て行きます、知りません、でも大半は塾に行っている、こういう現状を見てどのようにお考えか尋ねました。","respondent":"冠木指導課長","answer":"習熟度別学習というのはあるんですけれども、２人いなければ、３人いなければできないというのは習熟度別学習ではございません。どんなオーダーが出てきても、それに親身になって対応していくのが、私ども教員の仕事です。","id":"exchange-135"},{"speaker":"須貝委員","kind":"質問","question":"では、ちょっとお聞きします、なぜ塾に行くんですか。だって、秋田県にかなわないではないか尋ねました。","respondent":"冠木指導課長","answer":"塾に行かせる、行かせないは保護者の判断ですけれども、それはともかくとして、どの子どもにもきちっと学力をつけさせるのが、私ども、品川区の教育です。","id":"exchange-136"},{"speaker":"若林委員","kind":"質問","question":"１７３ページの教育指導費と、１７６ページの特別支援教育費、１８１ページの学校給食費をお伺いします。評価はお聞きましたので、目的をお聞きして、教育委員会としてのご見解を伺いたいと思います。","respondent":"和氣学務課長","answer":"こういう機会に、もう一度、子どもの教育をしっかり考えてもらう。そういう意味でも、学校選択制が教育の活性化、学校の活性化、地域における教育の活性化に直接つながっていると理解しています。","id":"exchange-137"},{"speaker":"若林委員","kind":"質問","question":"そのうえで、午前中にも議論がありましたが、今も一言ありましたけれども、学校選択制が地域にとってどのような影響を与えているか。地域が、この学校選択制をどのようにとらえているか、これを教育委員会としてはどのようにお考えか尋ねました。","respondent":"和氣学務課長","answer":"その一つの例が、防災のポンプを配備して、中学生が地域の中で防災のときにどう生きていくかとか、そういうことを考えたりします。品川区全域で、どう子どもたちがさまざまな地域行事に参加していけるのかということについては、もっと検討してまいりたいと考えております。","id":"exchange-138"},{"speaker":"若林委員","kind":"質問","question":"今、地域の話題を取り上げましたけれども、区長部局のほうの、一方の地域を担当する部署の方にお聞きしたい。一方、課題等もあると思いますけれども、その地域を担当する方のご見解を伺いたいと思います。","respondent":"宮地地域振興事業部長","answer":"学校とも連携しながら、区政協力委員会の場などで、また地域で学校をどう受けとめているかという生の声を聞かせていただいております。品川らしい子どもたちに育てていかれればという意味で受けとめていますし、地域もまた、積極的な受けとめ方をしていると判断しております。","id":"exchange-139"},{"speaker":"若林委員","kind":"質問・要望","question":"そこで、平成２１年度ですから、２年経った現状と課題について、まず、お聞きしたいと思います。なおかつ執行率が６９.７％と低いというふうになっているんですが、何かずれがあるのでしょうか、教えてほしいと求めました。","respondent":"冠木指導課長","answer":"そういうことも含めて、中途での対応というところも、もう少し深めていく必要があるのかなと思っているところです。特別支援教室の補修、当初よりも少ない件数で済んだので、執行率はそうなっていると考えています。","id":"exchange-140"},{"speaker":"若林委員","kind":"質問・要望","question":"もう一つ、平成２１年度の教育委員会事務事業の点検、評価をされました。外部機関との連携も含めた全体としての特別支援教育、これもしっかりと評価をしてほしいと求めましたので、ここら辺の考え方をお願いいたします。","respondent":"冠木指導課長、田村庶務課長","answer":"学習支援員との関係ですけれども、特別支援学級、学習支援員を置く場合もありますけれども。そういう関係機関との連携ですけれども、進めておりますけれども、さらにそういった連携は深めてまいりたいと思ってあります。 私のほうで、教育委員会での事務事業点検を担当していますのでお答えをいたします。平成２２年度の事務事業点検、ご意見があったことを踏まえて、引き続き検討してまいりたいと考えております。","id":"exchange-141"},{"speaker":"松澤委員","kind":"質問・要望","question":"１７４ページのスクールカウンセラー派遣費に関連してクレーマー対策についてと、１７５ページ、すまいるスクールについて、お聞きしたいと思います。この怪物についてわかっていたら、どういうことなのか教えてほしいと求めました。","respondent":"冠木指導課長","answer":"脅し的な部分であったりというようなことで、対応に苦慮する保護者がいるという状況は、私どももつかんでおります。学校で対応し切れなくなると、同じような対応をしてくるというところがありますので、学校でも同じような状況があろうかと考えています。","id":"exchange-142"},{"speaker":"松澤委員","kind":"質問","question":"私の子育てのころは、もう３５年前ですから、そのころでは考えられなかったことが起こっているみたいです。こういうものが出てきた現状、私たちのころには、その辺の原因をどういうふうに分析してとらえているのかについてお聞きしたいと思います。","respondent":"冠木指導課長","answer":"原因と言えるかどうかわかりませんけれども、やはり、親のほうが、子どもを育てる親になり切れていないという状況はあります。ですので、社会の中で子どもを育てていくという認識がない部分については、子どもが小さい段階から指導していく必要はあろうかと考えています。","id":"exchange-143"},{"speaker":"松澤委員","kind":"質問","question":"その辺のことを、しっかりと受け皿というものをつくるべきではないかと思うんですけれども、その辺はいかがか尋ねました。","respondent":"冠木指導課長","answer":"子ども未来事業部の子育て支援課との共同であるとか、そういったような広い視野で、チームワークを組んでの対応が何にもまして必要になってくるのかなと考えています。","id":"exchange-144"},{"speaker":"松澤委員","kind":"意見","question":"思うように野球ができない、サッカーができない、暑い夏に体育館の窓を閉め切ってやっているというようなことがよくあります。そういう騒音、受忍の限度はこんなものですよという形で説得する方向でやっていただいているのか、その辺の考え方をちょっと聞きたいと思いますとの意見を述べました。","respondent":"田村庶務課長","answer":"ハードの関係なので、私のほうからお答えしますが、午前中、砂ぼこりの話がありました。粘り強く説得して、ご理解をいただいて、地域と一体となって学校運営をしていくという形でやっていく以外に手だてはないのかと考えております。","id":"exchange-145"},{"speaker":"松澤委員","kind":"質問・要望","question":"後から、学校があるのを承知してきて、夜勤だからうるさいとか、それぞれ立場はあるんでしょうけれども、粘り強くよろしくお願いします。２点目のすまいるスクールですけれども、初歩的なことですけれども、その政策と内容についてお知らせほしいと求めました。","respondent":"田村庶務課長","answer":"平成１３年度からモデル実施を第二延山小学校から開始しまして、体力、個性の伸長を図るという目的で開始した事業です。","id":"exchange-146"},{"speaker":"松澤委員","kind":"質問・要望","question":"品川区は先駆的に始めて、今、これは２３区で相当広まっているんですよね。各区の状況をちょっとお知らせほしいと求めました。","respondent":"田村庶務課長","answer":"５校ぐらいすまいるスクールの全児童対策というのを取り込んでいる区もありますし、また、全児童対策に取り組んでいる区もあります。ハード的な部分での対応が、趣旨はわかるけれども、なかなか広まりがないというようなところが現状だと思います。","id":"exchange-147"},{"speaker":"松澤委員","kind":"質問","question":"時間がなくなってしまったのですけれども、この中で、学校の授業と連携して、算数、国語の復習を行う勉強会みたいなものをやっているんです。子どもたちを教えているということで、このことは時間がありませんので、また次回に聞きたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-148"},{"speaker":"土井委員","kind":"質問・要望","question":"１７５ページあたりにあるのでしょうか、どうもちょっとと思ったので、確認をさせていただきたいということ。ご質問の内容がそういうことだったから、その面だけをお答えいただいたんだと思うので、確認をさせてほしいと求めました。","respondent":"冠木指導課長、和氣学務課長、金子企画財政課長","answer":"私が答えたのは、自分の考えや判断を効果的に相手に伝える、これが一つです。なかなか現代の子どもたちを育てていくのは難しいかなと思いますので、プラス… そういう中で、経費の縮減もできているです。それ以上に使わせていただいていまして、そのことでさまざまな教育改革を展開し… 都区のあり方検討委員会で検討されてまいりましたけれども、今年５月の区長会総会では、来年度から具体化の検討に入ることを求めていこうという考え方です。","id":"exchange-149"},{"speaker":"土井委員","kind":"質問・要望","question":"ある意味では余力ができたわけですから、給食をやっている学校はどこもしっかりやっていただくということでお願いをしたいと考えています。少し皆さんにやってレベルを上げようというところに使っていただけると、それが見えるといいなと考えていますので、特にお答えは求めません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-150"},{"speaker":"宮崎委員","kind":"質問","question":"第一に、品川地区の小中一貫校の隣地の購入について、今、どうなっているか伺いたい。それから、値段など、わかったら伺いたいと思います。","respondent":"田村庶務課長","answer":"もう５年ほど前に、第一三共側に、文書も含めて働きかけをしてまいりました。まさに学校と接続する土地ですので、民地でも売却の意向があれば、積極的に購入しようということで働きかけしたものです。","id":"exchange-151"},{"speaker":"宮崎委員","kind":"確認","question":"それでいいんですよね、そこを確認したいと思います。ここのところを伺いたいと思います。","respondent":"田村庶務課長","answer":"ただし、もう既に校舎の竣工が来年４月です。校庭として整備して、有効活用を図ろうと、そのような考え方です。","id":"exchange-152"},{"speaker":"宮崎委員","kind":"質問","question":"例えば伊藤学園は非常に狭いという問題を指摘しておりますけれども、こういうことはどういうふうに考えていくのか。教育委員会の考え方を伺いたい。","respondent":"田村庶務課長","answer":"幾つかバランスで考えているのかもしれませんが、現在、買いたいと考えております。そういう意図で購入するものです。","id":"exchange-153"},{"speaker":"宮崎委員","kind":"質問","question":"小学校と中学校を合わせると、およそ１万３,０００m2必要なのに、４,７００m2しかないということなんです。学校設置基準があるということと、隣地があったら買うんだという考え方は、何が基準なのかと思うんですけれども、どうなんか尋ねました。","respondent":"田村庶務課長","answer":"学校の設置基準に該当する校庭を持っている学校は、都市部では、ありません。ほかでは買わないという意向ではありませんから、設置基準に該当するとか、取得の方向ということで考えているものです。","id":"exchange-154"},{"speaker":"宮崎委員","kind":"確認","question":"というふうに私は受けとめをしたんですけれども、そうではなくて、可能だったら買っていくということでいいんですね。そこのところを確認したいと思います。","respondent":"田村庶務課長","answer":"学校と地続きになっている場合に、うまく条件等がすり合えば、取得の方向で考えていきたい。そのように考えております。","id":"exchange-155"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そうすると、この時点でも、いかに改善をしていくのかということが、とりわけ設置者である区長に求められている姿勢だと思うんです。あるいは、ほかの土地を活用するなり、そういう考え方を出してほしいと求めました。","respondent":"和氣小中一貫教育担当課長","answer":"それぞれ例えば既存の学校でも、今までも、浜川中学校は校庭が狭くて、運動会がなかなか校庭でできないということもあります。あえて校庭を狭くしようなんてだれも考えておりませんので、基本的に、その敷地の中で最善の建物を建てて展開をしているです。","id":"exchange-156"},{"speaker":"宮崎委員","kind":"質問・要望","question":"荏原東地区の小中一貫校だってこのままいったら、目に見えているんですから。このことを強く求めて、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-157"},{"speaker":"三上委員","kind":"質問","question":"どういう議論がされているのか、ということについて、どういうふうに現状を掌握されているのでしょうか。秋田県方式と言われている、簡単でいいですから、おわかりになっているところをちょっとご説明いただけませんか尋ねました。","respondent":"冠木指導課長、和氣学務課長","answer":"効果もあると認識しておりますので、自分たちの使うところはきちっときれいにしていこうという考え方からも、引き続きやっていきたいと考えています。やはり一人ひとりの子どもたちの家庭がじっくりと取り組んでいるというところは… ＣＯ２の削減の目標管理とかを含めまして、実際に日々、それを見ながら積極的に縮減をしていくということを考えてまいりたいと思っているところです。","id":"exchange-158"},{"speaker":"三上委員","kind":"質問・要望","question":"そうことが根付いている部分が、いろいろ伺う中から感じてきた。品川区の当たり前ということについての考え方について、もう一度、ちょっとお伺いさせていただけませんか。","respondent":"冠木指導課長","answer":"こんなところからも、家庭への啓発をさらに進めてまいりたいと考えています。学力についても同様と思ってあります。","id":"exchange-159"},{"speaker":"三上委員","kind":"質問・要望","question":"生きるということについて、非常に難しい時代であるかもわかりませんけれども、それを変えていくのは、やはり教育ということだと考えています。ですから、しっかりそういった視点からも、品川区の教育を大きく育てていっていただきたいとお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-160"},{"speaker":"須藤委員","kind":"質問","question":"１７３ページの教職員人材育成経費に関連してお尋ねいたします。ほんとうに人間としての生き方を教えてもらうところだろうと思うんですけれども、そういうものをどうやって育んでいくのか、説明を求めました。","respondent":"冠木指導課長","answer":"校長といいましても差がございまして、そういった現状をなかなか直視できないような校長も中にはおります。こういった校長には、私ども、特別研修ということで、徹底的に指導している状況もあります。","id":"exchange-161"},{"speaker":"須藤委員","kind":"質問・要望","question":"６年生で武道が入るということで、よき指導者を養成してほしいということを、自民党として要望しておりましたのでそのあたりをどう考えているか。やはり指導者によって子どもたちが教科を好きになったり、そのあたりの先生方はどういう仕組みになっているのか教えてほしいと求めました。","respondent":"冠木指導課長","answer":"武道については、品川区としては、国に先んじまして、もう既に実施しています。そういった地域のお力のある専門家の方から教えていただくという機会などもつくりまして、教員の指導力の向上にあたってまいりたいと考えています。","id":"exchange-162"},{"speaker":"須藤委員","kind":"質問","question":"それから、せっかく小学生から９年生までやるということで、特に柔道に関しては、１５歳以上になれば、黒帯、初段が取れます。我々の子どもたちが世界に羽ばたいたときに、ブラックベルトだということが言えるような形の一つの考え方というのは持てますか尋ねました。","respondent":"冠木指導課長","answer":"指導の形態ですけれども、必修ではありますが、授業については、男女別の授業ということになろうかと考えています。それから、将来に向けて優秀な人材が育てばいいと私も期待しておりますけれども、まずは、基礎的、基本的なところからかなと思っているところです。","id":"exchange-163"},{"speaker":"須藤委員","kind":"質問・要望","question":"やはり３年間やって、正課に入ってきたら、ぜひそういうところを教えてあげてほしいと求めました。学校サイドに、どういったサジェスチョンというかアドバイスみたいなものをしていらっしゃるのか、説明を求めました。","respondent":"冠木指導課長","answer":"子どもたちの全容を見取るアンケートは実施しているんですけれども、前倒しして１０月２７日付で、全校で実施しています。こういった痛ましい事件にならないように、品川区全校を挙げて、万全の態勢で対応してまいりたいと思ってあります。","id":"exchange-164"},{"speaker":"須藤委員","kind":"質問","question":"１７６ページ、それをまた区民に利用してもらってもいいという話も、我々は聞くことがあるんです。そういうことを広げていくというのは、すぐにはできないでしょうけれども、そういう考え方はいかがか尋ねました。","respondent":"小川品川図書館長","answer":"大学等の連携ですが、区内にあります清泉女子大学の図書館と区の公立図書館と図書の連携をすることができるようになってあります。区内の大学との連携は、今の段階では、ホームページでリンクを組むというようなところから着実に少しずつやっているところです。","id":"exchange-165"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/260957?Template=document&Id=1334#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":110236,"voices":378}},{"id":"h22-20101111-4","meetingId":"h22-c-settlement","date":"2010年11月11日","dateIso":"2010-11-11","committee":"決算特別委員会","time":"午前１０時０２分～午後６時１２分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を140件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"渡辺委員","kind":"提案","question":"初めに、品川区民の日をつくろうという提案です。区に寄せられる意見、区政を評価する意見や提案などについて、主なものをご紹介くださいとの意見を述べました。","respondent":"日下部企画部長","answer":"それから、町会、自治会活動への支援、最近では企業の社会貢献活動との連携、この点も挙げられるのではないかと思います。分野別でちょっと見てまいりますと、地域福祉の関係でまいりますと、災害時要援護者の支援。","id":"exchange-001"},{"speaker":"渡辺委員","kind":"提案","question":"あるいは区民同士というのは、この提案のキーワードになるかと思いますので、次に行かせていただきます。２３区における区民の日の制定状況について、その内容と取り組み、時期などについてお知らせくださいとの意見を述べました。","respondent":"市岡総務部長","answer":"事業としては、東京都の功労者表彰式を実施する。どちらの区も１０月１日に区民の日の行事として、区政功労者表彰式、品川区では昨日行いましたけれども、それを実施しております。","id":"exchange-002"},{"speaker":"渡辺委員","kind":"提案","question":"まず品川区に住み続けたいと世論調査でお答えの方が約９割いらっしゃる、これも大変大きな評価だと思っています。この提案の中で、品川区民の日の制定を提案しますが、ご見解を伺えればと思いますとの意見を述べました。","respondent":"市岡総務部長","answer":"特に社会貢献活動を推進するきっかけになるような区民の日ということで、これは新しいご提案の内容かなというふうに思っております。この点では、先ほど企画部長の答弁にありましたとおり、今後研究をさせていただきたいというふうに考えております。","id":"exchange-003"},{"speaker":"渡辺委員","kind":"提案","question":"品川区がそんなところで、品川区内中が至るところで、そんなムードに包まれたらどうかという提案です。こんな提案なのですが、いかがか尋ねました。","respondent":"宮地地域振興事業部長","answer":"助成といったような活動をしておりますし、具体的に平成２０年度から社会貢献活動見本市というのを実施しております。委員のご提案なども新しい角度からのご提案というふうに受けとめておりますので、いろいろな点から研究してまいりたいというふうに考えております。","id":"exchange-004"},{"speaker":"渡辺委員","kind":"質問","question":"初めに、品川区の観光のとらえ方を伺いたいと思います。初めに、だれを想定しての取り組みか、そしてどのような行動を想定されているか、そしてこの政策目的をお伺いします。","respondent":"宮地地域振興事業部長","answer":"計画的に実施計画にも推進を盛り込み進めているところですが、もちろん外国の方をはじめ、広域圏からの観光客あるいは品川区民も対象となります。","id":"exchange-005"},{"speaker":"渡辺委員","kind":"質問","question":"本当にとらえ方は人それぞれだと思いますが、区外の方も大切、そして、区民が区内を訪ねる、歩く仕組み、そのように解釈ができるかと思います。そしてまたそのお客さんのニーズをどう分析をされているのか、この「歩く」というテーマに添って伺いたいと思います。","respondent":"宮地地域振興事業部長","answer":"こうした一つひとつの品川らしさ、こういったものを魅力としてとらえ、評価をし、これを品川区全体に発信していく。これらを評価し、細かく把握していくことで、きめ細かな人気スポットを創出していきたいというふうに考えております。","id":"exchange-006"},{"speaker":"渡辺委員","kind":"意見","question":"この品川という中の地域ブランドの評価をどう把握されているのか。主なところでどのようなところを評価をされているのか、お知らせくださいとの意見を述べました。","respondent":"宮地地域振興事業部長","answer":"この品川という知名度が一つ大きく評価できると思います。特に近年では、そして７月にオープンになりました四季劇場、こうしたところも今後の人気スポットになるのではないかというふうに考えております。","id":"exchange-007"},{"speaker":"渡辺委員","kind":"質問","question":"これは今もう既に述べられたように、この情報、魅力をどう発信していくか。受け身ではなくて、どのように情報を、伝える、仕掛けていくかというところで伺います。","respondent":"宮地地域振興事業部長","answer":"全体を歩くウォーキング、まち歩き、これは大きなキーワードかと思います。既に実施しておりますが、そういったウォーキングなどが一つの着地型観光としても推進できるのではないかというふうに考えております。","id":"exchange-008"},{"speaker":"渡辺委員","kind":"質問","question":"今言われましたお客さんに、あるいは来訪者の方に歩いてもらうをテーマに、整備の部分を伺っていきたいです。よく言われるユニバーサルデザインという言葉、この言葉の意味、あるいは品川区に当てはめた場合を伺いたいと思います。","respondent":"片田防災まちづくり事業部長","answer":"現状では対応８８％というような状況になっておりますし、平成２１年度中に９５％の状況ですけれども、平成２３年度中には１００％の対応。","id":"exchange-009"},{"speaker":"渡辺委員","kind":"質問・要望","question":"やはりいざ意識して聞いてみると、この整備の進み方の確認ができてよかったと思います。当然望ましいのですが、要所要所で、あるいは継続性あるいは質を求められる場面もあるかと思います。","respondent":"宮地地域振興事業部長","answer":"この方たちの質をアップするという意味では、毎年研修会や養成講座を行っておりまして、今年は既に８回実施したところです。取り組んでいるところですので、今後、こちらのほうも充実できると考えております。","id":"exchange-010"},{"speaker":"渡辺委員","kind":"提案","question":"そして一つの提案としたら、今後、八潮地区や運河のあたりでの展開が面白いのではないかと思っています。あるいはつくるアーティストの参加での文化の視点、とにかくお客さんが見てみよう、というような仕掛けの一つとしてご見解を伺えればと思いますとの意見を述べました。","respondent":"岩田都市環境事業部長","answer":"大井町駅の西口のけやきの道におきましては、平成２０年からＮＰＯまちづくり大井の皆さんがイルミネーションをやってあります。今後動きがあれば、区としてもこういった部分については積極的に支援をしていきたいと考えているところです。","id":"exchange-011"},{"speaker":"渡辺委員","kind":"確認","question":"この確認と、この根拠を伺いたいと思います。それと、観光の視点で商店街を活かした取り組み、先ほどもありましたが、それを改めて伺いたいと思います。","respondent":"宮地地域振興事業部長","answer":"これはやはり埋もれている資源を新たな観点から皆さんに見えるような形で取り組んでいく、より深くその地域のことについて学んでいただく。","id":"exchange-012"},{"speaker":"渡辺委員","kind":"確認","question":"これを確認したいし、今後もという思いなのか、伺いたいと思います。そんな努力、そのような考え方が必要かと思いますのが、ご見解をお伺いします。","respondent":"宮地地域振興事業部長","answer":"もとより住んでいる方々のアイデア、そしてそれを支援する仕組みといたしまして、観光協会、そして庁内もさまざまな横の連携、こうした形で地元を活性化するための取り組みは今後も続けてまいりたいというふうに考えております。","id":"exchange-013"},{"speaker":"渡辺委員","kind":"質問・要望","question":"最後に地域スポーツの点で伺わせてください。最後にこの見解を伺いたいと思います。","respondent":"宮地地域振興事業部長","answer":"ビジョンもあります。振興を図っていく必要があることは十分認識しておりますし、今後も精いっぱい振興を図っていきたいというふうに考えております。","id":"exchange-014"},{"speaker":"伊藤委員","kind":"提案","question":"八潮団地に続いて、杜松小学校跡地への高齢者施設建設等を自民党が提案してまいりました。そこで品川区での学校跡地の有効利用を踏まえた同施設の有効活用についてお伺いいたしますとの意見を述べました。","respondent":"日下部企画部長、木下健康福祉事業部長","answer":"区の政策目的を着実に実現をしていく、そういう観点から有効活用を図ってまいりたい、このように考えております。このように、さまざまな角度から、柔軟でより効果的な活用を図ってまいりたい、このように考えているところです。 小規模の特別養護老人ホームおよびグループホーム、そして小規模多機能型居宅介護および介護予防拠点を含めました地域との交流拠点というような枠組みで、現時点では想定をしています。","id":"exchange-015"},{"speaker":"伊藤委員","kind":"質問","question":"さて、次にほかの施設の中で、荏原第四中学校の跡地についてお伺いいたします。改めてその理由と、それから品川区の施設を貸与した目的、それから賃貸料等の算出基準について、答えるよう求めました。","respondent":"日下部企画部長","answer":"このような防災上の効果、さらには私学振興、こういう観点なども踏まえまして、区としても協力をしてまいりたい、このように考えているものです。","id":"exchange-016"},{"speaker":"伊藤委員","kind":"質問・要望","question":"次に、その青稜高校への賃貸が終了した後についてお伺いいたします。現時点で、この荏原第四中学校の有効活用施策等について、品川区の見解をお伺いいたします。","respondent":"日下部企画部長","answer":"青稜高校への貸し付けの終了後ですけれども、ご質問にもございましたさまざまな有効活用策が考えられる、このように受けとめております。それから区民ニーズの変化なども十分に見きわめながら、しっかりとした検討を進めさせていただきたい、このように考えているところです。","id":"exchange-017"},{"speaker":"伊藤委員","kind":"提案","question":"次に、財政関係についてお伺いいたします。まず質問は、多くの区民の声は、せめて品川区レベルでの緊急経済対策を来年度も引き続き継続してほしいとの区民の声をたくさんいただきますとの意見を述べました。","respondent":"金子企画財政課長","answer":"平成２２年度では、住宅リフォーム助成、中小企業の販路拡大や創業支援にも取り組んでいるところです。来年度も継続を、とのお尋ねですが、日本経済の動向あるいは区内経済の状況などを的確に把握しまして、対応を検討してまいります。","id":"exchange-018"},{"speaker":"伊藤委員","kind":"確認","question":"特殊な事情がありますけれども、来年度の税収減が約１００億円と推計をし、３６事業の見直しを明確にしたと新聞報道にありました。改めて品川区の現状と来年度税収の見通し、また目黒区と品川区についての比較、この確認をしたいと思いますが、ご答弁をお願いいたします。","respondent":"金子企画財政課長","answer":"平成２２年度は平成２１年度に比べまして、約３０億円ほど減少すると今のところ見込んでおります。平成２３年度につきましては、現在の経済状況から見ますと、引き続き厳しい状況になると考えているところです。","id":"exchange-019"},{"speaker":"伊藤委員","kind":"確認","question":"その確認をまずお伺いしたいのと、併せて、さらに事務事業評価、この結果の厳格な適用もさらには必要になってくると思いますが、いかがでしょうか。そのことについての答弁をお願いいたします。","respondent":"金子企画財政課長","answer":"時代の変化などに対応し、役割の終えた事業を思い切って縮小、廃止していくことが肝要かと思います。財源不足に対しましては、ご指摘の基金の活用、あるいはさらに起債についても後年度負担の少ない部分で活用してまいる考えです。","id":"exchange-020"},{"speaker":"伊藤委員","kind":"質問","question":"さまざまなオプションを考えて、この財政難に対応していく必要があると思いますが、いかがでしょうか。見解を説明を求めました。","respondent":"金子企画財政課長","answer":"組織改正あるいはさまざまな取り組みについても、適宜検討していく必要があるというふうに考えております。いずれにしましても時々の状況に適切に対応しまして、地域経済の活性化と区民生活の維持向上に向け、努力を重ねていく考えです。","id":"exchange-021"},{"speaker":"伊藤委員","kind":"質問・要望","question":"やはり国に対しての税源移譲を求めていくとか、改めて品川区の見解として、国に対してもさらなる税源移譲を行う考えをお聞かせください。地方財政が大変厳しくなる中で、国がこのような施策を行うことについては、やはり地方自治体が国に向かって意見を言うべきではないか尋ねました。","respondent":"濱野区長","answer":"最初に一括交付金に対する考えということからお答えをしますが、これには地方自治体の側からは懸念をすべき点が多々あるというふうに思っております。そうしたことから、また特別区長会から市長会への声も強く申し上げていかなければならないというふうに考えているところです。","id":"exchange-022"},{"speaker":"伊藤委員","kind":"提案","question":"そこで私ども自民党からも幾つか提案をさせていただきましたけれども、品川区に立ち寄るための幾つかのポイントを設定していきたいと考えます。空港内で放映すること等を行い、羽田空港から品川区へのお客様を誘導をすべきではないかと思いますが、いかがか尋ねました。","respondent":"宮地地域振興事業部長","answer":"さらに新たに４カ国の言葉を使ったパンフレットを作成し、一層ＰＲに努めていきたいというふうに考えております。ご提案のものも含めまして取り組んでいきたいというふうに考えております。","id":"exchange-023"},{"speaker":"伊藤委員","kind":"提案","question":"自民党も提案させていただきましたが、今度は羽田空港からの客を積極的に大井競馬場へ誘導すべきではないかと考えています。特別区競馬組合との協議等を具体的に行うべきではないかと思いますが、いかがでしょうか、ご答弁をお願いいたしますとの意見を述べました。","respondent":"宮地地域振興事業部長","answer":"お連れするというのは大井競馬場のほうも積極的でございまして、区や観光協会のほうにも申し入れがありました。今後、羽田空港の国際化への対応を検討する観光協会の会議にも出席していただくなど、連携した取り組みにつきまして検討してまいります。","id":"exchange-024"},{"speaker":"伊藤委員","kind":"質問","question":"浜川砲台、しながわ水族館、屋形船での夕食といったコース開発等の企画をしてみてはいかがでしょうか。費用対効果を勘案した設備建設、浜川砲台跡地に大砲を整備する等、具体的な検討をしてはいかがか尋ねました。","respondent":"宮地地域振興事業部長","answer":"それから従来やっておりました商店街のイベントなども支援することによりまして、なお一層の取り組みを進めていきたいと考えています。いずれにいたしましても、観光アクションプランに基づきまして、計画的に取り組みを実施してまいりたいと考えております。","id":"exchange-025"},{"speaker":"金野副委員長","kind":"質問","question":"１点目は、待機児童対策についてお聞きをいたします。本区における待機児童の主な要因をどのように認識しておられますか尋ねました。","respondent":"古川子ども未来事業部長","answer":"そしてもう一つは、これは品川区全体が持っている一つの評価にもつながると思うんですが、品川区への転入ということが増えてきている。こういったものが要因となりまして、本来準備しております保育園の入園枠を大幅に上回る方々の希望がある、このように考えてあります。","id":"exchange-026"},{"speaker":"金野副委員長","kind":"質問","question":"そこで、短時間保育室と保育ママ制度は、現在どのように実施されていますでしょうか。事業の概要、募集状況や実施状況、事業の成果と課題、そして今後の展開など、それぞれの事業について説明を求めました。","respondent":"古川子ども未来事業部長","answer":"一つは短時間の就労支援型ですが、今年で３年目になりまして、３カ所で実施しています。従来の認可保育園だけでは対応できないものが当然に求められてくるだろう、今後考えていく必要があるだろう、このように考えてあります。","id":"exchange-027"},{"speaker":"金野副委員長","kind":"提案","question":"その後の検討は、どのように進められていますでしょうか。課題解決のためにも、要件の見直しを図ることなどを提案をしますが、ご見解をお伺いいたしますとの意見を述べました。","respondent":"古川子ども未来事業部長","answer":"複数名の保育ママによる小規模な施設型の保育ママ制度を立ち上げたい、このように思いながら今年度、さまざまに検討してまいりました。","id":"exchange-028"},{"speaker":"金野副委員長","kind":"質問・要望","question":"この事業についての本区の認識をお伺いいたします。本区が実施しています短時間保育室との違いも合わせてご答弁ください。","respondent":"古川子ども未来事業部長","answer":"区の制度としてはなかなか難しいと考えていますが、私どもは積極的に支援をしていきたいと、このように考えております。私は大きくは違っていないと思ってありますが、いわゆる４時間未満の方においても預けることができるということでは、このように考えてあります。","id":"exchange-029"},{"speaker":"金野副委員長","kind":"提案","question":"マンションや空き店舗などを活用した合同保育を実施するなど、制度を利用しやすいように、保育ママと連携した仕組みづくりを提案をいたします。ご所見をお伺いいたしますとの意見を述べました。","respondent":"古川子ども未来事業部長","answer":"多様な保育ニーズにこたえていくという区の姿勢から考えますと、私のほうでも十分に研究をさせていただきたい、このように考えてあります。","id":"exchange-030"},{"speaker":"金野副委員長","kind":"質問・要望","question":"質問の１点目は、健康行政がどれほど区民の健康に関わっているかについてお伺いいたします。健康塾や体操教室など、健康の増進などを目的とした健康づくり事業の主な事業名と、延べ人数ではない参加人数をお知らせください。","respondent":"木下健康福祉事業部長","answer":"子宮頸がんが１万３,２４６人、乳がんが９,４９３人、前年度対比で１０ポイント近い増加が見られているところです。ふれあい健康塾は１３回以上ありますが、後期で参加された方ということで３０２人という実績が上がっているところです。","id":"exchange-031"},{"speaker":"金野副委員長","kind":"質問","question":"次に、この健康診断のデータの活用についてお伺いいたします。健診データの活用の考え方や、現在、区で行っている活用についての事例や今後の課題についてお聞きいたします。","respondent":"木下健康福祉事業部長","answer":"それから、今ミクロの視点で申し上げましたけれども、健診データを今度マクロの視点から把握していくということも大事です。今後の健康づくり事業等にどう活かしていくことができるかということについて、今後検討をしてまいりたいというふうに思っているところです。","id":"exchange-032"},{"speaker":"金野副委員長","kind":"提案","question":"より区民にわかりやすく健康づくりが促進される仕組みと体制づくりを行っていただきたいことを提案をいたします。ご所見をお伺いいたしますとの意見を述べました。","respondent":"木下健康福祉事業部長","answer":"介護予防事業につきましては、来年度の介護保険事業計画改定の中で、今お話がありました部分についても検討していきたいというふうに思ってあります。","id":"exchange-033"},{"speaker":"金野副委員長","kind":"提案","question":"これまでと同じようにその２本立てで行くならば、二つの計画をそのまま進めていくと、これまでと同じ繰り返しになるのではないかと懸念をいたします。","respondent":"木下健康福祉事業部長","answer":"介護予防事業の体系化、先ほど申し上げましたように「いきいき計画２１」の中の検討の中で十分精査をしていきたいというふうに思っているところです。改定期が平成２５年になりますので、その段階で、この問題については再度検討していきたいというふうに思っているところです。","id":"exchange-034"},{"speaker":"金野副委員長","kind":"提案","question":"各１３地域の推進委員会をバックアップする仕組みづくりを検討し、地域の健康リーダーとして、卒業生を派遣する体制づくりを提案いたします。ご所見をお伺いいたしますとの意見を述べました。","respondent":"本保品川区保健所長","answer":"具体的には、健康大学で習得された情報を発信し、健康づくりの行動モデルをご自分で示すなどの役割を担っていただきたいというふうに考えております。","id":"exchange-035"},{"speaker":"金野副委員長","kind":"提案","question":"代表的な提案として、ランニングが定着をしていることから、歩道などに歩いた距離がわかるような標識や塗装を施すことなどを提案してまいりました。これまで私どもが提案してきました事業の拡充などによって、さきの健康大学しながわの卒業生など、ご所見をお伺いいたしますとの意見を述べました。","respondent":"本保品川区保健所長","answer":"今ご質問にお答えしましたように、地域に出向いて行って、その場で健康づくりについて、いろいろな方を対象にしてサポーター役を担っていただきたい。そのような情報を積極的に発信する役割を担っていただきたいというふうに考えてあります。","id":"exchange-036"},{"speaker":"山路委員","kind":"質問","question":"区営住宅をどのようにしてセーフティネットの拠点とするのか、お伺いします。住宅確保要配慮者のために住宅を供給することは難しいのではないかと思いますが、区の意図するところをお伺いいたします。","respondent":"片田防災まちづくり事業部長","answer":"その中で、現状、区営住宅の利用についてはかなり満室状況ということもありまして、なかなか住宅を必要とする方にとっては難しいところもあります。民間の活用を含めて、それぞれのいろいろな仕組みを今、検討しているというような状況です。","id":"exchange-037"},{"speaker":"山路委員","kind":"質問","question":"毎年１２月に申し込み登録するとのことですが、昨年度の申込者数と、実際入居できた世帯数、そして今後の高齢者住宅の方針についてお伺いします。住宅あっ旋事業の申し込み数と、実際にあっ旋制度を利用した世帯数、そして今後の取り組みについてお伺いいたします。","respondent":"木下健康福祉事業部長","answer":"今後の区としての考え方ですけれども、一定の基盤が整備されているというふうに考えておりますから、具体的に予定はしておりません。そして今後、改善点等が出てまいりましたら、その部分については十分検討をしていきたいというふうに思っているところです。","id":"exchange-038"},{"speaker":"山路委員","kind":"提案","question":"私は平成１９年第２回定例会にて、この制度を活用して、高齢者世帯および子育て世帯に借上型区民住宅の空き室を提供することを提案しました。一般型、高齢者型を問わず、地優賃制度を利用した住宅の提供についての本区のご所見をお伺いいたしますとの意見を述べました。","respondent":"片田防災まちづくり事業部長","answer":"区のこれまでの検討の経過といたしましては、それぞれ区民住宅のオーナーとも協議をしながら、これまで導入に向けた検討を行ってきたところです。","id":"exchange-039"},{"speaker":"山路委員","kind":"質問","question":"今まで借上型区民住宅の空き室については手がつけられませんでしたが、実現に至った経緯についてお伺いいたします。今後の他の借上型区民住宅の空き室対策にどのように適用されるのか、お伺いします。","respondent":"片田防災まちづくり事業部長","answer":"特に条例の中で検討を私どもがしてきたところは、補助金をもらわなくても逆に入室を図って収入を見込めるといったような判断で。契約が５年を切った中で、収入のシミュレーションを図って今後の導入についての検討を進めていきたいと、このように考えてあります。","id":"exchange-040"},{"speaker":"山路委員","kind":"提案","question":"同じく平成１９年の第２回定例会で、アドバイスや高齢者向け施設の情報提供を行うなど、高齢者住み替え促進事業の実施を提案いたしました。そのほか手続きなど事業の概要についてお伺いをいたしますとの意見を述べました。","respondent":"片田防災まちづくり事業部長","answer":"民間の不動産業者の協力を得ながら、子育て世帯を優先的に入居してもらえるように努められるよう、いろいろ検討してきているところです。そういう対応ができないかということを合わせて、その制度の中で今後検討していきたい、このように考えてあります。","id":"exchange-041"},{"speaker":"山路委員","kind":"質問","question":"このモデル事業の概要についてお伺いします。そして、大井林町高齢者住宅が選択された主な理由、また補助金などのメリットについてお伺いをいたします。","respondent":"木下健康福祉事業部長","answer":"今回、それから生活支援サービスを内包させるなどの工夫がされているということで採択になったというふうに理解をしております。家賃等を計算するに当たりましては、ある意味では減価償却期間を３９年と見た場合のご本人当たりの負担額ということで計算をしてまいりますので。","id":"exchange-042"},{"speaker":"山路委員","kind":"提案","question":"居住支援協議会の概要と支援制度についてお伺いします。居住支援協議会を立ち上げて、住宅の確保に特に配慮を要する方への居住支援に取り組むことを提案しますが、それぞれご所見をお伺いしますとの意見を述べました。","respondent":"片田防災まちづくり事業部長","answer":"居住支援協議会の概要とその内容ですけれども、協議会については、住宅セーフティネット法の中に組織としての設置についての規定があります。","id":"exchange-043"},{"speaker":"山路委員","kind":"提案","question":"公明党はこれまでさまざまな機会を通じて、条例の制定や具体的な取り組みについて質問し、提案を行ってまいりました。初めに、ビジョンの概要について、策定された背景や位置づけ、主な取り組みの内容についてお伺いいたしますとの意見を述べました。","respondent":"宮地地域振興事業部長","answer":"こうした基本構想等を実現するための方向を示すもの、この文化芸術・スポーツ振興が必要であるという方向性を踏まえたものと考えております。本年度から実施いたしました芸術祭、そして劇団四季との連携による親子観劇招待、活動拠点の整備などが挙げられます。","id":"exchange-044"},{"speaker":"山路委員","kind":"質問","question":"品川の魅力と活力を輝かせていくためには、ビジョンにも示されているとおり、区にあるさまざまな資源を活かしていくことが重要であると考えます。夏劇場が本年７月にオープンし、５カ月目を迎えた現状と課題について、それぞれお伺いをいたします。","respondent":"宮地地域振興事業部長","answer":"にぎわい創出のために行った取り組みといたしましては、情報交換を進めること、ＰＲを行ってきたところです。今後、この四季劇場、地域のまちづくり、あるいはにぎわいづくりに、どのようにつなげていくかが重要な課題ととらえております。","id":"exchange-045"},{"speaker":"山路委員","kind":"質問","question":"一方、区内の子どもたちを対象に、観劇だけでなく、舞台終了後などに俳優の方と触れ合えるような取り組みや、ワークショップへの協力など、さらなる交流を深める取り組みについて考えたらどうかと思いますが、どのようにお考えか尋ねました。","respondent":"宮地地域振興事業部長","answer":"劇団四季が児童に対して美しい日本語の話し方教室などを区内の小学校でも実施しているというふうに伺っております。今後も劇団四季に働きかけまして、引き続き協議をしてまいりたいと考えております。","id":"exchange-046"},{"speaker":"山路委員","kind":"提案","question":"私は今年の第２回定例会で若手アーティストの養成について提案いたしました。来年度以降の開催に当たって、どのような課題が残されたのか、合わせてお伺いいたしますとの意見を述べました。","respondent":"宮地地域振興事業部長","answer":"これまで行ってきました事業を一体的に実施しまして、相乗効果による盛り上がりを図るとともに、いずれの会場にも多くの方にご入場いただきました。課題といたしましては、いろいろ町会等でもＰＲしたのですが、まだまだ周知が足りなかったかと認識しております。","id":"exchange-047"},{"speaker":"山路委員","kind":"提案","question":"９月、委員会視察で大分市を訪問し、１０月に予定されていたおおいた夢色音楽祭２０１０のお話を伺いました。幅広く多くの区民が参加でき、まち全体のにぎわいにつながる芸術祭の開催を提案いたしますが、それぞれのご所見をお伺いいたしますとの意見を述べました。","respondent":"宮地地域振興事業部長","answer":"一定の整理をしました後、実行委員会等のご意見をいただきながら、より効果的な方法を検討していきたいと考えております。芸術祭を一つのきっかけとなるようなものとして考えていきたく、さらに課題を詰め、検討してまいりたいと考えております。","id":"exchange-048"},{"speaker":"山路委員","kind":"提案","question":"一つの提案ですが、各種スポーツの予選会を各地域で行い、きゅりあんで表彰式を実施するなどの取り組みも今後検討してみてはと思います。本区の美術館や歴史館にて同様の取り組みを検討するよう提案いたしますが、どのようにお考えか尋ねました。","respondent":"宮地地域振興事業部長","answer":"さまざまな可能性はあると思います。さまざまな取り組みをしておりますので、ご提案の内容なども参考に、施設の利用者増に合わせ有効活用を図ってまいります。","id":"exchange-049"},{"speaker":"山路委員","kind":"質問","question":"あくまでも人と人を結ぶ交流につながり、文化芸術・スポーツ振興でにぎわいのまちづくりが推進されますことを、ご努力をお願いいたしまして、私の総括質問を終了いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問・要望","question":"仕事につけない、仕事をやめざるを得ない実態をどう受けとめているのでしょうか。質問が多いので、区の対応については、後ほどお伺いをします。","respondent":"古川子ども未来事業部長","answer":"それから２点目が、点数制のご説明ということでありましたけれども、一定の選考の方法の中に基準を設けてあります。これは育児休業制度をしっかりとるという基本方針はありますけれども、１年以上前から、当然枠があります。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"確認","question":"５点伺いましたが、どの項目も、本来ならば保育園に入れる、資格がある人であると確認をしてもよろしいでしょうか。そして、どうして不足をしている認可保育園をつくらないのか、その理由をお伺いいたします。","respondent":"古川子ども未来事業部長","answer":"来年６月にもまたできる予定です。さまざまな受け皿を用意する中で、それぞれの需要にこたえていきたい、このように考えてあります。","id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問","question":"大方がお金をかけずに詰め込み保育など、子どもたちを犠牲にする内容が多いのではないでしょうか。認可保育園をつくらない、この理由にこの間、ピーク論とコスト論、たびたび伺っていますが、この点はいかがか尋ねました。","respondent":"古川子ども未来事業部長","answer":"さらなる必要な経費をどう投入していくかということにつきましては、将来の行政需要をどう判断していくかということに帰結するだろうと考えています。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問・要望","question":"子どもを本当に生み育てやすい環境をつくっていく、子どもが増えることをぜひやってほしいと求めましたが、いかがでしょうか。民間任せではなく、区が認可保育園増設を行う、認可保育園増設を柱に据えた対策を立てて、直ちに行うことを求めますが、いかがか尋ねました。","respondent":"古川子ども未来事業部長","answer":"第２４条、確かに保育の実施責任は区市町村にあります。さまざまな受け入れを今も進めておりますし、来年の４月にはさらなる受け入れ枠を確保していきたい、このように考えてあります。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問","question":"世田谷区などでは、国有地、公有地、これを活用して認可保育園をつくり、２年間で１,７９３人分増やしています。待機児ゼロを目指して本気で実行、実現をしてほしいのですが、いかがか尋ねました。","respondent":"古川子ども未来事業部長","answer":"あるいは幼稚園における預かり保育、さまざまな手法を講じながら一人でも多くの方が入れるように、そういう努力を今後ともしてまいります。","id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問","question":"４９４人と６６人の差、この差はどういうことなのか、私はからくりがあると思っています。待機児６６人と、私たちの未入園児４９４人の実態との乖離について、説明をお願いしたいと思います。","respondent":"古川子ども未来事業部長","answer":"４９４人ではなくて４８７人でありまして、４８７名の方には入園申し込みをなさいましたが、不承諾という形での通知をしている。その基準に照らし合わせて６６人というのが、品川区の正式な４月１日における待機児童の数です。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"公共施設の一つとして、保育需要に対し認可保育園を中心とした整備計画を持つべきと考えますが、いかがでしょうか。もう１点は、五反田のグランスカイのマンションの総戸数と高さ、そして総事業費、税金投入額も説明を求めました。","respondent":"古川子ども未来事業部長、片田防災まちづくり事業部長","answer":"さまざまな状況の中で、再度その方が４月１日以降の入園を意志として持っていらっしゃるかどうか。これは確認するのは当たり前です。これは３,３７５戸という状況ですし、再開発を進める地域もありますので、その中で将来的な予想については５,１２７戸を予定しています。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問","question":"今グランスカイのことを伺いましたけれども、品川区で一番高い。この辺の基盤整備は一体どこの部署でどのように練られているのか、そこをお伺いします。","respondent":"片田防災まちづくり事業部長","answer":"基本的には公益施設、子育て支援施設もそうですし、そういう中で、いろいろな支援を検討しているというような状況です。そういうことがありますので、そういうところにつきましては防災まちづくり事業部のほうで指導しているという状況です。","id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区みずからが需要に見合った認可保育園の増設を実行、そして実現することを求めたいと思います。待機児解消から１人でも減らしたい、このことは後退をしたのでしょうか、改めてお伺いをしたいと思います。","respondent":"片田防災まちづくり事業部長、古川子ども未来事業部長","answer":"再開発にはこれまでも何度もご説明していますように、その事業計画の中で、必要な需要を見込んです。今お話がありましたように３０人の定員の認証保育所ということでの話もありますし、それは指導してきた結果で… 区長の発言についてのご質問ですけれども、基本的な区のスタンスは変わってございません。一人でも多くの方々が保育園に入れるように、そういう施策をこれまでも、そしてこれからも、とってまいります。","id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問・要望","question":"実態はどんどん悪化をしているというとらえ方をぜひしてほしいと求めました。このことを強く求めまして、終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"南委員","kind":"質問・要望","question":"年収が１５０万円程度ですから、特別養護老人ホームの増設は、今本当に多くの区民の切実な課題です。この点について、まず見解を伺いたいと思います。","respondent":"木下健康福祉事業部長","answer":"その段階で、荏原地区の３カ所、戸越台、荏原、中延、すべて土地の目鼻はついていたわけであります。言ってみればお約束になりますので、そういう具体化の担保といいますか、それが明らかな段階で計画化するのが正しいと考えているところです。","id":"exchange-061"},{"speaker":"南委員","kind":"質問・要望","question":"特別養護老人ホームに何年待っても入れないという声がたくさんあるわけですね。そこで、特別養護老人ホーム入所のための申し込みをした方の数と、入所できた方の数を改めてまたパーセンテージも教えてほしいと求めました。","respondent":"木下健康福祉事業部長","answer":"平成２０年度につきましては、申し込みをされて審査対象になった方の数が合計で９４４人、入所された方の数が１１３人で、入所率が約１２％です。平成２１年度は１,０２８人の審査を行いまして、１９９人の方が入所、入所率１９.４％という数字になっております。","id":"exchange-062"},{"speaker":"南委員","kind":"質問","question":"したがって、一刻も早くつくってほしいという声がたくさんあることは、この数字を見ても十分ご存じになることだというふうに思います。要介護認定を受けた方々の数字というのはどういうふうな状況になっているのかを説明を求めました。","respondent":"木下健康福祉事業部長","answer":"平成１２年の段階ですけれども、当時の要介護認定の認定率は８.４％でございまして、人数とすると４,６５１人です。直近、平成２２年３月の段階の認定率は１４.４％、認定者総数は１万１８５人という数字になっております。","id":"exchange-063"},{"speaker":"南委員","kind":"質問・要望","question":"さらに団塊の世代が増えていく、こういう状況ですから待ったなしなんです。９０歳、平成２１年度の第２回目の申し込みの数で結構でありますので、そこをちょっと教えてほしいと求めました。","respondent":"木下健康福祉事業部長","answer":"１０５人ということで、要介護度３を中心に４、５の方が申請をされている状況にあるです。年齢的な部分では８０歳から９０歳ぐらいの方が中心になっているというふうに認識しております。","id":"exchange-064"},{"speaker":"南委員","kind":"質問","question":"そして８０代の方が２２９人、９０代の方は１２１人、増えてきている。増加傾向にあるというふうに私は思うんですけれども、その辺については、どういうふうに区としては見ているんか尋ねました。","respondent":"木下健康福祉事業部長","answer":"やはり在宅で限界が来たときに入所の見通しが立つということを介護の基本方針にしておりますから、４、５の方が中心である。ただ、若干年齢の部分が、現在は年齢がやや高くなってきている傾向があるということは事実であるというふうに思っております。","id":"exchange-065"},{"speaker":"南委員","kind":"質問","question":"これについての見解と、土地の目鼻が立ってからと区は繰り返し答弁しますけれども、目鼻が立ってからでは２年や３年はかかるわけですね。この点での見解も合わせて伺いたいと思います。","respondent":"木下健康福祉事業部長","answer":"２３区整備率の比較で余り反論するのもあれなんですけれども、品川区はケアホームですね、いわゆるユニットケアの施設も整備してまいりました。今後ともその点については努力をしてまいります。","id":"exchange-066"},{"speaker":"南委員","kind":"質問・要望","question":"これは保育園とか介護施設等々のそういう基盤整備とか量的拡大が求められている事業について、地方公共団体の事業者が施設整備を行う場合に。どういうふうにアプローチしてきているのか、それについて紹介をしてほしいと求めました。","respondent":"日下部企画部長","answer":"確かに今ご質問にありますように、国の姿勢もだいぶ変わってきております。例えば用途廃止の決定方針が明確になったもの、そういうものについては今現在提示をされていない、そういう状況です。","id":"exchange-067"},{"speaker":"南委員","kind":"質問","question":"ワンフロアですから非常に小ぢんまりと落ち着いて生活ができるということで、そういうふうに思いました。そういう点については、どのようになっているのか、こういうふうにちょっと考えを伺いたいと思います。","respondent":"日下部企画部長","answer":"財務省所管の中で処分財産になっている、そういうレベルまでは行っていない、というふうに私どもは承知をしています。今後は多少時間的に余裕がありますので、さまざまな角度から有効活用について検討してまいりたいと、このように考えているところです。","id":"exchange-068"},{"speaker":"南委員","kind":"質問・要望","question":"要望があるということに目を背けて、合計すると最低でも１２年間ですか、１２年間もの長きにわたってＴＯＣビルに貸し出しをする。この点についても校舎の活用はまだまだできるはずですから、そういう政治へと切りかえていただきたい、そういうふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"阿部委員","kind":"質問","question":"初めに、品川区が抱える喫緊の課題の１つである、保育園の待機児童対策について伺います。そこで、まず来年度に向けたさまざまな保育の受け皿の拡大方策について、見通しを伺います。","respondent":"古川子ども未来事業部長","answer":"今年の４月につきましては、緊急対策ということで相当大がかりな増員計画をもって対応し、そして、結果として６６名の待機児童が生じたです。来年の４月はそれを上回るような努力を現在、行っているところです。","id":"exchange-070"},{"speaker":"阿部委員","kind":"質問","question":"それから、既存園における定員増と弾力化の考え方についても伺います。この定員の拡大と弾力化との関係についてご説明をお願いいたします。","respondent":"古川子ども未来事業部長","answer":"まさに緊急的な状況の中でこの数字にこだわることは、受け入れが非常に難しいということの一つの考え方だろうと思います。したがいまして、結論から申し上げますと、定員拡大であっても、弾力化であっても、子どもの受け入れについては一定の限界があると考えております。","id":"exchange-071"},{"speaker":"阿部委員","kind":"質問・要望","question":"さて、品川区では本年度、小学校に保育園の分園をつくって５歳児を保育する、そんな仕組みをスタートさせました。子どもの様子や保護者の声、そして保育士や教員の変化などを踏まえ、この施策に対する区としての評価と課題についてお伺いしたいと思います。","respondent":"古川子ども未来事業部長","answer":"これを実施するにあたっては、現時点で実際に子どもを見、今回の施策については満足していただいている方がほとんどだろうと考えています。","id":"exchange-072"},{"speaker":"阿部委員","kind":"質問・要望","question":"例えば保育園での４歳児の育ちがどうなっているのか、そういったことも含め、区としてそのようなお考えがあるのか伺いたいと思います。そういった評価の分かれ目にもなると思いますので、ぜひ検討してほしいと求めましたけれども、いかがか尋ねました。","respondent":"古川子ども未来事業部長","answer":"まだ半年ちょっとですので、先ほど申し上げました、あくまでも待機児に対する緊急的な対応策と私自身も認識しています。この分園のスタイルをどうしていくかということにつきましては、そういう観点から、待機児の動向も踏まえて判断する時期が来るだろうと考えています。","id":"exchange-073"},{"speaker":"阿部委員","kind":"質問","question":"このテーマの最後の質問になりますが、過去にも中央教育審議会等で、義務教育年限の引き下げが議論されたことがあります。今回の施策は、５歳児からの義務教育化という方向につながる可能性を持つものなのか、区あるいは区教育委員会のお考えを伺いたいと思います。","respondent":"古川子ども未来事業部長","answer":"義務教育化につきましては、今から数年前、当時の政府の考え方にあったことは事実ですし、その後に無償化という問題がまた出てまいりました。この事業を始めたのは、先ほど申し上げましたとおり、あくまでも待機児童解消ということでご理解いただければと思います。","id":"exchange-074"},{"speaker":"阿部委員","kind":"質問","question":"次に、子どもや家庭にかかわるさまざまな課題と行政としての対策について伺います。今月１１月は児童虐待防止推進月間でもありますが、品川区では児童虐待の予防と早期発見のために、どのような体制を組んでいますか尋ねました。","respondent":"古川子ども未来事業部長","answer":"早期に発見をし、そして対応を速やかにとっていく、こういう観点から始めたものです。権限を持って臨まなければできないもの、そういうことについての仕分けをしながら、それぞれの役割を十分に果たしていきたいと考えております。","id":"exchange-075"},{"speaker":"阿部委員","kind":"質問・要望","question":"児童虐待では迅速できめ細やかな対応が求められております。検討会の中でのこの問題をめぐる議論と、品川区としての考え方、将来への展望とクリアすべき課題についてお知らせください。","respondent":"日下部企画部長","answer":"区側の基本的な考え方ですけれども、特別区が実施しております児童家庭相談とあわせまして、支援を一体的に行う。そういった点で既に平成２０年の６月の幹事会におきまして、区に移管する方向で検討する事務であるという位置づけで都区が一致しています。","id":"exchange-076"},{"speaker":"阿部委員","kind":"質問","question":"それから、ホットライン開設１カ月でのホットラインの内容別相談件数、そして対応なども教えてください。このホットラインの存在そのものの周知方法についてもお伺いします。","respondent":"市岡総務部長","answer":"広報しながわで３回、説明をしながらお配りし、こういうケースがあります。なお、あさっての土曜日からＣＡＴＶで、人権啓発課長が町会長会議で説明をしているところが放映される。","id":"exchange-077"},{"speaker":"阿部委員","kind":"質問","question":"この一時保護、これは区自体には一時保護をする権限はたしかないはずなんですけれども、これはどういった仕組みになっているのか。その専門性と権限の面から、もう少し詳しく教えていただけますか。","respondent":"市岡総務部長","answer":"これまでも一時保護を一定の制度の中でやっておりますので、特に児童相談所との関係で児童、それからドメスティック・バイオレンスの場合ですね。","id":"exchange-078"},{"speaker":"阿部委員","kind":"質問","question":"区内ではＤＶについて今、どんな相談体制をとっているのでしょうか。過去３年間の相談件数と内容の傾向などをまとめていらしたら、まずは説明を求めました。","respondent":"市岡総務部長","answer":"それから傾向としては、これは逆にこういう傾向だという一義的なものがないところが特徴だと考えております。いずれにしても、先ほど申し上げた多様な相談に答えられるという体制を敷いているです。","id":"exchange-079"},{"speaker":"阿部委員","kind":"質問","question":"その幾つかの窓口のうちの１つには、さらに大きく相談者を引きつけるといいますか、そのことについてさらにご答弁をほしいと求めました。それからあわせて質問を行いますけれども、何か新しい対策は盛り込まれるのは、その辺もあわせてご説明ください。","respondent":"市岡総務部長","answer":"どの入り口から入ってもネットワークが支えるという対応の仕方をとっておりますが、今、委員ご指摘の点については。２つ目の特徴は、どの入り口から入ってもネットワークが支えますということを、鮮明に出していきたいです。","id":"exchange-080"},{"speaker":"阿部委員","kind":"質問・要望","question":"にはぜひ、またＰＴＡへの積極的なアプローチもぜひお願いしたいと思います。この点についてご所見をお願いいたします。","respondent":"市岡総務部長","answer":"この結果等も踏まえて、今、委員のご指摘いただいた中学校の養護教諭、あるいは管理職層に対する研修について、今後検討していきたいと思います。","id":"exchange-081"},{"speaker":"阿部委員","kind":"質問・要望","question":"最後に今後のＤＶの対策の中でぜひ考えてほしいことが２つあります。この２点について、区側のお考えと、今後の対応について、現段階のお考えで結構ですので、ご所見を伺います。","respondent":"市岡総務部長","answer":"ただいまの２点のご指摘ですけれども、いずれも重要性は私どもも認識しているところです。息の長い支援ということについてもそうですが、国を含めた広域的な体制の構築ということについても、意見を申し上げていきたいと考えています。","id":"exchange-082"},{"speaker":"阿部委員","kind":"提案","question":"区議会でも多くの会派がさまざまな機会に増設を求めており、そんな中で、歓迎すべきことだと考えています。校舎を高齢者施設に転用するよう提案をしており、また民主品川としても、この計画についてはぜひ早期に進めていただきたいと考えていますとの意見を述べました。","respondent":"木下健康福祉事業部長","answer":"考えられる方策としては、複数ユニットの施設をつくるということは、高齢者施策としては新たな展開ができる。やはり小規模な土地で、そういう選択が可能な場合については、検討の対象にしていきたいと考えています。","id":"exchange-083"},{"speaker":"阿部委員","kind":"質問","question":"それはどのように調査をされたのでしょうか。区ではこの問題の本質はどこにあるとお考えか尋ねました。","respondent":"木下健康福祉事業部長","answer":"年金不正受給といういわゆる不正行為ということについては、これはきちんとした対応というのが必要かと考えています。１件は辞退ということで確認ができておりますけれども、それ以外の５人の部分につきましては、現在の品川区の状況です。","id":"exchange-084"},{"speaker":"阿部委員","kind":"確認","question":"それで今後のことを伺いたいんですけれども、所在確認にとどまらず、これを高齢者を支える基盤あるいはツールとして考えることはできないだろうか。戦略的にあるいは継続的に実施していくべきではないだろうかと思うんですが、その点についてご所見をお伺いします。","respondent":"木下健康福祉事業部長","answer":"例えばお祝い事業をお配りする中で、民生委員として気になるケースというのがあるかもしれないと思うわけであります。そういうケースについては、例えば民生委員の見守りの対象のほうにリストとして入れるというような取り扱いも、今後検討をしていきたいと思います。","id":"exchange-085"},{"speaker":"阿部委員","kind":"質問","question":"さて、地域の高齢者の見守りという点では、品川区は平成２１年度からモデル的に生活応援事業を始められました。この進捗状況と現在までの評価、そしてモデル期間終了後の扱いについて説明を求めました。","respondent":"木下健康福祉事業部長","answer":"平成２１年につきましては、社会福祉協議会の職員と民生委員のＯＢが協力し、社会福祉協議会と地域センターが連携する形を基本に進めてまいりました。買い物の同行支援という事業をモデル的に実施しておりまして、現在６人の方がこの間、その支援を受けたところです。","id":"exchange-086"},{"speaker":"阿部委員","kind":"質問","question":"どうなんでしょうか。区としてはどこが主体になって、何をどう進めていくのかということを包括的にどう考えているかということを、ご所見をお伺いします。","respondent":"木下健康福祉事業部長","answer":"コーディネートをし、考え方としては、むしろ社会福祉協議会のソーシャルワーカーにふさわしい仕事だと思うわけであります。包括支援センターの次の第５期のあり方というのが国のほうで検討されておりますから、考え方、社会福祉協議会と地域センターが連携する方式が。","id":"exchange-087"},{"speaker":"阿部委員","kind":"質問","question":"ですから、補助金を出せと言っているわけではありません。しかし、一時的に生活インフラを失って困惑している区民に、行政としてもう少し関心を持つべきだと思いますが、いかがか尋ねました。","respondent":"宮地地域振興事業部長","answer":"区といたしましては、大型の商業施設につきましても大切な区民のインフラであるということはしっかりと認識しております。公表はできないながらも、生鮮３品を中心としたスーパー等の関連施設を予定しているというお話も伺っております。","id":"exchange-088"},{"speaker":"阿部委員","kind":"質問","question":"ただスーパーが撤退したことによってハード面の課題も浮かび上がったと感じております。そして駐輪場、そういった面でさまざまな課題を感じておりますが、その点については区のお考えはいかがか尋ねました。","respondent":"片田防災まちづくり事業部長","answer":"エレベーターとかいろいろなバリアフリーの問題があります。私どものほうとしては、そういう調整をしながら、ハード面でやさしいまちづくりを進めているところです。","id":"exchange-089"},{"speaker":"阿部委員","kind":"質問","question":"この園舎の暫定活用についてはいかがお考えでしょうか。幼稚園という特性から、幼児教育あるいは保育といった面での活用も考えられると思いますが、ご所見を説明を求めました。","respondent":"日下部企画部長","answer":"したがいまして、この辺の環境をどうするかということもありますので、今後具体的に検討を進めてまいりたいと考えております。そういったことを考えますと、保育でありますとか子育て関係の利用というのは、現実的にはかなり難しいのではないかと考えているところです。","id":"exchange-090"},{"speaker":"渡部委員","kind":"質問・要望","question":"初めに子育て支援について伺います。子どもたちは自然と社会の中で、自分という地位を、その年齢ごとに判断できる力が備わっていったのではないか尋ねました。","respondent":"古川子ども未来事業部長","answer":"１つには親支援、言葉では確かに親支援と申し上げますけれども、どのような形で支援ができるだろうか。まさに３０年後に親になるであろう今の乳幼児期に、そういったものをしっかりと植え付けていくことは、私どもの仕事だろうと考えております。","id":"exchange-091"},{"speaker":"渡部委員","kind":"質問・要望","question":"１つ、具体的なところを確認させていただきたいんですが、入園に際しての対象者条件に、居宅外で常時働いている場合とあります。入園ができればしっかり就業していくんだという方々に対して、このポイント、点数はどのように勘案されているのか尋ねました。","respondent":"古川子ども未来事業部長","answer":"なかなか入れない状況に対しましては、次年度に向けてのさまざまなご相談に応じ、きめ細やかな対応をしています。ただ、今現在、この指数につきまして、より実態に沿った形に改善すべきではないかと、保育課内部での検討を進めているところです。","id":"exchange-092"},{"speaker":"渡部委員","kind":"質問","question":"前の質問でも触れましたが、小学校、中学校の教育上必要なものは何なんでしょうか。地域や他の保護者に対しても事例を公表し、皆で話し合うことも必要と考えますが、いかがか尋ねました。","respondent":"市川教育次長","answer":"その際には、家庭で何をどうするべきか、どうしてもらいたいのかということを具体的に伝えることが大切だと考えております。委員から具体的なご提案もございましたけれども、学校のさまざまな事情を見極めた上で、それぞれ対応すべきものと考えています。","id":"exchange-093"},{"speaker":"渡部委員","kind":"質問・要望","question":"親子で参加できるプログラムの開発などを行って、もっと積極的な取り組みを希望しますが、いかがでしょうか。環境教育、この自然体験に対する教育委員会の考え方をお伺いさせてください。","respondent":"市川教育次長","answer":"現在行っております日光の校外施設での実施と比較検討いたしました場合、現段階では、実施プログラムを組む上で大きな調整課題があります。","id":"exchange-094"},{"speaker":"渡部委員","kind":"質問・要望","question":"何らかの特例を求めますが、いかがですか。そうしますと、学校ごとにもう一度ブロックを見直すなど行っていかれますか尋ねました。","respondent":"市川教育次長","answer":"そのあたりのことにつきましては、荏原東地区、豊葉の杜学園の開校を一つの節目として、検討してまいりたいと考えています。本年度、城南第二小学校で講じました学校選択制の運用上の工夫など、暫定的な対応策も視野に入れて対応してまいりたいと考えています。","id":"exchange-095"},{"speaker":"渡部委員","kind":"意見","question":"単独校１校の工事であれば、近隣の学校を他の活動団体に調整を依頼して、一部間借りするなどで対応してきていました。それぞれお答えをお願いしますとの意見を述べました。","respondent":"市川教育次長、古川子ども未来事業部長","answer":"極力校庭、敷地の制約から、従前の広さを持つ校庭などの確保ができないケースが実際あります。屋内体育館にかわる適地、あるいは代替施設を近隣に確保すること自体が難しい状況のもとでは、かなり困難な課題だと受けとめてあります。こじれてしまいますと、なかなか双方がテーブルにつくこと自体が非常に難しいというふうになってまいります。","id":"exchange-096"},{"speaker":"渡部委員","kind":"質問・要望","question":"次に、高齢者を取り巻く環境について伺います。それとショートステイというのは最大で現状何日可能か尋ねました。","respondent":"木下健康福祉事業部長","answer":"それから、ショートステイの日数ですけれども、原則７日です。それから、在宅でケアプランを作成している方という形で見ますと、３月末で６,０４４人という数字になっております。","id":"exchange-097"},{"speaker":"渡部委員","kind":"質問","question":"要介護４、５等の方が自宅にいた場合、なかなか建て替えの計画にもならない。区は相談できる体制は、その要介護４、５の方がどこかで預かれるような体制はあるのか尋ねました。","respondent":"木下健康福祉事業部長","answer":"今、ご指摘のありましたようなケースですと、ショートステイの制度の中ではなかなか難しいのではないかと思います。標準的には６カ月、１年というところもありますので、お勧めするというのが現在の対応です。","id":"exchange-098"},{"speaker":"渡部委員","kind":"質問・要望","question":"区民に対して、民生委員とはこういう仕事をする人なんだよというのを広報していただけるよう求めますが、いかがでしょうか。もう１件、町会からの選任が非常に難しくなった場合、どのように選任されていくのか、教えていただけますか尋ねました。","respondent":"木下健康福祉事業部長","answer":"今回も大変苦労された町会等もいらっしゃるわけなんですけれども、私どもといたしましては、民生委員の活動をどう我々が支援するか。勉強になった、そのようなことを地域の中に発信していくようなことが、大事ではないかなと思っているところです。","id":"exchange-099"},{"speaker":"渡部委員","kind":"質問・要望","question":"引き続き支援を要望いたします。区民の使いやすいシステムにしてほしいと思いますが、いかがか尋ねました。","respondent":"宮地地域振興事業部長","answer":"お尋ねの商店街に属さない商店ということですが、約６５０店舗あります。そういう意味では支援をしていきたいと考えています。","id":"exchange-100"},{"speaker":"渡部委員","kind":"質問","question":"こういうことが区ではできないでしょうか。いかがか尋ねました。","respondent":"宮地地域振興事業部長","answer":"捨てられないでずっと使っていただくということが基本ですので、気に入られるようなデザイン等、課題はあろうかと思いますが、研究させていただきたいと思います。","id":"exchange-101"},{"speaker":"渡部委員","kind":"質問","question":"１つ、タクシーのことについて伺います。いかがか尋ねました。","respondent":"宮地地域振興事業部長","answer":"ボタンだけでは通じないので、この場合にはいろいろな整備、設備が必要となります。大変難しい課題ですので、今後動向を見ていきたいと考えております。","id":"exchange-102"},{"speaker":"藤原委員","kind":"質問","question":"今後の政策展開と財政運営についてお伺いしますが、エコポイントの半減など、マイナスの要素が増えました。まず数字からお伺いしますけれども、平成２１年度決算と平成２２年度の決算見込みとの比較について、まずお伺いします。","respondent":"金子企画財政課長","answer":"平成２２年度についてはまだ少し粗い見込みになりますが、区民税で３６０億円、大体３０億円ほどの減になるかと思います。財政調整交付金については、まだ特別交付金が明確でありませんけれども、３６２億円ほど、やや平成２１年度より多いかなと見込んでいるところです。","id":"exchange-103"},{"speaker":"藤原委員","kind":"質問","question":"相当大きな減収だと思うんですけれども、比べて、目黒区は減収が１００億円でしたよね。２年比べると、品川区も８０億円近く減収となっているんですけれども、改めて品川区は大丈夫なんか尋ねました。","respondent":"金子企画財政課長","answer":"逆に品川区が７０９億円で目黒区が２１０億円と、約３分の１以下ということで、目黒区はすべての指標で悪くなっております。品川区は、経常収支比率が７４.６％で、２０ポイント以上の開きがありまして、財政の健全度としましては、はるかに品川区のほうが高いものです。","id":"exchange-104"},{"speaker":"藤原委員","kind":"質問・要望","question":"いつどうなるかわからないという思いで、危機感を持って、健全財政に努めてほしいと求めました。「小さな区役所から大きなサービスを」であると思うんですけれども、このスローガンを具体的にどう推進していくのか、財政を含めてお伺いします。","respondent":"金子企画財政課長","answer":"事業の思い切った選択と集中、つまり時代の変化に対応しまして、新たな行政ニーズにも対応させる財政基盤を確立していくという考え方であります。こうした手法によりまして、地域経済の活性化と区民生活の安定を目指して、施策を展開してまいる考えです。","id":"exchange-105"},{"speaker":"藤原委員","kind":"質問","question":"入園申込者の増加の原因についてお伺いするんですが、子育ての孤立感、心理的な圧迫感が親御さんにあるのではないかなという思いがあります。そこまでいかなくても、潜在的な入園希望者は相当数がいると思うんですけれども、改めてその増加についての原因をお伺いします。","respondent":"古川子ども未来事業部長","answer":"しかしながら、その内実はさまざまであろうと考えています。深夜の１０時ぐらいまで働く方もいらっしゃいますので、そのような中では、さまざまに今後も対応をとっていきたいと考えております。","id":"exchange-106"},{"speaker":"藤原委員","kind":"質問・要望","question":"来年は２園の私立保育園が開園すること、認証保育所も開設することですが、区立保育園の認可保育園の増設だけが解消策にはならないと思っています。受け入れてもらえる施設を求めていると思っているんですけれども、三年の申込者の動向と、受け入れ見込みの計画についてお伺いします。","respondent":"古川子ども未来事業部長","answer":"この動向につきましても、大変難しい、先ほどの要因との関係があります。来年４月に向けましてはそれを上回る拡大、これは定員外ですけれども、認可保育園の定員の拡大というような対策を講じていきたいと考えております。","id":"exchange-107"},{"speaker":"藤原委員","kind":"質問","question":"介護予防についてお伺いしますが、まず数字を伺いますが、その中で介護予防に参加されている方がどのくらいいるか。それと、この事業の整理体系化についてどういうふうに考えているか、お尋ねします。","respondent":"木下健康福祉事業部長","answer":"対象者の考え方ですけれども、６５歳以上の人口の５％ということでありますから、３,０００人強という数字を想定していたところであります。","id":"exchange-108"},{"speaker":"藤原委員","kind":"質問","question":"データということが大事だと思うんですけれども、この事業を実施するにあたって、データの分析をしないのか。それをどういう形で反映していくのかという考えを改めてお伺いしたいのと、特定健診のように、目標とか計画などがあれば説明を求めました。","respondent":"木下健康福祉事業部長","answer":"平成１８年に始めたころは、前屈でどのくらい曲がることができるかとかいうのを、事業の開始前と後で調べました。そういう点では、先ほど申し上げた２５のチェックリストに基づく効果というのを、現在では考えているところです。","id":"exchange-109"},{"speaker":"藤原委員","kind":"質問・要望","question":"商店街連合会の補助金が１,５００万円余、この内容について説明をいただきたいのと、これまで続けてきた成果についてお伺いします。それと、この中にマイ箸運動も入っていると思うんですが、この事業の内訳と成果についてもお伺いします。","respondent":"岩田都市環境事業部長","answer":"平成１４年度からこのマイバッグ運動は実施しておりまして、成果といいますと、加盟商店からエココインを１枚いただけることになっております。経費につきましては、昨年で約８０万円、区商店街連合会のほうに補助金を出しております。","id":"exchange-110"},{"speaker":"藤原委員","kind":"質問・要望","question":"何かお考えがあったら教えていただきたいのと、商店街連合会への補助金なんですけれども、見直されるという考えはあるんでしょうか。有料化のほうがみんなが守りやすくて、成果が上がると私は思っているんですけれども、その辺についてはいかがか尋ねました。","respondent":"岩田都市環境事業部長","answer":"約９５％が間伐材ではなくて、これは現在やっている規模で、来年度以降も続けていきたいと考えています。１人あたり０.３枚という数ですので、ＣＯ２対策あるいは地球環境問題として継続していきたいと、今のところは考えております。","id":"exchange-111"},{"speaker":"藤原委員","kind":"質問","question":"次に、産業振興についてお伺いしますが、まず、融資あっ旋についてですが、現在の緊急対策、３年間無利子の施策が、多くの事業主から喜ばれている。区の負担についてはどれほどなのか尋ねました。","respondent":"宮地地域振興事業部長","answer":"平成２０年度が２,２８６件で１３０億８,９７０万円、それから、平成２１年度は２,９１１件で２２０億４,２００万円という実績になっております。平成１９年度が２億９,７７７万円、平成２０年度が４億１,６３２万円、平成２１年度で９億３,６０７万円となっております。","id":"exchange-112"},{"speaker":"藤原委員","kind":"質問","question":"単純な継続ではなく、重点化を図るという形で言っていると思うんですけれども、この国の動向と今後の区の施策は変更がまずあるのかどうか。数字を伺いましたけれども、そういった方への新たな対応について、区として考えがあるか説明を求めました。","respondent":"宮地地域振興事業部長","answer":"確かに政府が、来年４月以降に単純延長を行わないという方針を固めたと聞いております。区といたしましては、こうした国の動き、それから経済の動向等を注視しながら、やはりしっかりと見ていかなければいけないと考えております。","id":"exchange-113"},{"speaker":"藤原委員","kind":"確認","question":"プレミアム付区内共通商品券についてお伺いしますが、この商品券の財源構成がどうなっているか、事業費ベースでお答えください。２３区のほかの区で、それはないということを確認したいので、そのことも質問をします。","respondent":"宮地地域振興事業部長","answer":"具体的に申し上げますと、商品券を販売しているのは、４２カ所の郵便局を含む５０カ所の拠点で商品券を売っております。性別、年代等を書いていただいておりますので、そうしたことはないと考えております。","id":"exchange-114"},{"speaker":"藤原委員","kind":"質問","question":"そのときと違って、今の現状は、まだまだカンフル剤としての商品券の発行というのをしなくてはいけないと私は思っております。款別審査のときも、ぜひとも来年度も継続するようにお願いしたいと考えていますが、その辺についてはどうか尋ねました。","respondent":"宮地地域振興事業部長","answer":"が、やはり緊急経済対策という視点で、品川区ではこのプレミアム付商品券を発行しております。世界の景況等々を含めまして、あくまでも緊急のときに発行するものだと認識しておりますので、ご理解のほどよろしくお願いいたします。","id":"exchange-115"},{"speaker":"藤原委員","kind":"質問・要望","question":"ご理解できないので、また質問をしますけれども、この間、今年２回目の発行をしましたよね。品川区は商店街活性化のために施策をと言っているんですから、もうちょっと前向きに考えるとか、その辺についてはいかがか尋ねました。","respondent":"宮地地域振興事業部長","answer":"今回のプレミアム付商品券、秋の分はほんとうに早く完売いたしました。力というのはほんとうにすごいものだと考えていますが、私はあくまでも緊急時の施策だと判断しておりますので、この先のことはお約束できないです。","id":"exchange-116"},{"speaker":"藤原委員","kind":"質問・要望","question":"再開発事業についてお伺いしますが、改めてその辺をお伺いさせていただきたいと思うんですけれども、改めて伺います。財源についてはどういうふうにしているか、お伺いします。","respondent":"片田防災まちづくり事業部長","answer":"あるいは平成１３年につくりました市街地整備基本方針、将来のあるべき形ということで、私どもまちづくりを進めてまいりました。どのような支援をしてきたかというご質問ですけれども、まちづくり事業にかかる事業者、これらの方を支援してきたという状況です。","id":"exchange-117"},{"speaker":"藤原委員","kind":"質問","question":"広く集められた税金を特定の地域に集中的、限定的に投入をしていいのか。再開発事業に税金を投入する意義を、改めてお伺いします。","respondent":"片田防災まちづくり事業部長","answer":"将来のまちづくりの構想といいましょうか、その都市像を実現するということで、私どもこれまでそれぞれのまちづくりを進めてまいりました。人と物の行き来ができて、そういう形の中でトータル的な再開発を評価しておりますし、そこに意義があると考えています。","id":"exchange-118"},{"speaker":"藤原委員","kind":"質問・要望","question":"最後に、今まで具体的な施策を伺ってきましたけれども、この施策を実現していく区の職員の皆さんの確保、それと、人材育成についてお伺いします。平成１９年度から開始された民間企業の経験者採用について、この制度の概要と、品川区のこれまでの採用実績と効果についてお伺いします。","respondent":"市岡総務部長","answer":"ここ数年を見てみますと、大体品川区の採用予定数の２倍から２.７倍という数字ですので、かなり人気があるかなと考えています。これまでこの３年間で、事務、技術合わせて約７０人採用しておりまして、来年度も２０名程度採用の予定をしております。","id":"exchange-119"},{"speaker":"藤原委員","kind":"質問","question":"その辺の説明と、あと、職員の自己啓発ですね。仕事に役立つ資格の取得の支援とか、ありましたら説明を求めました。","respondent":"市岡総務部長","answer":"１つは、我々も職員育成の１つのポイントだと考えておりまして、もう少し広げていきたいと考えています。これを行う予定ですが、いわゆる公共政策大学院の修士課程を修了した職員が２人出ておりまして、その戦力になってもらいたいと考えています。","id":"exchange-120"},{"speaker":"藤原委員","kind":"質問","question":"人材を確保して育成していっているというのがよくわかりましたが、区の職員というのは、一番の基本というのはサービス業ですよね。来庁者に対してのサービス業だと考えていますが、その一番の基本というのは思いやりだと思うんですけれども、その辺はいかがか尋ねました。","respondent":"市岡総務部長","answer":"それらを含めて、引き続き人材育成については、十分力を入れていきたいと考えています。","id":"exchange-121"},{"speaker":"市川委員","kind":"提案","question":"異変に気づいた年齢の約７５％が１０歳から２４歳という実態を考えれば、何といっても必要と言えるのではないでしょうか。伺いますが、中学校では第１学年で、高校では入学時と次の年次で学習をするということにしておりますとの意見を述べました。","respondent":"市川教育次長","answer":"５年生の市民科でも同様の趣旨を持った授業を実施しています。毎日一番身近にあります担任教員の気づきということが大切なことだということで、そうした対応を心がけるように、研修等で指導している面もあります。","id":"exchange-122"},{"speaker":"市川委員","kind":"質問","question":"区における子どもの相談事業の体制についてですが、相談する機関として、どのようなところがありますでしょうか。その相談にはどのような方があたっていらっしゃるのでしょうか、お聞きいたします。","respondent":"市川教育次長","answer":"こちらにつきましては、主として臨床心理士の資格を持ったカウンセラーが対応しています。心のフリーダイヤルということで、いじめ等の対応にもあたってあります。","id":"exchange-123"},{"speaker":"市川委員","kind":"提案","question":"平成２２年度は、２４市区に導入が拡大され、活用が高く評価をされているところです。人材育成を提案いたしますけれども、このことについてのご見解を伺いますとの意見を述べました。","respondent":"市川教育次長","answer":"そうした意味で、私どもは相談を受ける際の懐の広さというか、いかに相談内容に対応していくかということが大切なことだと考えています。スクールソーシャルワーカーの人材がどうかということを考えますと、私ども区がとっている対応が、実務的にも有効であると考えています。","id":"exchange-124"},{"speaker":"市川委員","kind":"提案","question":"これまで多くの会派がスクールソーシャルワーカーの配置の提案をされましたけれども、全く同様な答弁であったと記憶をしております。その辺の違いというところを再度お伺いいたしますとの意見を述べました。","respondent":"市川教育次長","answer":"スクールカウンセラーとスクールソーシャルワーカーの役割なりあるいは機能は、同じだとは決して考えてございません。スクールソーシャルワーカーの育成ということについては、社会の制度なり仕組みなり、その辺の手当が必要ではないかとも考えてあります。","id":"exchange-125"},{"speaker":"市川委員","kind":"質問・要望","question":"続きまして、プラスチックごみの削減について伺います。今後もこの取り組みをさらに推進していくべきと考えますが、これについてはいかがか尋ねました。","respondent":"太田品川区清掃事務所長","answer":"そういう意味を考えますと、今回の分別変更については、区といたしましては、一定の成果があったと考えているところです。さらに今後、発生抑制に努め、分別の徹底を図りながら、資源として回収をしていきたいと考えているところです。","id":"exchange-126"},{"speaker":"市川委員","kind":"質問","question":"見解を伺います。絶えず人が動いている区にあっては、啓発活動も積極的に間断なく行われなければなりませんけれども、これについてお考えを伺います。","respondent":"太田品川区清掃事務所長","answer":"区はこれまでも平成２０年１０月の分別変更時に、いろいろな広報媒体を活用して、区民の方への周知をしてまいりました。３点目の、あるいは汚れのひどいものは資源化ルートに乗せられないということも考え合わせますと、難しいのではないかと考えているところです。","id":"exchange-127"},{"speaker":"市川委員","kind":"質問","question":"広報活動といえば、リサイクル事業における区の費用負担の現状を区民に伝えることで、問題提起することも重要です。すなわち廃棄物会計を明らかにするということが必要だと考えますけれども、これについてどのようにお考えか尋ねました。","respondent":"太田品川区清掃事務所長","answer":"今年の１月１１日号の広報におきましても、それから、区民１人あたりの経費について広報しています。今後についても、品目ごとに経費の広報については研究をしていきたいと考えています。","id":"exchange-128"},{"speaker":"市川委員","kind":"質問","question":"拡大生産者責任の考え方についてのご見解を伺います。確立に向けた取り組みについても伺います。","respondent":"太田品川区清掃事務所長","answer":"再生利用を考え、製品を生産し、事業者の資源循環のリサイクルにおける責任を明確にする必要があると認識しています。そうした考え方に基づき、これまでも特別区長会を通じて、現行の容器包装リサイクル法の改正を国へ要望しています。","id":"exchange-129"},{"speaker":"市川委員","kind":"提案","question":"続きまして、選挙の投票率を上げるためにということで伺ってまいります。提案もされましたが、まだやれることはいくらでもあるのではないかという問題意識から、何点か伺いますとの意見を述べました。","respondent":"早津選挙管理委員会事務局長","answer":"都議会議員選挙もそうでしたが、そういう傾向もありまして、低減傾向に歯どめがかかりつつあるような傾向も一方では見られます。具体的な努力としましても、今回におきましては、３点ほど新しい試みをしたところです。","id":"exchange-130"},{"speaker":"市川委員","kind":"質問・要望","question":"その３点という新しい試みについても、少しお聞かせほしいと求めました。","respondent":"早津選挙管理委員会事務局長","answer":"告示日の前日にＳＬ自動車を使いまして、明るい選挙推進委員の方に出動していただきまして、区内４カ所の駅前広場において啓発活動を行いました。これが事前の３点ですが、その後、選挙期間中においても、４点ほどのＰＲ活動の充実を行ったところです。","id":"exchange-131"},{"speaker":"市川委員","kind":"質問・要望","question":"選挙管理委員会として、選挙公報はもちろんのこと、選挙時に認められている法定ビラを多くの人に届けられるよう、どんなことができるのか。選挙管理委員会の議題として議論をしてほしいと求めましたけれども、これについてはいかがか尋ねました。","respondent":"早津選挙管理委員会事務局長","answer":"したがって、その配布についても同じことになります。私ども集合住宅も含めまして、それについては選挙管理委員会の職員が赴いて配布するという形で、徹底をしています。","id":"exchange-132"},{"speaker":"市川委員","kind":"質問・要望","question":"研究してほしいと求めましたが、いかがでしょうか。早い設置を要望いたしますが、いかがか尋ねました。","respondent":"早津選挙管理委員会事務局長","answer":"それから、ポスター掲示所につきましては、今回は５日前の９月２１日火曜日から４日間で設置を行いました。そういったことも総合的に考えながら、適切な設置時期というものを考える必要があろうかと考えております。","id":"exchange-133"},{"speaker":"松澤委員","kind":"質問・要望","question":"平成２１年１月に編成した補正予算に盛り込んだ緊急総合経済対策を、平成２１年度も引き続き積極的に進められたことを評価いたします。最後に、来年度予算に反映されることを強く要望いたしまして、品川自民党区議団の意見表明といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-134"},{"speaker":"若林委員","kind":"提案","question":"３年間無利子の中小企業融資あっ旋事業や、公明党提案の施策を含め、区民サービスの向上が一定図られたものと評価をいたします。提案した施策の反映など、サービスの充実に向け一層の努力を傾注されるよう要望し、意見表明といたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-135"},{"speaker":"菊地委員","kind":"質問・要望","question":"次年度以降も継続すること、２０１５年までに住宅の耐震化率を９０％にする計画に責任を持ち、地域経済を支えてきた中小企業への全面支援を求めます。以上、我が党は住民こそが主人公の立場で区政運営を行うよう求めて、意見表明とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-136"},{"speaker":"土井委員","kind":"意見","question":"易者の５つの顔に加え、子どもたちを導く体制整備と、都からの人事権移譲の取り組みに期待をいたします。我が会派議員のもろもろの提起が取り上げられることを期待いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-137"},{"speaker":"須貝委員","kind":"質問・要望","question":"格差社会と言われ、二極化が加速している区民生活、社会福祉の観点からも、生活に困っている区民を支援するさらなる政策を要望します。塾によって支えられている公教育の改善を要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-138"},{"speaker":"西本委員","kind":"提案","question":"将来を見据えて区民の利益を最優先に考え、限られた財源を最大限に生かしていく政治姿勢が求められていくものと考えます。我が会派で提案、要望した各項目について、区政運営に生かしていただくことを強く要望しとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-139"},{"speaker":"井上委員","kind":"提案","question":"関係機関と付置義務の協議を積極的に行い、毎年撤去啓発費用を２億円弱かけるという対策ではない政策の転換を求めます。最後に、提案をさせていただいた意見を予算編成に生かしていただくことを要望し、生活者ネットワークの意見表明を終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-140"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/260957?Template=document&Id=1336#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":124021,"voices":306}},{"id":"h22-20101130-9","meetingId":"h22-cm11","date":"2010年11月30日","dateIso":"2010-11-30","committee":"文教委員会","time":"午後１時１２分～午後１時４０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を5件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"１の週休日というところの説明をいただきたいのと、４時間と３時間４５分が半日振替えになった場合、教えていただきたい。２のところで、下の(2)に該当者がないと書いてありますけれども、どういう方が再任用になるのかということを説明を求めました。","respondent":"冠木指導課長","answer":"この説明で出てくる状況というのは、学校の教員は、決められた期間内にその勤務の振替えをすることができることになるわけです。品川区では、今のところは、そういう方はいらっしゃらないです。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"私学の教育職員とか、幼稚園の職員とかと比較することはあるんでしょうか、そういうことは一切ないのでしょうか。ちょっとそこが気になったので、教えていただけたらと思います。","respondent":"冠木指導課長","answer":"民間の事業所の一つとして、私立の幼稚園などが入っている可能性はあろうかと思いますが、細かいデータまでは持ち合わせておりません。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺の役職がどうなると、給料が上がっていくのか、基本的なところを教えていただきたい。それから、１０月に、幼稚園が３級から４級になるというお話があって、それはいつからなのかも含めて、説明を求めました。","respondent":"冠木指導課長","answer":"説明をさせていただいたように、職層に合わせて給料表も定めるべきであるという勧告が２年前ぐらいに出ておりまして、その給料表が入ってくるです。この辺につきましてはまた、詳細がわかってまいりましたら、議会のほうでご審議等をいただくことになろうかと思います。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１０月に、職員の平均年間給料が約１０万８,０００円、１.６％下がるというご説明をいただいたんですけれども、この部分と地域手当の１％の部分で、結果的にどうなるのか、わかりやすく説明していただきたいんです。","respondent":"冠木指導課長","answer":"おおむね４０歳真ん中ぐらいの方々ということで、平均で約１.６％、年間で約１０万８,０００円の減になるという説明をさせていただいたところです。さらに公民較差の０.３％の部分も含めて、この給料表が変わったです。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"意見","question":"５０人以上の企業との比較において、結局、やはり人事院勧告制度の根幹自体を見直していかなくてはいけない部分もあるのではないかと考えています。でも、労使で合意をしているということなので、反対はしないといった意味での、消極的な賛成をしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/746735?Template=document&Id=4716#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":7604,"voices":28}},{"id":"h22-20101130-5","meetingId":"h22-cm11","date":"2010年11月30日","dateIso":"2010-11-30","committee":"総務委員会","time":"午後１時１２分～午後１時４１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を8件整理しています。","topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"土井委員","kind":"質問","question":"減額改定ということなんですけれども、ちょっと整理をする意味で、ここ数年間、どれぐらい下がったのか、わかりますか。というのは、ほかのところにも影響があるものですから。","respondent":"榎本人事課長","answer":"マイナスが６回ありまして、トータルしてマイナス４.５２％という形で、マイナスの回数が多くなっております。平成２１年度が０.３８％、平成２２年度が０.３０％という形で、マイナスが続いている形です。","id":"exchange-001"},{"speaker":"須貝委員","kind":"意見","question":"２３区人事委員会勧告の大前提として、民間従業員の給与水準と均衡させる、要は較差是正させるということが根本にあると思うんです。その辺について、どのようなお考えを持っているのか、説明を求めました。","respondent":"榎本人事課長","answer":"東京都と区を中心に、医師の人材を確保しようとしているんですけれども、なかなか欠員状態が解消できないという状況が続いております。そういった面から、医師の給料表につきましても、引き下げをしないという判断したものです。","id":"exchange-002"},{"speaker":"宮崎委員","kind":"意見","question":"それから、平均の支給として、年収でどうなっていくのかということ。それから、今回の冬の一時金、そこのところはどういうふうな影響になるのか、聞きたいんですけれどもとの意見を述べました。","respondent":"榎本人事課長","answer":"この１２月で精算をしまして、期末部分につきましては、年度末の期末手当で精算をするという形で提案をしているものです。０.０５月のマイナスで、期末手当部分が０.１５月のマイナスということで、合わせて０.２月のマイナスという形になっているものです。","id":"exchange-003"},{"speaker":"宮崎委員","kind":"質問・要望","question":"総額としても、２億６,５００万円ということなんですけれども、基本的に区の職員全員が対象になるのかどうかということ。５０歳代後半のところをかなり下げているようなんですけれども、そういうところがわかっていたら、教えていただきたいんです。","respondent":"榎本人事課長","answer":"医療職の方も、本俸は下げないですけれども、期末・勤勉手当は下がりますので、そういった意味で、全員という形のものです。課長級で下がるのが１５万円、部長級で１８万６,０００円という形で、年間で１万３,０００円下がるという形になっています。","id":"exchange-004"},{"speaker":"宮崎委員","kind":"意見","question":"そういうところをどういうふうに見ているのかというと、このままでいいのかと、いつも感じてしようがないんです。そこのところは、どういうふうに、今後の方向というのを考えているのか聞きたいんですとの意見を述べました。","respondent":"榎本人事課長","answer":"なぜこういう形になるかというと、ボーナスは１回前の水準と比べている、半期ずれるという形になります。後から公務員のほうがそれに合わせていくような関係になっておりますので、民間のほうのボーナス水準は２年ぶりに増加という形と認識をしています。","id":"exchange-005"},{"speaker":"宮崎委員","kind":"質問","question":"そういう事実があるわけですから、公務員の生活をどうするんだと、このままどこまで進んで行ってしまうのだろうなという感じがします。これは意見ですけれども、言っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"林委員","kind":"質問","question":"直接、この数字とかには関係ないかもわからないけれども、現場の人たちとの交渉の中で、一番話題というか、課題というか、その辺のお話は聞けるものですか、ここで、現場の声という意味で、聞かせてもらえる部分があったらお願いします。","respondent":"榎本人事課長","answer":"ある程度、職員も認識はするんだけれども、やった成果の部分がどうしても反映されづらいという意見があります。２年連続でボーナスが下がるという形になって、どうやっても、なかなか気持ち的に割り切れないというのが一番大きいのかなと感じているところです。","id":"exchange-007"},{"speaker":"林委員","kind":"質問","question":"２３区でこういうふうに考えて、人事委員会というものに対して、品川区は独自に現場と交渉していくよというような流れにはならないものなのですか。教育職員なんかは、品川区独自の形を出していくという検討ぐらいはしてもいいのではないかなという気がするんですけれども、いかがなものか尋ねました。","respondent":"榎本人事課長","answer":"やはり、各区の独自性という意味でのいろいろな検討はしてきているところです。やりたい意欲はやまやまですけれども、その辺の実務部分を考えると、かなりいろいろな課題があるかなと感じているところです。","id":"exchange-008"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/212618?Template=document&Id=1870#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":8878,"voices":29}},{"id":"h22-20101213-6","meetingId":"h22-cm12","date":"2010年12月13日","dateIso":"2010-12-13","committee":"区民委員会","time":"午前１０時０２分～午前１１時３６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件整理しています。","topics":[{"id":"topic-01","title":"議案審査に移ります。 初めに第９２号議案、品川区地域センターの設置に関する条例の一部を改正する条例および(2)第９３号議案…","agenda":"議案審査に移ります。 初めに第９２号議案、品川区地域センターの設置に関する条例の一部を改正する条例および(2)第９３号議案…","exchanges":[{"speaker":"山内委員","kind":"質問","question":"荏原第三地域センターのほうなんですけれども、ちょっとこの地図で、校庭はどこになるんですか。上部のほうが２６号線でしたっけ。","respondent":"中山地域活動課長","answer":"右が２６号線です。","id":"exchange-001"},{"speaker":"山内委員","kind":"質問","question":"右が２６号線ですね。ということは、右側のところに校庭があると考えていいということか尋ねました。","respondent":"中山地域活動課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"山内委員","kind":"質問","question":"この出入り口は、今まで学校で使用していたときと変わらないような出入り口といったことでよろしいんか尋ねました。","respondent":"中山地域活動課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"山内委員","kind":"質問","question":"地域の方は理解されていますが、やはりここを普段活用されている方、改めましてその周知はどのようにされているのか。例えば区の掲示板等々、そういった周知をされているかとか、そういったところを改めましてお伺いしたい。","respondent":"中山地域活動課長","answer":"予定といたしまして、２６号線に近い側、ここにグラウンドへの入り口を設ける予定です。一応地元への説明の場面を設けるかどうかについて、何らかの説明、その他の全体の敷地の扱いについての説明をする場面を一つ設けたいと考えています。","id":"exchange-004"},{"speaker":"山内委員","kind":"確認","question":"最後に１つ確認なんですが、一時的な仮移転をしますけれども、業務的なことというのは時間等々すべてにおいて変更はなく、今までと同じといった考え方でよろしいのか、最後にそれを確認だけ。","respondent":"中山地域活動課長","answer":"行政窓口、あるいは区民集会所の時間を含めて、一切従来と変更はございません。","id":"exchange-005"},{"speaker":"渡辺委員","kind":"確認","question":"荏原第三地域センターのほうで図面をもとに何点か確認で伺いたいと思います。トイレの改修というか、手の入れ方を伺いたいのが１つと、もう１つは空調の関係の確認。","respondent":"中山地域活動課長","answer":"実は２階については、どこでもトイレ、身障者用トイレについては１階で利用いただくという考え方をとっているものです。排煙と申しますか、少し敷地のわきに逃げていただいて喫煙をしていただくという考え方ですので、あえて排煙施設等は設けないです。","id":"exchange-006"},{"speaker":"渡辺委員","kind":"質問","question":"その辺の見解を伺いたいのと、もう１点、明るさというか、もとの学校の際は相当数の方やいろいろな出入りがあった。周辺も含めた明るさの確保というんですか、何か活気があったようなところから、その点を伺えればと思います。","respondent":"中山地域活動課長","answer":"逆に今までは学校ですから、いわゆる校舎の裏部分については閉鎖をして入れないようにして、事故等が起こらないようにしてまいりたいと考えています。","id":"exchange-007"},{"speaker":"菊地副委員長","kind":"質問","question":"１年と三、９,０００万円の予算というのは結構大きなものだと思うんですけれども、この中身であったりするんか尋ねました。","respondent":"中山地域活動課長","answer":"約３,０００万円というのが新しい施設の改築に向けての基本設計、実施設計。基本的には最小限必要な地元の方への利便を確保する執行と考えておりますので、工事の概要、契約についても詰めておるところです。","id":"exchange-008"},{"speaker":"菊地副委員長","kind":"質問・要望","question":"もう１つお聞きしたいんだけれども、その後の活用方法についてお考えがあるのかどうかというところ。同時に２階を地元に開放するというのは、地元開放はどうなるのかというところを教えていただきたいのと、窓口はどこにどうやって申し込んで。","respondent":"中山地域活動課長","answer":"これは、基本的には在宅介護支援センターを運営している社会福祉法人の運営にゆだねるという形になりますので、ご説明申し上げたとおり。","id":"exchange-009"}]},{"id":"topic-02","title":"第９６号議案、指定管理者の指定","agenda":"第９６号議案、指定管理者の指定","exchanges":[{"speaker":"菊地副委員長","kind":"意見","question":"５年を終えて指定管理者をもう１度見直しということなんですけれども、今、いわゆる途中で別の法人になるわけですよね。その辺の関係というのはどうなっていくのか、ちょっと明日の報告になってしまうかもしれないんですけれども、すみませんとの意見を述べました。","respondent":"堀越文化スポーツ振興課長","answer":"公益財団法人の認定の予定というのが平成２４年度以降という形ですので、そのあたりで一定確認と整理は必要になってくると思います。","id":"exchange-010"},{"speaker":"菊地副委員長","kind":"確認","question":"ただ、さっき、いわゆる同一主体かどうかを確認したりとか、そういうのはしなくてはならないかもしれないというお話でしたね。そうすると、その段階で、５年の指定管理の期間を待たずに、もう１度議会に上がってくる可能性も含めてということなんか尋ねました。","respondent":"堀越文化スポーツ振興課長","answer":"明日ご説明しますけれども、事業の目的ですとか設立目的、そういったものについては大きな変化はないと思っています。登記によって、新しい公益財団法人に変わるという、それだけとご理解いただければと思います。","id":"exchange-011"},{"speaker":"山路委員","kind":"意見","question":"指定管理者の指定については説明がありました。どうしても民間ではだめだという、そういうものを検討されたと思うんですけれども、そこを聞かせていただければとの意見を述べました。","respondent":"堀越文化スポーツ振興課長","answer":"それともう１点、そこを中心に行っていくという中で、やはりこの区の文化振興を図る財団との連携が必要だと考えています。これまでの実績、品川区民芸術祭の一体的な運営という観点から、民間事業者よりは文化振興事業団のほうが適していると判断をしたものです。","id":"exchange-012"},{"speaker":"山路委員","kind":"質問","question":"全体に付随するそういうところはどういう、この指定の品川文化振興事業団と大手メーカーと話をされて、仕切りをやられているか。その大手メーカーでも指定管理者としての能力というか意思があるのではないかと思ってきたんですけれども、その辺はどうなんか尋ねました。","respondent":"堀越文化スポーツ振興課長","answer":"今、どういうようなやり方をしているかという部分からお答えしますと、その中で基本的な全体の管理は管理組合の考え方に沿ってやります。そういった面で管理体系の複雑なところもございまして、私がお話しする中では聞かせていただいているという部分です。","id":"exchange-013"},{"speaker":"山路委員","kind":"意見","question":"ということは、選考基準で品川文化振興事業団がいいということですけれども、ただ、大手メーカーも総合的にやりたいという意思を示した場合に、民間とその財団とが競うというか、こういう検討というのは現状では考えられないのかとの意見を述べました。","respondent":"堀越文化スポーツ振興課長","answer":"きゅりあんが基本的には区民への貸し出し施設というところなんです。区と連携しながら、今回は区としての考え方といたしまして、今のところは考えてございません。","id":"exchange-014"},{"speaker":"山路委員","kind":"質問","question":"もしあったとすればです。いろいろな面で総合的に競うところでいいものが出るのだったら、そういうことも研究課題に入れておくべきだと思うんですけれども、どうお考えか尋ねました。","respondent":"堀越文化スポーツ振興課長","answer":"そのあとのいろいろな清掃等の部分についても、実際専門性の高いところにお願いをしているという状況にあります。再開発ビル全体との連携、よりよい連携を図っていけるような研究、引き続きもっと効果があるような形を常に研究していきたいと思います。","id":"exchange-015"}]},{"id":"topic-03","title":"平成２２年陳情第１５号、品川区総合体育館における職員制服の見直しに関する陳情","agenda":"平成２２年陳情第１５号、品川区総合体育館における職員制服の見直しに関する陳情","exchanges":[{"speaker":"山路委員","kind":"質問","question":"区がつくったんだけれども、専門的にこういうところに委託して、そういう人たちが一体になってやってやるというようなイメージをやはり。そこら辺の微妙な誤解ではないかと思うんですけれども、その辺はどのようにお考えか尋ねました。","respondent":"堀越文化スポーツ振興課長","answer":"その受託業者から支給された作業しやすい服装で当たっていると考えておりますし、実際にこのロゴの大きさを見ても特に問題はないと思っています。","id":"exchange-016"},{"speaker":"山路委員","kind":"質問・要望","question":"こういう陳情が出るということは、そういう思いの１つではないかと思うわけです。こういうところをもう１度、やはりこういうふうに出たことを機会に参考としていただきたいと思うんですけれども、どういうふうにお考えか尋ねました。","respondent":"堀越文化スポーツ振興課長","answer":"今、健康センターの例をお出しされたんですが、体育館に関してはコナミが継続して受けておりますので、事業者が変わってという話はございません。そういった中で対応させていただきたいとは思いますけれども、今回の件に関しては特に問題はないと考えておるものです。","id":"exchange-017"},{"speaker":"山路委員","kind":"意見","question":"コナミさんがやっているときは非常に評価がよかったんです。だけど、現場で言える人も、言えない人もいろいろいらっしゃいますので、その辺をきめ細かくお願いしておきたいということですとの意見を述べました。","respondent":"宮地地域振興事業部長","answer":"ご意見はよく承りましたので、やはり陳情、苦情、区民の声等で出てきた背景というのはやはりあると思うんです。よくサービスの全体をもう１度点検しまして、やはり根っこはどういうところにあるのかというのも十分見させていただきたいと思います。","id":"exchange-018"},{"speaker":"渡辺委員","kind":"質問・要望","question":"それを確認したいのと、この陳情者の方自身のそういう問い合わせが、この陳情書の前に窓口等にあったのかどうかが把握されていたら伺いたい。そういう全体像を見たときに問題かどうかという視点も含めて、確認をさせてほしいと求めました。","respondent":"堀越文化スポーツ振興課長","answer":"この件に関して、窓口等でのトラブルというのはありません。陳情書にありますとおり、団体登録の更新でいらしたとは思いますけれども、その際にロゴの話についてのお申し出はなかったです。","id":"exchange-019"},{"speaker":"菊地副委員長","kind":"質問","question":"だからコナミというロゴが入っているかどうかは別としても、指定管理者として明確にわかるようなものというのが、私は必要だと思うんです。清掃業務のところにしてもそうですし、やはり統一した考え方というのが私は必要だと思うんですけれども、その辺のところはどうなんか尋ねました。","respondent":"堀越文化スポーツ振興課長","answer":"区の立場としては、施設の設置者としての最終的な責任を負うという考え方ですので、区としても全体的に指定管理者の部分については。そういった点で、これからもそういう形で対応するということで、十分ご理解をいただけるのではないかと考えているところです。","id":"exchange-020"},{"speaker":"菊地副委員長","kind":"質問","question":"要は品川区が責任を持ってやっている事業なわけですから、そこをここで明確にしてくださいねというこの陳情の中身なんだと私は思うんです。そこをはっきり出すべきだと。","respondent":"堀越文化スポーツ振興課長","answer":"そういう対応をしてきておりますし、ほかの例えば清掃等についてもそういう形で説明するように、それは徹底しています。そういう形でお示しをさせていただいているという形で、今後、我々といたしましてもそういう形で対応させていただきたいと考えているところです。","id":"exchange-021"},{"speaker":"大西委員","kind":"意見","question":"今月はどういう予定があるのかなとかで見たときに、そこに載せておけば、それで終わるのではないかなと。それに載っているかどうかもあわせて、もし載っていなければやってもらったら少しいいのかなと思いますとの意見を述べました。","respondent":"堀越文化スポーツ振興課長","answer":"今、受付のところに管理をしている主体として、品川区スポーツ協会の名前がわかるものを明示をさせていただいているところです。そういった形で対応していますので、基本的に窓口対応の部分でできるということと、十分対応させていただいていると考えておるところです。","id":"exchange-022"},{"speaker":"川西委員長","kind":"質問","question":"ほかになければ、私のほうから１つ質問をさせてください。そういうことをちょっと大まかに知っておきたいと思います。","respondent":"堀越文化スポーツ振興課長","answer":"品川区スポーツ協会の部分で言えば、いろいろな教室とか講座の実施ですとか、全体の運営については品川区スポーツ協会。やはりサービスの安定性、経済的な合理性という部分を加味しまして、指定管理と同じ年数の５年を基本に委託をしていくという考え方です。","id":"exchange-023"},{"speaker":"高橋委員","kind":"確認","question":"１つだけ確認したいんですけれども、この陳情の中の表の最後から３行目に「窓口業務は区の業務でなくてはなりません」というところについて、もしかしたらここは説明があったかもしれませんが、このことについて、この陳情された方の認識が正しいのかどうか。","respondent":"堀越文化スポーツ振興課長","answer":"これはちょっと説明の仕方はあると思うんですけれども、指定管理をしておりますので、指定管理ですから管理の業務がもう代行という形になります。","id":"exchange-024"},{"speaker":"渡辺委員","kind":"意見","question":"先ほどもう再三説明もありましたし、現物を見させていただいて、そんなに社会通念上おかしくないものであるという見解を持ちました。そういったほんとうに細部にわたる個別案件まで陳情としてどうかという疑問を持ちながら、これは明確に不採択かと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"山路委員","kind":"質問・要望","question":"そういう形で指定管理者、そして民間を活用されているわけですから、当然そこにはロゴマークも必要になってくる。そこだけ注意してほしいと求めましたが、この趣旨に関しましては結局合わないので、不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"菊地副委員長","kind":"質問・要望","question":"指定管理者制度のもとで、やはり品川区スポーツ協会があそこの場合は実際に受けているわけですから、そこは明確にすべきだと思います。私は採択を求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"石田委員","kind":"意見","question":"民主品川としては不採択で行きたいと思います。彼らの意識としては、今回、この陳情に関しては不採択でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"高橋委員","kind":"質問","question":"どういう表現になるか、不採択という話とは切り離して、検討してほしいと求めました。不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"大西委員","kind":"質問","question":"ちょっと先ほど申し上げた質問と重複しますけれども、掲示自体でもうやっているという認識でいいわけですね。おそらく先ほどもございましたように、特段の違和感を覚える方はほとんどおられないということで、この陳情に沿うことはできないと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/397696?Template=document&Id=2596#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":27502,"voices":144}},{"id":"h22-20101213-7","meetingId":"h22-cm12","date":"2010年12月13日","dateIso":"2010-12-13","committee":"厚生委員会","time":"午前１０時０２分～午後２時５５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件整理しています。","topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"区として総合評価をする中で、どういうふうに各現場に返すということをしておられるのか、その辺をちょっと伺いたいと思います。そういうことで理解していただいて、どういうふうにしておられるのか、ちょっと教えてほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"いろいろな面についてヒアリング行いまして、どのように運営をされているか、所管といたしまして把握をしています。それから活動報告というところで、絶えずサービスセンターと連携をとりながら、利用者に質のいいサービスを提供するように努めているところです。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"どういうふうにしているのかということを聞いたつもりなので、ちょっとその辺がわからなかったので、もう一度教えていただきたい。多分、指定管理者になっていくんだろうと思うんですけれども、そうなると、ちょうど５年にならないわけですから、報告が半年ずれるわけですね。","respondent":"冨岡高齢者福祉課長","answer":"そういう中で、ほかのさまざまサービスセンターのあり方等をつぶさに見て、長所をそれぞれのところに生かしているです。先々、どういうふうにしていったらいいかということで、検討の課題とさせていただければと思います。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"さっきのような質問をさせていただいたんですけれども、マイナスも、改善しなくてはいけないところもありますよね。そういうところをどういうふうに扱ってきているのか、見えない部分なので、教えてほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"対応と方針ということで、次の年に向けて改善をしていくという形で、私どもからもご説明申し上げている。当然、それは続けてまいりまして、明らかにしてまいりたいと思っているところです。","id":"exchange-003"},{"speaker":"中塚副委員長","kind":"質問","question":"どうしても指定管理者という制度をとる場合、選定委員の裁量の中で、いろいろ変更することが可能な仕組みでもあるわけですよね。ですので、ここで言っている合理的とは何か、連続性とは何か、どういう考えに基づいていらっしゃるのか、そこの中身をご説明いただけますか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"１番目ですが、指定管理者の変更等に伴う混乱等を避けるために合理的であろうと、私どもは考えております。介護の場合ですと、運営者に連続性、つまり利用者の状況をよく把握をしている運営者に継続してお願いをしていくのがいいだろうと理解しています。","id":"exchange-004"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"区の思い、考え方は、どういうものがあるのかご説明いただきたいと思うんです。そこについて、ご説明いただけますか尋ねました。","respondent":"木下健康福祉事業部長","answer":"これが、ある種誤解があって、機械的に変更するというようなことがあったとしますと、現場の混乱は非常に大きいことが予想されます。そういう点では、５年ごとに議会の審議も含めました見直しの機会を設けるということは、やはりそれは必要だと考えています。","id":"exchange-005"},{"speaker":"沢田委員","kind":"質問・要望","question":"区はどのような直接的な、定期的な施設の点検等をしているのか、そういうことをお伺いしたい。それからもう１点は、私はわからなかったので、お伺いさせてほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"それをまとめて経営会議にかけまして、その結果をこの委員会で報告するという流れで、指定管理者の１年のモニタリングは進めております。あるいは、それに類似した施設について区内の法人が運営をしている場合については、そちらのほうをこれからも指定していくような方針です。","id":"exchange-006"},{"speaker":"沢田委員","kind":"質問","question":"そうすると、今後、新しく新規でやるときは、やっぱり区の中の今ある社会福祉法人が中心になっていくんですか。他区での実績とかも評価して、他区でやっている社会福祉法人を指定するということもあるのか、その辺はどうなんか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"説明不足で申しわけございません。既に区内でも実施をしている、実績を見ながら、区内の法人にお願いをしていきたいと考えています。","id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"品川区としてどのように見ておられるのか、区として、どういうふうに見ていらっしゃるのか。問題意識、こういうところはこういうふうにしたほうがいいのではないかみたいな問題意識がもしあれば、教えてほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"運営の仕方といいますのは、それぞれの、今までの実績を生かしながら工夫をして取り組んでいただきたいと思っているところです。これについても、やはり、今後ということを期待しています。","id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"品川区がどういうふうに見ておられるのか伺いたかったので、あわせて、そこも教えてほしいと求めました。例えば品川総合福祉センターはどういうふうに、そういうところも、知っている範囲で伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、そういうことも含めて、きちんとした選定をしていく。だから、議会側との関係、区民との関係では、どういうふうに見たらいいのか尋ねました。","respondent":"木下健康福祉事業部長","answer":"サービス向上委員会改めモニタリング部会というのを設置してありますが、やはり一定の対応が必要なものについては、各法人にそういう情報を提供し。","id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"どんな配慮していても起きてしまうということはあるので、そこまで求めているものではないと理解していただきたいんです。どうなんでしょうかということも聞いたつもりなんですけれども、ちょっと考え、見解を伺いたいんです。","respondent":"木下健康福祉事業部長","answer":"したがって、これは、その都度議会に報告するという性格ではなく、保険者側として、区として責任を持って対応することですよと。継続するにふさわしいということで、今回、指定管理者の延長ということをお出しをしているです。","id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっと改善を求めるべきところはあるのではないかという問題意識で、これは私の意見ですから、それでとどめておきたいと思います。もし、検討していただけるのであれば、検討していただきたいということもあわせて申し上げて、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"中塚副委員長","kind":"質問","question":"人材確保のことについて、１点、お伺いしたいと思うんです。そこについては、指定管理者の選定の中でどのように評価をされているのか、そこをご説明いただけますか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"これからも引き続き、あらゆる機会を通じて雇用の確保を図っていただきたいということで進めているところです。そういうものも含めまして、正式にご決定をいただければ、本格的に動き始めるということになるかと思います。","id":"exchange-013"},{"speaker":"中塚副委員長","kind":"質問","question":"なぜ聞いたかというと、それぞれ一定努力はされているという話も伺いますけれども、実際はなかなかきゅうきゅうだという話もよく伺うわけです。どう進めているのか、そこを区がどういう評価されているのか、お伺いしたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"施設長級とか、中堅とかという形で、職員の層に応じた配置というものも不足する部分もあるかと思います。配置の動きは始まっていると聞いておりますが、新しい方も含めて確保できるように、連携を取りながら話を進めてまいりたいと考えています。","id":"exchange-014"},{"speaker":"中塚副委員長","kind":"質問","question":"選定として、候補者として挙げられているわけですから、今、人材確保がどう進められているのか、そこを、区がどう評価しているのか。福祉は人ですから、そこをどう区が評価を挙げているのか、改めて伺いたいと思います。","respondent":"木下健康福祉事業部長","answer":"広報等を含めまして、区が協力できるところは協力しながら、必要数を満たせるようにしていきたいと考えているところです。そういうようなこともありますので、開設までには、きちんとした態勢がとれるだろうと見ているところです。","id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"伺おうかなと思ったんですけれども、もう３０年近く、二十数年経つわけですね。ちょっとその辺の状況を教えてほしいと求めました。","respondent":"間部高齢者いきがい課長","answer":"年齢的に見ても、この制度的には６５歳以上の方を対象にしているということで、要介護状況の方が増えているという認識を持っているところです。７件から８件というような状況が見られますので、おおよそ二十二、三件の方については退去しているというような状況です。","id":"exchange-016"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"ちょっと教えていただきたいんですけれども、この三つの高齢者住宅は、高齢者住宅そのものはほかにも幾つかありますよね。指定管理者制度等、ほかの部分はどうなっているのか、単純に期間の問題なのか、ちょっとその前後がわからなかったので、ご説明いただけますか。","respondent":"間部高齢者いきがい課長","answer":"入居されている方に何かお困り事があった場合に、併設の在宅介護支援センターや在宅サービスセンターに相談に行きやすいということがあります。","id":"exchange-017"}]},{"id":"topic-02","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"南委員","kind":"確認","question":"要介護１程度の方でも対象にしているというふうに聞いたんですが、対象者をどういうところに規定をしているのか、一つ確認したいと思います。私は伺ったんですけれども、それでよかったのかどうかを、ちょっと確認したいと思います。","respondent":"冨岡高齢者福祉課長、上山健康福祉事業部副参事","answer":"対象者につきまして、私の申し上げたところですが、あとにつきましては、社会福祉協議会のほうで対応します。要介護１、２でありましても、お配りをしているというのが対象者です。種類といたしましては、月に１種類と限らせていただいておりますので、品を月によって変えまして、工夫をされてお使いになられております。","id":"exchange-018"},{"speaker":"南委員","kind":"提案","question":"その辺の認識というのは、品川区なり、社会福祉協議会なりが、どういうふうに見ていらっしゃるのか、その辺の見解を伺いたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"在宅介護を支援するというところで制度化されているものでございまして、それについては、今のところ考えていないです。あくまでも在宅介護を支援する、それも現物で給付をしていくというのが原則です。","id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"どういうふうに見ていらっしゃるのかということを聞いたので、在宅も含めて、見解を教えてほしいと求めました。在宅介護でも入院する場合はあるわけですから、なぜ、その辺についても伺いたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"それが、例えば入院とか何とかということであれば、これはまるで別の考え方に立ちまして、新たに考えていかなければいけないです。品川区が支援をしている紙おむつの支給の援助は、その点については、ご理解をいただきたいと考えています。","id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"３,０００円の金額について、どうなのかというのは、もう１回教えてほしいと求めました。それこそ、合理的な理由にはなっていかないと思いますので、改めて、その辺についても伺いたいと思います。","respondent":"上山健康福祉事業部副参事","answer":"私のほうで説明不足の点があったかと思いますが、予算的には２５０万円ほどでございまして、延べで１５０名ほどでございました。区の職員等を交えました紙おむつに対する検討委員会を設けまして、５から、在宅での支援をさらに広げていくというような形での工夫は。","id":"exchange-021"},{"speaker":"南委員","kind":"質問・要望","question":"対象者が１００倍、予算額は何倍でしょうか、人数に比べると、全然少ないですよね。区民が今求めていらっしゃる、枚数を増やしてほしい、強く求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"山元委員","kind":"質問・要望","question":"どうなんでしょうか、実際にあるかどうか、教えていただきたい。ちょっと、その辺も教えてほしいと求めました。","respondent":"上山健康福祉事業部副参事","answer":"そのうち５人が急に入院することになって、その５人につきましては、支給の対象にしております。社会福祉協議会で紙おむつ事業をしているというところでは、特別区の中では、品川区を含めて２区と伺っております。","id":"exchange-023"},{"speaker":"山元委員","kind":"質問","question":"そうしますと、裏を返せば、品川区ともう一つの二つの区以外は、区で助成をしているということと受けとめてよろしいですかね。","respondent":"上山健康福祉事業部副参事","answer":"よろしいかと思います。","id":"exchange-024"},{"speaker":"山元委員","kind":"質問・要望","question":"わかりました。少しお時間をいただいて、もう１回質問をさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"幾つかお伺いしたいと思うんですけれども、先ほどのご説明の中でも、２３区で２１区が何らかの形で行っているわけですよね。３点ないし４点、なぜできない理由なのか、ご説明ほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"繰り返しになりますけれども、この制度につきましては、在宅での介護を支援するための紙おむつの現物給付の制度ですので、それ以外についての考えは、現在では持っていないです。","id":"exchange-026"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"２３区で２１区が実施をしていることを、どう見ているのか、ご答弁がなかったので、お答えほしいと求めました。在宅で紙おむつを使っている方が、入院したときに、紙おむつを使うということがわからないのか尋ねました。","respondent":"木下健康福祉事業部長","answer":"つまり、１号保険料で対応するという考え方です。このことを区民の方にわかりやすく伝えるときの説明として、一言で言えるのが、この紙おむつと敬老杖なんです。","id":"exchange-027"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"改めて伺いたいのは、いないのか、ご説明ほしいと求めました。この現状をどう思うのか、あわせてご説明ほしいと求めました。","respondent":"木下健康福祉事業部長、上山健康福祉事業部副参事","answer":"そうなってまいりますと、私は思っていまして、大変危機感を持つわけであります。そういう点では、社会福祉協議会がこれまで大事にしてきた紙おむつ支給事業を、今後とも社会福祉協議会事業で堅持すべきだと考えているところです。考え方ですけれども、紙おむつについては個人差があるということで、すべての多い方の充足までは難しいかとは考えております。","id":"exchange-028"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"最終的に、区が思っているのか、いないのか、そこをご説明ほしいと求めました。区民の実態の把握について、どう進めていくのか、ご説明ほしいと求めました。","respondent":"木下健康福祉事業部長","answer":"そのときにご説明させていただきましたけれども、介護保険等の公的支援が入っているわけでありますから、それに加えて。夜間対応型に衣がえましたけれども、どうしてなくなったかというと、おむつが１晩もつようになったわけであります。","id":"exchange-029"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"公的医療制度の枠の中で考えるべきだというお話だと思いますけれども、区民の医療費負担や紙おむつなどの負担軽減をしっかりとやるべきだと思います。改めて、２３区でやっていないのは品川区を含めて２区だけと、こういう事態を一日も早く改善してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"南委員","kind":"質問","question":"ちょっとお店に行って伺ったんですけれども、今、いっぱいできてきています。どう人間らしく暮らすことを保障できるかと、そのことを追求しないで、高齢者の介護は考えていくべきではないと思うんです。","respondent":"木下健康福祉事業部長","answer":"夜間対応型訪問介護というのは、そういうことを応援する介護保険サービスであります。そうしますと、おむつというのは、そういうことも現実的には難しいというような方について、ご本人も起きなくて済む、家族も起きなくて済む。","id":"exchange-031"},{"speaker":"大沢委員","kind":"質問・要望","question":"それと同時に、まだ区では、こういう事業が制度としてないということを伺いました。ゆえに、制度として確立されていないものを、区に対して求めるのは、それは無理があるのではないかと考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"三上委員","kind":"質問","question":"ほかの２１区がやっているから、品川区もそういう形でやるべきだと変えていくことにはならないと、私は思います。これはやはり財源の問題ですから、これは努力していくべきだと思いますし、増やすということはできるだろうと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"２３区最低の金額にとどまるのではなくて、必要な状況に応じて、ほんとうにもう少し引き上げるという方向で考えていくべきではないかと思います。枚数を増やしてほしいということについても、そういう方向で改めて考えていただければということも、ちょっとお願いしていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"稲川委員","kind":"質問・要望","question":"こういったお見舞いの精神というのですか、１万５,０００人にだんだん拡大してきた、これからも大切にしていっていただきたい。それからもう１点言うのであれば、ほかがやっているから品川区も現金給付するべきだという話は相関性がないと思いますので、不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"三上委員","kind":"質問","question":"私は、山元議員の質問の中で、当初、図書館の中で代読、代筆サービスの提供ということで質問されました。再質問のときに、そこの点について、もう少し詳しくお尋ねさせていただければと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/360687?Template=document&Id=3284#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":48008,"voices":121}},{"id":"h22-20101213-8","meetingId":"h22-cm12","date":"2010年12月13日","dateIso":"2010-12-13","committee":"建設委員会","time":"午前１０時０２分～午後０時２８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件整理しています。","topics":[{"id":"topic-01","title":"第１１３号議案、専決処分の承認を求めること","agenda":"第１１３号議案、専決処分の承認を求めること","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"指定管理の話がありましたが、管理会社はどこだったのかお伺いします。区民住宅にお住まいの方が例えば家賃を滞納した場合に、滞納時の退去に至るルールというのはどうなっているのかということもあわせてお伺いします。","respondent":"柏原住宅担当課長","answer":"それから、指定管理ということで、管理をお願いしておりますのは、品川宅建管理センターです。家賃を滞納された場合の対応ですけれども、中の基準ですが、明け渡しも含めまして法的な措置をとらせていただくというところです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"天井が抜けてしまった原因というんですか、住宅にそもそも欠陥があったのかどうか、そういうのはあるのかどうか。今回の天井が落ちた責任の所在は、区としてはどこにあると考えているのかをお伺いします。","respondent":"柏原住宅担当課長","answer":"ただし、今回の場合につきましては、区が建物を管理しているという立場もありますし、初期対応に若干おくれがあったというところもあります。それでおけがをされたというところもありますので、その部分につきましては対応させていただいているです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"しかし、こじれたというところがやっぱり、どうしても裁判にするしかなかったのかというのがちょっと気になる点ではあるんですね。区が管理を委託しているわけですから、対応というんですか、改めてお伺いします。","respondent":"柏原住宅担当課長","answer":"丁寧な対応ということでさせていただいていたところではありますけれども、弁護士とも相談しまして、ちょっとそういったところでこじれてしまったと。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"その人のいろいろどういう人なのかというのもあると思うんですけれども、それをこじらせてしまわないようなしっかりとしたフォローというんですか、きちんと管理をこれからしていってほしいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"藤原委員","kind":"確認","question":"相手の方の言いたいこととかがわからないので、一方的な報告なので確認をとっておきたいんですけれども、この事故が起きた原因というのは。区民住宅だからという形で区が管理しているということですから、どういう形で、どういう賠償をしていくのが通常なんか尋ねました。","respondent":"柏原住宅担当課長","answer":"その原因者でありますので、上階の方が下の方に損害を与えたということであれば、上階の方が下の方に対してその損害賠償をする。保険に入っていたりとかという方もいらっしゃれば、保険で対応しているということは出てくるかと思いますが、通常であれば上階の方がするです。","id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"だと思うんですけれども、今回この件に関しては、その上階の方がどういう対応をして、そして区としては、その上階の方にどういうアプローチをして、どういう形で具体的になったのか説明を求めました。","respondent":"柏原住宅担当課長","answer":"上階の方への対応ですが、原因が水漏れだというところが判明したところで、まず下の方への謝罪をお願いしますということをお話し申し上げております。上階の方が原因で下階の方が損害を受けますので、その損害に対する対応というのは上階の方に責任がありますので、そのように。","id":"exchange-006"},{"speaker":"藤原委員","kind":"質問","question":"それも明確にわかっているわけですから、あんまりあれすると、どんどん要求が増えていったんでしょう。だから、その辺についての考え方はどうか尋ねました。","respondent":"柏原住宅担当課長、岩田都市環境事業部長","answer":"建物の管理が、ちょっとほかの建物と違う事情がございまして、若干そこの連絡体制がうまくいかなかった点もありました。そういったところも含めて謝罪をさせていただいて区が入ったです。初期対応に非常にまずいところがあったので、代替として、ファミーユ下神明という新品のビルに移っていただくというご提案もしています。","id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"これに対しての区の考え方というか、これ、怒り立ててもしようがないということなんでしょうか。それとも、厳重に注意されたのか、その辺をちょっと聞きたいんです。","respondent":"柏原住宅担当課長","answer":"こちらのほうからも、先ほどもちょっと申しましたが、そういったところで品川宅建管理センターのほうもとまどっていた部分があったのは事実です。","id":"exchange-008"},{"speaker":"松澤委員","kind":"質問","question":"そもそも品川宅建管理センターが指定管理者を受けているということに関しては問題がないということでしょうか。私なんか、このようなことが防げたかもしれないなというふうに思うんですけれども、この考えについてコメントがありますか。","respondent":"岩田都市環境事業部長","answer":"それで１カ月放置すると、こういう水漏れ事故が出てきますので、最初は湿気だけが落ちてくるんです。通報があったら２４時間いつでも対応するというのが、現在はそういうふうに対応できるように体制は立て直っております。","id":"exchange-009"},{"speaker":"松澤委員","kind":"質問","question":"ファミーユ大井ということで名がつくんですから鉄筋コンクリートの建物なんでしょうけれども、２階、天井の間には必ずすき間があるんですよね。それが下へ漏れてくるということですから、水漏れ１つ大変だということを、ちょっと考えられないですね。","respondent":"片田防災まちづくり事業部長","answer":"三日の話ですから、一時的に多くの水が下にたまってしまって、その重みで逆にクラスターボードとかそういうものが落下したのかなと考えています。","id":"exchange-010"},{"speaker":"藤原委員","kind":"質問・要望","question":"それはそう思うじゃないですか。役所に通報して、していますからと言って、ほらみたことか、落っこちちゃったとなるじゃないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"阿部副委員長","kind":"提案","question":"結局、損害賠償とか謝罪とかはされて、もうそっちのほうは済んでいるという理解でよろしいんでしょうか。それも含めて、区もいろいろご提案をされていると思うんですけれども、これは見舞金みたいなものはご提案されるものなんか尋ねました。","respondent":"柏原住宅担当課長","answer":"天井の修繕、まだ済んでいないという状況がございまして、具体的に上の方から損害賠償というところではまだ手続が進んでおりません。それから、そこまで至らずにどんどん話が過大化していったというところがございまして、直接的に何かお支払いしたというところはございません。","id":"exchange-012"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"もう１つあるということで、今回のを受けて、その辺を確認させていただきたい。１２時間以内とか言ってかかっているぐらいですから、業者としては、ある意味済む話なのかどうかということを改めてお考えを伺いたいと思います。","respondent":"柏原住宅担当課長","answer":"それからあと、品川宅建管理センターのことについてですが、責任は重いと考えています。保険の部分につきましては、これを受けたからというわけではないんですが、入っていただくように入居時にご案内をさせていただいているところです。","id":"exchange-013"},{"speaker":"若林委員","kind":"質問","question":"品川宅建管理センターがいて、都市整備公社がいてということで、この水漏れの事象的にはどこに原因があったんでしょうか。２つ。","respondent":"柏原住宅担当課長","answer":"初動対応につきましては、連絡体制といいますか、どこがまず最初に責任を持って動き出すんだというところだと思うんです。どっちなんだ、どっちなんだ、そういう状況があったものですから対応がおくれた。","id":"exchange-014"},{"speaker":"若林委員","kind":"質問","question":"新しいのが出てきたんですが、メンテナンスがこの二、三日の間に現場に行っていたというふうに理解していいんか尋ねました。","respondent":"柏原住宅担当課長","answer":"見に行って、これはちょっと詳しくあけないといけないだろうと。こっちじゃないとやっている間に二、三日の工事の設定があって、その間に落ちてしまったです。","id":"exchange-015"},{"speaker":"若林委員","kind":"質問","question":"入りますよということで当然部屋に入っていっているわけですから、そこのどこでどうなったのか、ちょっともう１回そこをご説明いただいて。こういうことは指定管理の問題ですので、これは全庁的に何か情報発信するという、そういうシステムはあるんか尋ねました。","respondent":"岩田都市環境事業部長","answer":"その日１日水をとめてもらうという、こういった対応がきちっとなされていなかったので、何をやっていたんだということで厳しく指導したわけです。即刻即日対応で即やるというようなことは、今はそごのないようにした、こういうことです。","id":"exchange-016"},{"speaker":"若林委員","kind":"確認","question":"メンテナンス関係のそごはなかったということの確認でよろしいですね。ほかの業者だってこういうことをやってしまったとなれば、区民住宅を全部調べるんか尋ねました。","respondent":"岩田都市環境事業部長","answer":"洗濯機をお買いになって、上の階は高齢のおばあちゃんですので、お買いになって設置したときにいじられたのではないだろうかと。だから、そこは推測の域を脱しませんけれども、何らかの原因でわざとトラップを外してしまったということなんです。","id":"exchange-017"},{"speaker":"若林委員","kind":"質問・要望","question":"指定管理的にも厳重注意等の対応をされたと、今後の対応もこれで管理のあり方を含めてしっかり対応してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"今後このような事態にならないために、管理体制の見直しを含めて改善努力することを強く求めまして、今回は承認したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-02","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"この請願者の皆さんの要求を区はどう考えているのかお伺いしたいのと、前回もコミュニティバスの運行を求める請願が審議をされましたけれども、把握しているところは一体どこなのか伺いたいと思います。","respondent":"松代都市計画課長","answer":"先般もお答えしましたように、そういったところがいろいろとこちらのほうで考えた中では、そういった形には至らない。しかしながら、２回乗りかえれば、おおむね３０分、４０分ぐらいのところで区内の施設等には行けるのではないかというように思っておるところです。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこなら高齢者の方でも耐えられるんだという説明がちょっとわからないのでそれを教えていただきたいんですけれども、やっぱり７００ｍだと。何で７００ｍにするのかというのをわかるように説明していただきたいのと、もう少し具体的にどこら辺の地域なのか、具体的に説明を求めました。","respondent":"松代都市計画課長","answer":"私どもはこれまでもおおむね１５分というもの、また、７００ｍというものでこの交通網の割り方を考えてきたところです。今、先ほど言いました荏原の一部、それと上大崎の一部がこのような地区に当たるのではないかなというふうに思っているところです。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、５００ｍ圏内でこういったシミュレーションをしていただきたいと思うんですけれども、いかがでしょうかということが１つと。運行に補助金というんですか、運営費の補助を出している区は何区あるのかというのを、わかっていたら教えていただきたいというのが２点目です。","respondent":"松代都市計画課長","answer":"ここで今、１９区が実施してございまして、その中で聞き取りだとかいろいろな話を聞きますと、補助金をほとんど導入した形でやってあります。やっぱり９億円、８億円ということで、非常に大きな財政負担になってくというようなことです。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"しかもさまざまな会派から要望も出されておりますけれども、区民も議会も望んでいる施策ならば、いかがでしょうか。２点目の質問ですけれども、こうした福祉タクシーなど、ちゃんと十分なサービス提供できていると思っているのかどうかもお伺いします。","respondent":"片田防災まちづくり事業部長","answer":"１つの出発点を決めたとしても、なかなかぐるっと回って逆に狭い道を通るというようなところも含めて難しいところもあります。武蔵小山のほうとの絡みの中では、そういう中での民間バス事業者によるそういう対応については、区としても今後の対応としては当然考えていきたい。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"補完になっているのかどうかというのは、ちょっとご答弁がなかったのでお伺いしたいなと思いますのと、均衡がとれていないところもあるわけですから。ですから、こうしたところも含めて考えていくべきなんだと思うんですけれども、いかがか尋ねました。","respondent":"岩田都市環境事業部長","answer":"１つの路線の中で固定したものを回すと、目黒区の検討書を見てもらえばわかりますけれども、これが一番難しいところなんです。これが補助２６号線が通りますと、東急側は前向きに検討しているということを聞いておりますので、品川区としては検討はしておりませんけれども。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"ですから、区民の皆さんが望んでこういうところへ通してほしいと言ったところであれば、採算だってとれるようになるかもしれないじゃないですか。そういう試みを私はやるべきだと思うんですけれども、いかがか尋ねました。","respondent":"松代都市計画課長","answer":"そういう中で鉄道網とか道路網を含めて、将来、本当に３０年、５０年先の品川区のあり方というものを検討してまいります。目黒区のほうで見合わせた理由の１つの大きなところは、実際いろいろルートを検討してみたんだけれども、満足できるところが非常に少ない。","id":"exchange-025"},{"speaker":"松澤委員","kind":"質問","question":"２６号線は、これは東西に必要な道路ですから、今の答弁でも将来的にはという明るい話がありました。交通渋滞ということを考えたら、とてもじゃないけれども不可能だと思うんですが、交通の面についての問題についてどう考えるか尋ねました。","respondent":"松代都市計画課長","answer":"通行者、また商店街等については、当然時間的な制約等もありますので非常に難しいという点があります。ましてやこの地区でそれを満足させるような道路網と交通形態とルートというのは、非常に難しいというように考えてあります。","id":"exchange-026"},{"speaker":"阿部副委員長","kind":"質問","question":"ごめんなさい、最初に言いました何らか、今までの研究をちょっと見えるようにしていただくことはできますでしょうか。それだけ説明を求めました。","respondent":"松代都市計画課長","answer":"やはり本格的な委託で数千万かけてやるような話が我々の今までのやり方でございまして、それはきちんとしたデータのもとに説明ができる話です。その数字が本当に大丈夫か、それが根拠があるのかと言われますと、その次の次の説明が非常に難しくなろうと思います。","id":"exchange-027"},{"speaker":"市川委員","kind":"意見","question":"５００ｍ圏内だとどのようになるのかというところについて聞きたいなとも思いますし、もう少し品川区の実態というものを見る必要があるのではないかなと思いますので、私は継続ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"松澤委員","kind":"質問","question":"現在、私どもの１人が同じような質問をしたということもありまして、いろいろ党内でも議論は相当しました。これ、出されている方は本当に車の交通を考えた場合どうなるのか、そういうことまで考えて出されているのだろうかという逆に疑問を感じました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"若林委員","kind":"質問・要望","question":"私もその１対１等の対話の中では、これは必ず実現できるといいですねということで、そういうお話し合いをすることが常にあります。そこはしっかりと議員として私は判断をさせていただきたいということで、個人的な、いろいろな意味での不採択ということでお話をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"渡部委員","kind":"質問・要望","question":"コミュニティバス、要望として結構出てくるものでございまして、全否定はしないでほしいといった話もしました。結論から申しますと、今回のこのコミュニティバスの運行を求める請願に対しては、不採択とさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"安藤委員","kind":"意見","question":"委員の皆さんに呼びかけたいのは、まずこの請願を採択していただいて、それで検討に入ろうじゃないか。私は、私自身も採択を主張いたしますし、委員の皆さんにも採択を呼びかけたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問・要望","question":"これは要望で言っておきますが、部長の先ほどの答弁の中に、武蔵小山の補助２６号線が前向きだというお話がありました。ぜひこれ、実現してほしいと求めましたので、これはもう実現に向けて全力でやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"市川委員","kind":"意見","question":"それで、ここの請願の趣旨にも書いてあるところは、じゃあ、どうなのかといいましたら、１に走らせるエリアではないんじゃないかなと感じます。福祉の分野でも少しそういう議論を深める必要があるのではないかなと思いますので、この請願については不採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"阿部副委員長","kind":"意見","question":"やはり利便性という意味では、バス１つに頼ると、ハードだけじゃなくてソフトも含めてつくっていく必要があるだろうなと考えています。したがって、民主品川としては、この段階ではこの請願には不採択という考え方ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"}]},{"id":"topic-03","title":"今定例会の一般質問にかかわる所管質問ですが、今定例会の一般質問中、建設委員会にかかわる項目","agenda":"今定例会の一般質問にかかわる所管質問ですが、今定例会の一般質問中、建設委員会にかかわる項目","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"西品川の公園の下にも６００本ですか、これも当然満杯になったのだろうと思いますけれども、その状況。「あと１０分降ったら、結構上のほうの人も話を聞いたものですから、その辺どうだったのかというのをまず聞きたいと思います。","respondent":"藤橋都市整備下水道課長","answer":"１時間５０mmに対応した雨の対応というのは、三時間継続する雨、こういった行為に対応した施設になっております。取水事故の対応後、工事を進めておりまして、今のところ予定どおり平成２３年３月末に下水道施設が完了する予定です。","id":"exchange-036"},{"speaker":"松澤委員","kind":"確認","question":"１時間換算にして１５０mmの中で、あれは下水道幹線ですから、下水道はいっぱいになったんでしょうね。その辺のところをもう１回確認しておきます。","respondent":"藤橋都市整備下水道課長","answer":"お話のとおり、下水道幹線の水位データを東京都のほうに照会しましたところ、７時５０分より少し前の段階から水位が急激に上昇いたしまして、戸越幹線も満干の状態が続いておりましたのを確認しております。","id":"exchange-037"},{"speaker":"松澤委員","kind":"質問・要望","question":"こんなことは何年に一度の雨、貯留管工事ができたにもかかわらず水が噴き出して使えなかったということの１点、区民のほうはそこへ行くと思うんです。しっかりと工事そのものを来年の梅雨期までには必ず完成させていただきたいということと、する予定なのか、その辺だけ聞いておきます。","respondent":"藤橋都市整備下水道課長","answer":"貯留管の工事につきましては、今めいっぱい工事を進めておりまして、３月末に終わって、４月以降、貯留を開始する予定で進めているところです。","id":"exchange-038"},{"speaker":"松澤委員","kind":"質問・要望","question":"それで結構なんですけれども、戸越の下水道幹線は、新幹線を超えてからなぜか二股に分かれているんですよね。新幹線のところであふれるんじゃないかということが前から強いですから、その辺も含めてしっかりと地域の人に説明してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"安藤委員","kind":"質問","question":"先ほど、５０mm対応だとなかなか現実に合わないという面も出てきているのかなというふうに思うので、必要なのかというのもあわせてお伺いします。違う方向に下水管を切り替えたということだと思うんですけれども、そういった形で何かこれから改善の余地はないのかというのをお伺いします。","respondent":"藤橋都市整備下水道課長","answer":"１時間５０mmの降雨に対応した施設ということで、その施設に時間がかかるというだけではなくて、浸水被害を誘発するおそれがあります。その調査結果を踏まえて対応を検討するということになっています。","id":"exchange-040"},{"speaker":"安藤委員","kind":"質問・要望","question":"そよかぜ公園のところですか、当然警報ですからびっくりするためにあるわけですけれども、こちら側から連絡しないと出ないものだと思うんです。それ以外は区の人が当日調査をして、ここが浸水したと確認したところは出ると思うんですけれども、そこら辺はどうか尋ねました。","respondent":"中山防災課長","answer":"事業所の場合はすべて１万円、床下の場合、一般世帯でも１万円です。浸水箇所以外も、その近辺ずらっと見て回っておりますので、浸水被害の確認はすべてしています。","id":"exchange-041"},{"speaker":"阿部副委員長","kind":"質問","question":"それで、１点だけ教えてください。雨が降ってすぐに青空が出てきて、２時に第１回水防本部会議、このタイミングというのはどういうことなのかだけ教えてほしいと求めました。","respondent":"中山防災課長","answer":"７時４５分に水防本部を設置したんですけれども、４５分に設置してから、要するに、災害活動にすぐ携わらなければならないという状況がございましたので、このような時間になってしまいました。","id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/483234?Template=document&Id=3996#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":44818,"voices":106}},{"id":"h22-20101213-9","meetingId":"h22-cm12","date":"2010年12月13日","dateIso":"2010-12-13","committee":"文教委員会","time":"午前１０時０２分～午後３時１１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を101件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"台場もそうですけど、並列型、０歳から５歳までの保育園に４・５歳の幼稚園をくっつけるという形になってきている。ここのところはなぜあえてこの一時のところと組み合わせて幼保一体なのかということをお聞きしたいのと、あと基本的には、その辺をまずお聞きします。","respondent":"吉岡保育課長","answer":"その中で、保育園機能と幼稚園機能をあわせ持つものを考えてございましたので、その中でそのような計画を立てたものです。０歳から３歳までの保育園、それから４歳・５歳が幼稚園という流れの中で実施してまいりましたが、新たな並列型というものを設置したわけで。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そうすると、開発の工事がどういう流れで行われるのかというのと、それに伴って御殿山小学校の工事もありますよね。その流れを教えていただきたいのと、いつからいつまでのものなのかというのをまず教えていただきたいのと、流れを。","respondent":"吉岡保育課長","answer":"開発につきましては、今飯沼委員からお話がありましたように、その中で一定幼稚園の施設としては影響を避ける必要があろうかと考えているところです。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"保育園のところについて、開発のところは、何かなかなか計画が進まないといったところで、いつになるのかちょっと３年ですか。戻る時期が３年というのは、ちょっとその辺も含めて流れを具体的に教えていただきたいのと、もうちょっと今の段階でわかる範囲で教えていただきたい。","respondent":"吉岡保育課長、田村庶務課長","answer":"３年１カ月なのか、２年１０カ月なのか、ちょっとその辺は詳細に私どもは申し上げる立場にございません。戻ったときの形ですけれども、形としては御殿山幼稚園を核に… 当初の予定から毎年いろんな状況があるんでしょうけど、平成２２年度着工、平成２５年度竣工という形を聞いております。御殿山小学校の改築の予定ですが、実施設計という形ですが、平成２４年度が実施設計。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"幼稚園のここの最初の目的のところですか、開発が平成２２年度から平成２５年度となっていますけど、明らかに遅れていますよね。いつ帰るのかとか、それから小学校の計画と幼稚園の絡みがどうなのかというのがちょっと見えないのでお願いいたします。","respondent":"吉岡保育課長","answer":"いつ帰るのかというお訪ねに対しては、今庶務課長がお答えしたとおりでございまして、平成２２年度から平成２５年度という計画が少し遅れているですが、再開発でできます施設の中に戻りますので、再開発の工事がいつ完了するのか、それによって決まってくるです。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"学校との絡みは。小学校の工事と、この幼稚園の園舎の関係を説明を求めました。","respondent":"田村庶務課長","answer":"もともと学校の校地ですから、そこの部分を含めて影響の出ない範囲での改築ということで考えております。ですから、再開発が遅れ気味であってもそれに影響されるものではないというように考えております。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問","question":"そうすると、開発が遅れていて、まだ悪影響がいつになるのか明らかにならないけれども、先に移転をしていくということなんでしょうか。ちょっとその辺説明を求めました。","respondent":"吉岡保育課長","answer":"いつ工事が始まって、そういう影響が出てくるのかという問題です。早晩影響が出てくるということであれば、使用できるようになる平成２３年４月から幼稚園については、品川学園の隣地で運営をするです。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"どうもちょっと納得がいかないので、ちょっと開発絡みの質問をしますけれども、北品川五丁目地域のところに７棟ぐらい新たな高層ビルができる。ちょっとこの辺の開発絡みの、小学校への影響とか幼稚園の影響に対してどう考えていらっしゃるのか、ちょっとこっちのほうをお聞きしたいと思います。","respondent":"田村庶務課長、吉岡保育課長","answer":"委員ご指摘のように南側にビルが建つというのももちろん承知しています。御殿山小学校は校庭などが若干変形していますので、公募型のプロポーザルで業者の提案を待っているという状況です。幼稚園への影響ですけれども、これはご説明したとおりでございまして、まずは現在地から品川学園の隣地へ移転をするということです。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"本当だったら今日図面が欲しいぐらいで、ちょっと何かすごく複雑な地域なので、真南に一番影響があるところからちょっと移動しますよね。その移動した当初の跡とかがどうなるのかもちょっと含めて教えていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"意見","question":"課長は小学校の形態が変わるとおっしゃいましたよね。建物の形態が変わりますよねとの意見を述べました。","respondent":"田村庶務課長","answer":"いや、言っておりません。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"意見","question":"建物の場所が変わりますよね。〔「設計はこれからするんだ」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今の状況からすると、４時間は日影をおとすということで、それをどう受けとめていらっしゃるのか。まだこれからですよというんだったら、極力問題の少ない方向でやっていただきたいので、そこを一つお話ししていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"提案","question":"お任せしっ放しで公募するんですか。だから、そこの区の考えを聞かせていただきたいのが１点と、あと幼稚園が、戻る場所がどこになるのかというのをぜひ聞かせてくださいとの意見を述べました。","respondent":"田村庶務課長、吉岡保育課長","answer":"がけや擁壁が御殿山幼稚園、小学校にありますので、がけや擁壁の改修工事をどのように費用対効果も含めて行うのか。そういう条件で公募型プロポーザルをかけている段階なので、まだ出てきていませんから… 幼稚園が戻る場所ですが、これは昨年度の委員会でご報告させていただいたところですけれども、北品川五丁目第一地区の再開発によって建設されます建物の中に入るです。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"確認","question":"私はその大もとのところをお伺いしたので、もう一回そこをお話ししてほしいのと、１４３ｍの一番大きなところに入るんですよね。その辺をちょっと確認したい。","respondent":"田村庶務課長、吉岡保育課長","answer":"先ほど三つの提案をお話ししたんですが、今の御殿山小学校よりもより良い教育環境が図れるような内容にしていきたいというように考えております。 建物の計画の中でＤ棟ということで計画された建物を予定していますが、もう少し詳しくどのように入ってということはご説明をする機会があろうかと思いますので、現在の時点ではあくまでも仮定の話であるです。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"今より良い環境でとおっしゃいましたけれども、今より良い環境なんでしょうか、悪くなるんでしょうか。","respondent":"古川子ども未来事業部長","answer":"私が言うのもなんですけども、委員会の中で、この北品川五丁目に関します小学校の関係、幼稚園の関係、５年前から報告しております。平成２５年度完成であれば、平成２６年度の当初にまた戻れる状況ができますけれども、このように考えております。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"おっしゃってほしいと求めましたが、区民の代表ですから、丁寧にお答えをしていただきたいなと思います。大きいところの開発の問題がこの幼稚園に対して影響しているなということで、態度のときに後でまた意見を言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"やっぱりその方法が違ったりとかすることによって、そこの現場の子どもたちに対する保育士、幼稚園教諭のやり方も変わってくると思うんですね。そこのつながりをどういうふうに考えていけばいいんか尋ねました。","respondent":"吉岡保育課長","answer":"あるいは現在検討されているこども園になるのか、その辺のところはまだこれから先の話ですので、十分制度の動向等も見極めながら検討していくです。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"年齢区分型の、もしかしたら０・１・２歳の認可保育園ができる可能性もあるというふうに受けとめていいのかなと思うんですけれどもいかがですか。それはどうなのか尋ねました。","respondent":"吉岡保育課長","answer":"戻った先で、０・１・２歳の保育園ができるのかということにつきましては、今の考えでは保育的な要素も持った施設ということで考えてあります。定数は現在３０人と考えていますけれども、保育園からが１５人、できるだけ受け入れができるように進めてまいりたいと考えています。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"幼稚園を希望されている保護者の方にすれば、本当だと３０人の枠があるのに、１５人、最大２０人というと１０人減るわけですよね。ということは、ちょっと何か手を打たないといけないというふうに思っているのか、現実的な数の把握はどのようにされているのか尋ねました。","respondent":"吉岡保育課長","answer":"４年後にどうなっていくのかというのは、御殿山幼稚園は募集を３０人したところ、４１人の応募をいただいております。募集を３３名かけたところ、２４名の応募ということで、この中で運営していけるものかなというように考えております。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"やっぱり台場は台場のいいところを知らせるとかということもしなきゃいけないでしょう。そういうことだとちょっと多分この３０人という枠だと保護者の方たちというのは、その考え方を最後にお聞きしたいと思います。","respondent":"吉岡保育課長","answer":"その中で小学校との連携も十分に図りながら、質の高い幼児教育を行っているものと理解していますので、その辺は区民の皆様にアピールをしていきたいというように思ってあります。","id":"exchange-019"},{"speaker":"井上委員","kind":"質問・要望","question":"どういうふうな財源の構成になるのか、設置に当たって、ちょっとお金の流れを教えていただきたい。","respondent":"吉岡保育課長","answer":"公立の認可保育園については、建設についても運営についても一般財源化されておりますので、国や都からの補助がないというように考えてあります。","id":"exchange-020"},{"speaker":"井上委員","kind":"質問","question":"すこやか園にしているということについては、何も財源のところでは変更がないということでいいのか尋ねました。","respondent":"吉岡保育課長","answer":"委員がおっしゃるとおりです。","id":"exchange-021"},{"speaker":"井上委員","kind":"意見","question":"今回も今年の場合には６２人の幼稚園の申し込みということですので、影響はないだろうというふうに思うんですけど、来年４月ですね。そこのところでどういうふうな、そこをどういうふうに説明をし、どういう対応を考えていらっしゃいますかとの意見を述べました。","respondent":"吉岡保育課長","answer":"その中で、全体としては幼稚園に入園を希望される方の利用については、おおむね充足をしているというように考えております。御殿山幼稚園１園だけの考えではなく、トータルの中で幼稚園に入園される方のご希望についてはお受けできるものというように考えております。","id":"exchange-022"},{"speaker":"井上委員","kind":"質問","question":"同じような環境を維持するべきだというふうに思っていますけれども、そこのところを品川区として再開発が優先されるべきではないと思っているんですが、そこら辺は幼稚園ではどのようにお考えなんか尋ねました。","respondent":"吉岡保育課長","answer":"安全で住みやすいまちづくりを行うという目的で行ってありますので、それはそれで一定の行政目的を持って実施しています。幼稚園ですので必ず設置いたしますし、新しい環境の中で十分な環境を確保してまいりますので、ご安心いただきたいと思います。","id":"exchange-023"},{"speaker":"金野委員","kind":"意見","question":"これは今この形態あるいはどういった規模というところまでは、こういう規模でいきたいというところを持っていらっしゃるんだろうと思うんですね。そのときに動向を見て、どれぐらいこちらの希望がかなうのかというところだと思うんですが、どういったことをお考えなのかとの意見を述べました。","respondent":"吉岡保育課長","answer":"これはまだ今後の検討になりますが、幼稚園の幼児教育機能と、それから０歳からの保育園の保育機能ということで考えてあります。新たな保育の需要、幼児教育の需要にこたえられるようにしていきたいというように考えているところです。","id":"exchange-024"},{"speaker":"金野委員","kind":"質問・要望","question":"給食の部分ということですから、給食の話が出たのでちょっと教えていただきたいのと、あと幼保一体という形で考えていらっしゃる。きっちりこちらの希望とするものをしっかり持っていっていただきたいというふうに思いますが、そこら辺のことをもう少しお願いします。","respondent":"吉岡保育課長","answer":"保育の需要にできるだけこたえられるような施設をということで今考えてあります。そういうものを含めて保育教育機能を持った施設として十分な規模あるいは内容を含ませたいというように考えているところです。","id":"exchange-025"},{"speaker":"金野委員","kind":"質問","question":"最後に、この施設、今回、改正されて幼保一体施設北品川すこやか園となるのですが、この御殿山幼稚園が戻った後、ここはどうなるんでしょうか。すこやか園自体は、そのままそっくり移転をするんじゃないですよね。","respondent":"吉岡保育課長","answer":"御殿山幼稚園が戻った後の幼保一体施設ですけれども、０歳から３歳の保育園だけが残って、４歳・５歳の幼稚園部門はいなくなるということになります。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問","question":"ちょっとその辺の方向性を一つお伺いしたいのと、今度のところで、名称が北品川第二保育園という名前がついていますよね。ちょっと先の方向性で申しわけないんですが、考えがあるんでしたら、その辺を説明を求めました。","respondent":"吉岡保育課長","answer":"就労支援だけを目的にやっているということはございませんで、これはあくまでも幼児教育の中でその充実を図りながら、あわせて就労支援を行うです。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問","question":"従来を引き継いでいくというと、新園のほうが新しくてきれいで、古いほうが吸収されていくみたいな状況ということですか。そこだけ説明を求めました。","respondent":"吉岡保育課長","answer":"建物ですので、いずれ４０年、５０年で老朽化して耐用年数を迎えます。あるいは従来を超える保育の需要があれば、先ほど申し上げたような保育需要の減少ということがあれば、それなりの対応をとっていくです。","id":"exchange-028"},{"speaker":"井上委員","kind":"質問・要望","question":"どういう方針を持った上で、そういう動向を反映させていくのかという基本的な考えによるものがよくわからないんですが、そこはちゃんとあるのか。どういうふうなお考えを、どういう方針で進むよというところをちょっと明確にしていただきたいなと思ったんですが、いかがか尋ねました。","respondent":"吉岡保育課長","answer":"どういう施設に預けようが、お子さんが充実した保育あるいは教育を受けられる場を区民の皆様に提供する、それが一番基本的な方針です。国の制度自体、今まさに検討して詰めているところですけれども、その方向性を十分に見極めながら検討してまいりたいと考えております。","id":"exchange-029"},{"speaker":"井上委員","kind":"質問・要望","question":"もというところもあるかと思うので、その辺をしっかりと意見聴取しながら進めて、慎重に進めていただきたいなというふうに思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問・要望","question":"できれば就労支援と保育園を求めている方、どうしても並列型の幼保一体施設にしていただきたいという思いはありますけれども。第９５号議案については、今日お伺いして、建物がこれから場所が変わるというか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"本間委員","kind":"意見","question":"待機児解消とかというふうに出ておりますし、いかに時代の変化、急激に変化する時代に対応していく経過の中での出来事だと思います。状況は変わるかもしれませんけれども、根底にそういうねらいがあるということをもって、努力されているなということで賛成をいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"西本委員","kind":"質問・要望","question":"所管は違いますけど、議論はまた別になりますけれども、報告をもうちょっとこれからまめにしていただきたいなというふうに思っています。保護者にどういうふうに対応するかというのは、とても重要なことだろうと思いますので、こまめに報告をお願いしたいというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"井上委員","kind":"質問・要望","question":"保護者への説明は十分にして、決定したときではなく、事前の情報提供をしてほしいと求めました。３年、もっと先になるかもしれませんけれども、ぜひ行政としての役割を果たしていただくようにお願いしたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"}]},{"id":"topic-02","title":"の第９８号議案、指定管理者の指定","agenda":"の第９８号議案、指定管理者の指定","exchanges":[{"speaker":"飯沼委員","kind":"意見","question":"説明の文書の裏面のところの、今ちょっと説明があったんですが、「児童福祉施設および第１種・第２種社会福祉事業の運営実績」というところの第１種と第２種をもうちょっと詳しく説明をしてくださいとの意見を述べました。","respondent":"安井子育て支援課長","answer":"第１種の社会福祉事業ということで、児童福祉法第３８条で、母子生活支援施設という形で指定されている施設になっているです。それから、今年度から正式に第２種社会福祉事業になりました養育支援訪問、子育て支援センターで行っている養育支援訪問がそれに該当するものです。","id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問・要望","question":"利用されていらっしゃる方にとっては、本当に連続性とか安定性が求められる施設であると思うんですね。その辺の内と外との評価をどう見ていくのかということと連続性と、その辺、その辺をどう区として把握をしているのかという点を聞かせてください。","respondent":"安井子育て支援課長","answer":"やはり指導とか生活支援をメインにしておりますので、常勤の職員が施設長を含めて９人ほどおりまして、基本的には常勤の職員で対応するということで。","id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問","question":"継続性のところで、ちょっと継続性のところでお伺いしたいのと、あと外からの評価とアンケートのあたりは具体的にどう把握されているのか。そこを説明を求めました。","respondent":"安井子育て支援課長","answer":"利用者のアンケートみたいなものを受け付けるような意見箱みたいなものを用意しておりますので、そこら辺で質的な確保とか、問題点のないような形で進めていくような改善策を進めているです。","id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問","question":"そういった面の考えというんですかね、その辺のお考えがあったら、ちょっとお聞かせ願いたい。","respondent":"安井子育て支援課長","answer":"これまでモニタリング・評価であるとか、決算審査であるとか、予算審査の段階で、議員の方々にも見ていただいているところだと思いますので、そちらについては特に問題があるということはないというようには考えているところです。","id":"exchange-038"},{"speaker":"井上委員","kind":"質問","question":"５年後の変更に今回また改めての指定ということになっていると思うんですが、経費の縮減というのを一つ目標として挙げられているところなので、その辺についてどのような変化が見られているのかということをまずお伺いしたいと思います。","respondent":"安井子育て支援課長","answer":"子育て支援センターについては、虐待対応については人を増やしたり、それなりに対応してきているです。あまりそこら辺のところのコスト面をカットというような話になりますと、逆に非常に問題が出てくる施設だというように認識しています。","id":"exchange-039"},{"speaker":"井上委員","kind":"質問","question":"区は今後どのように考えていこうとしているのか、あるいは全然そういう視点がないのか、ちょっとその辺をお伺いしたいと思います。","respondent":"安井子育て支援課長","answer":"の苦情なんかについて全体的に対応をどうしたかというようなことを明確にしているというような対応をとっております。その中でそれが反映されてくるのだというように私どもは考えておりますので、今のやり方で問題はないのではないかというように考えております。","id":"exchange-040"},{"speaker":"井上委員","kind":"質問・要望","question":"選定委員会の議事録ですかね、どういうやりとりをして、こういう結果に至りましたというぐらいの公開は必要になってくるというふうに思います。どういう議論がありましたかというような議事録の公開とか、そのことについてどのような見解を持たれているのかお伺いしたいと思います。","respondent":"古川子ども未来事業部長","answer":"それぞれ課長４名おりましたけれども、最終的に指定に足る候補者を選定してきた、このように考えております。委員のご意見として承っておきます。","id":"exchange-041"},{"speaker":"井上委員","kind":"意見","question":"そのことを判断する材料が乏しいということははっきりと申し上げておきたいなというふうに思います。意見として受けとめていただいて結構ですけれども、そのことはしっかりと今後の課題として区は考えていくべきことであるというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"西本委員","kind":"意見","question":"この施設の利用について、利用者はどういうふうな傾向があるのか。増えているのか、例年同じような数なのかという動向はどうなのかとの意見を述べました。","respondent":"安井子育て支援課長","answer":"ただ、離婚を前提とした話も十分やっていただいた上でのことを考えていただくようなご相談をさせていただいているというところはあります。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"ショートステイ、トワイライトステイとか相談、先ほど離婚で悩まれている方の相談等々が増えている傾向にあるとのことですが、そのほかの需要は増えているのか、その辺、ざっとでいいので説明を求めました。","respondent":"安井子育て支援課長","answer":"それが本来的な使われ方ですので、そういう意味では、そういう状況を反映しているのかなというように考えております。それから、ファミリーサポートについてですけれども、ファミリーサポートは大体若干ずつ増えているというような形です。","id":"exchange-044"},{"speaker":"西本委員","kind":"質問","question":"そうしようとすると、決められた金額ではやっていけないというふうに思うんですけれども、そこら辺はどういうやり方をされているんでしょうか。そして、その判断として、安定的、継続的にサービスを提供するという、そういう評価になっているのかお聞きしたいと思います。","respondent":"安井子育て支援課長","answer":"そういった意味での経営の安定性、そこから人の配置の問題であるとか、そういったところが確保できているというように考えているところです。","id":"exchange-045"},{"speaker":"西本委員","kind":"質問","question":"それから、これからいろいろ判定してほしいという気持ちがあるものですから、そうするといろいろやりたいと思うんですよね。それをどういうふうなやり方を考えて、これからを考えられているのかなという、この辺はいかがなんか尋ねました。","respondent":"安井子育て支援課長","answer":"例えば先ほどの養育支援訪問のようにそちらを重視して、このときにほかのところから応援してもらいながらこの施設の中だけでも対応ができた。急な場合もそのようにできるというような形での対応が可能になってきているのではないかなというように思っています。","id":"exchange-046"},{"speaker":"西本委員","kind":"質問・要望","question":"離婚される場合に逃げ場所が欲しいとか、そういう部分だってあろうかと思うし、これからどんどん柔軟に対応していただきたい。そのためには、それなりの財源も必要だし、それに見合った対応策、それを考えていただきたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"いいものを選んでいくために指定管理者はあるわけですから、進捗状況を勘案して、変えていくことも検討しているのかということの確認が一つ。だけど、具体的にどういう成果が出てきたのかということを、やっぱり議会側に示していただかないといけないのではないか尋ねました。","respondent":"古川子ども未来事業部長","answer":"この二つの課題を担ってありますので、それぞれの課題につきましては十分に検討し、そしてまたご意見をいただきながら改善を図っていきたい。このように考えております。","id":"exchange-048"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"もう一つだけ要望ですけど、場合によっては１年になるかもしれないけれども、もう少し丁寧な議会に対しての説明をほしいと求めました。そのあとは向こう５年間この議案については家庭あんしんセンターの運営を福栄会に委託するわけですから、特にコスト面の話もぜひいただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"金野委員","kind":"質問・要望","question":"ちょっと要望というか、質問の中で私は言わなかったんですけれども、やはりコストの面というのは気になっていたところです。もう少し資料としても欲しいなというところは私も思っておりましたので、ぜひその点も。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問・要望","question":"外部評価を受けるとか、利用者のアンケートを直接受けとめるなど、透明性を高めていただきたいなと思います。賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"}]},{"id":"topic-03","title":"平成２２年請願第２０号、品川区私立幼稚園児保護者負担教育費軽減に関する請願","agenda":"平成２２年請願第２０号、品川区私立幼稚園児保護者負担教育費軽減に関する請願","exchanges":[{"speaker":"西本委員","kind":"質問","question":"二つ質問をしますが、１番の公私間の格差ということなんですが、何パーセントの方たちが対象になっているのか。それから２番のところですが、していないものなのか、そこら辺を説明を求めました。","respondent":"吉岡保育課長","answer":"実は正確に実施した実際の結果が出るのは年度末にならないと出ないんですが、大体５ポイント以上上がったかなというように考えているところです。その他、この中からは先ほど申しましたけれども、今回ご要望が出ています母の会連合会のいろんな行事の事業費も支援するです。","id":"exchange-052"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、確かに公立はかなりお金を抑えられたという部分はあるんでしょうけれども、それは考え方によるのかなという感じは受けております。この要望としては、確かにそれはありがたいことではあるんですが、どこまでを園としてこれから考えようとされているのか。","respondent":"吉岡保育課長","answer":"所得に関係なく全員の方に補助をするのがいいのかという考えもございまして、所得制限については必要であると考えているところです。現在のご負担の状況、それから区の取り組みの状況を考えれば、おおむね妥当なところにあるのではないかなというように考えているところです。","id":"exchange-053"},{"speaker":"西本委員","kind":"質問","question":"国の流れの一つに、就学前教育というくくりの中で、無料化という話も出ていたと思うんですね。これからいろいろ議論されていくとは思うんですが、それに対して品川区としての考え方はいかがか尋ねました。","respondent":"吉岡保育課長","answer":"就学前教育の無料化あるいは保育も含めて就学前教育の経費の無料化をしていく考え方があることは承知しています。ただ、国や都の動向等を見極めながら区としても判断していくべきものかなというように考えてあります。","id":"exchange-054"},{"speaker":"井上委員","kind":"質問","question":"品川区はどういうふうな判断をしているのかというのが一つと、障害児の１人に対して２０万円という幼稚園への補助というのは、ちょっとそこのところの状況を説明を求めました。","respondent":"吉岡保育課長","answer":"一定先ほど申し上げた考え方の中で、それから、全体を通して見れば他区に遜色のない補助となっているかなと考えております。現在お一人当たり年間２０万円なんですが、これは平成２０年から２０万円に上げておりまして、その前までお一人１０万円ということでございました。","id":"exchange-055"},{"speaker":"井上委員","kind":"質問","question":"５区の制限のところで、制限の基準がまた違うんではないかというふうに思うんですけれども、先ほど５７％の方が交付をされたと、そこのことだと思うんですけど、そうすると、４３％ぐらいの人が品川区は制限のほうに入るわけですが、その辺は他の４区はどういう状況なんか尋ねました。","respondent":"吉岡保育課長","answer":"すみません、他区の状況について、それぞれ何パーセントの方が受給していらっしゃるかというところまでの資料は持ってございません。","id":"exchange-056"},{"speaker":"井上委員","kind":"質問","question":"何パーセントというところではなくても、ここで切るという金額的なものとか、ちょっとその辺、比較でわかるようなデータがあれば説明を求めました。","respondent":"吉岡保育課長","answer":"品川区の場合は、受けることができる区民税の所得割の額２６万３,５００円が上限で、それ以上になると受けられないという形になってあります。","id":"exchange-057"},{"speaker":"井上委員","kind":"確認","question":"では、その制限の中で品川区はちょっと厳しいかなという程度のところで理解すればよろしいんでしょうか。そこだけ確認したい。","respondent":"吉岡保育課長","answer":"制限を残しているのは、千代田区ですとか、新宿区ですとか、中央区ですとか、文京区ですとか、それなりにいわゆる富裕区と言われているところでございまして、財政的にもそれだけのことができるという判断をされているものというように考えております。","id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問・要望","question":"教えてください。保護者補助金と幼稚園等就園奨励費の補助金との違いを教えていただきたいのが一つと、その数ともう一回パーセンテージもそれぞれ教えていただきたい。","respondent":"吉岡保育課長","answer":"保護者補助金については、２１万６,７００円以下の方が対象だったものを、平成２２年度から２６万３,５００円以下の方まで対象を拡大したです。","id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問","question":"それから所得制限の考え方は先ほど伺ったんですが、ちょっとわかりにくいので、例えば保育園の保育料のランクがありますよね。あの辺と比較してどの辺から所得制限に引っかかっていただけないのか、ちょっとその辺をわかりやすく説明を求めました。","respondent":"吉岡保育課長","answer":"それから、大体年収ベースで言いますと夫婦と子ども２人世帯で７３０万円ぐらいの階層の方になろうかなというように思っているところです。拡大をした部分につきましては、年収８７０万円以下の方については大体夫婦と子ども２人で対象になるというように思っているところです。","id":"exchange-060"},{"speaker":"飯沼委員","kind":"意見","question":"保育園の保育料と比較してどうなのかなということ。ちょっと聞いたんですけれども、あまりよくわからなかったんで、もう一回との意見を述べました。","respondent":"吉岡保育課長","answer":"すみません、保育園の保育料については、所得税をベースに設けております。今申し上げた私立幼稚園については、区民税の所得割額をベースにやっていますので、直ちに直接的な比較ができない部分があるかと考えています。","id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問","question":"私もちょっとこの請願者の方に直接お伺いする時間が持てなかったので、ちょっと近所で私立に行き始めた方にお伺いしたら、３カ月で１万５,０００円。２人目になって、所得制限がなかったらどうなるんだろうというような言い方、率直にいかがか尋ねました。","respondent":"吉岡保育課長","answer":"園によっていろんな幅がある中で、入園料から保育料から、設定されているというように理解をしております。そういう意味では、一定お二人、三人とお預けになっていらっしゃる方には配慮をした補助の支給体制になっていると考えております。","id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問","question":"第二子で所得制限に引っかかっている人が、第二子でもいただけないというので、その辺がすごく大きいと思っています。平均どのぐらいとか、ちょっと全体を把握する意味で、わかっている範囲で教えていただけたらと思います。","respondent":"吉岡保育課長","answer":"一番低いところで２６万円代です。それで、一番高いところでも３４万円ぐらい、３５万円弱というところが一番高いところです。","id":"exchange-063"},{"speaker":"金野委員","kind":"質問","question":"もしあったとしたら、どのようなタイミングでしてきたのか、まずそこを説明を求めました。","respondent":"吉岡保育課長","answer":"これができたのは平成３年度、教育研修の費用を補助し始めたのは平成８年度、園児の教材費についても平成８年度というように徐々に拡大をしてきているところです。","id":"exchange-064"},{"speaker":"金野委員","kind":"質問","question":"平成８年に教員の方の研修の費用も出しております、いい教育、園児教育をしてあげたい。それならばこうしてあげようと、こうしていかなければというお考えがあると思うんですけれども、どういうふうにお考えか尋ねました。","respondent":"吉岡保育課長","answer":"園の数も２０園、区立は９園ですので、数からいっても私立幼稚園が果たしている役割は非常に大きなものがあります。必要な補助は区として現在もしていると考えていますし、今後についても同様に続けていく考えですが、振興を図っていきたいと考えております。","id":"exchange-065"},{"speaker":"金野委員","kind":"質問・要望","question":"回って保護者や園児たちの負担を軽減するということにもなると思いますので、その辺はもう一歩いかがでしょうか。お答えいただきたい。","respondent":"吉岡保育課長","answer":"確かにおっしゃるとおりで、いわば保育料のアップを抑えると言いますか、保護者の負担を軽減されることにももちろんなると考えています。先ほど申し上げました特別な支援が必要なお子さんに対する保育の経費の補助、そのような中で、そのように考えているところです。","id":"exchange-066"},{"speaker":"飯沼委員","kind":"質問","question":"預かり保育についてちょっとお伺いしたいんですが、この間きんだぁくらぶが７園から８園に増えたんでしたか。","respondent":"吉岡保育課長","answer":"７園です。","id":"exchange-067"},{"speaker":"飯沼委員","kind":"質問・要望","question":"まだ７園ですか。私立幼稚園の側から、経営者の側から預かり保育について要望とかが出ていましたらちょっとその辺を聞かせてください。","respondent":"吉岡保育課長","answer":"今言った時間まではいかないんですけれども、基本の教育時間が終わった後に２時間の預かり保育をしている園にも一定の補助金を出しています。","id":"exchange-068"},{"speaker":"飯沼委員","kind":"質問","question":"今のところの総額はわかるんですが、幾ら補助金が、どういう算定で出るのかちょっとわからないんですが、補助金の額を知らせてほしいのと、施設からのご意見が、あったらで結構ですから、聞いたんですけど。","respondent":"吉岡保育課長","answer":"預かり保育については、レギュラーの部分も一定保護者の方への支援ということもありますし。さらにもう１時間プラスをする場合は、その１６万円にプラス８万円の補助単価のアップがあるという形になっております。","id":"exchange-069"},{"speaker":"飯沼委員","kind":"質問・要望","question":"やはり、きちんとした預かり保育自体は、朝と夕方と両方というふうに求められる。サービス的な、お母さんたちにいろんな体験をしてほしいからと言ってやっていて、財政的な圧迫があるなというのを率直に感じていますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"井桁委員","kind":"質問・要望","question":"結論を出してほしいと求めました。ぜひとも公私の教育の格差というものは、できる限り考慮していただきたいなという思いがありますので、採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"金野委員","kind":"質問・要望","question":"公明党も今日結論を出してほしいと求めました。そういった意味からも、この請願にあるとおり、このお気持ちはよく私もわかる一人でもありますので採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"飯沼委員","kind":"意見","question":"少しでも子育てのところで負担をなくしていくといった方向に行ってほしいので、所得制限もなくしていく方向に行ってほしいなと私たちは考えています。本請願については賛成、採択ということでお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-073"},{"speaker":"本間委員","kind":"質問","question":"公立の役割分担の違いがあるにせよ、品川区の成り立ちにおいて、私立の補完としての公立幼稚園のやってきた経過があるというようなことでもあります。しかし、品川区もそれなりに格差を近づける努力を何回かにわたっていろんな経費でやってきているものも教えていただいておりますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"西本委員","kind":"質問・要望","question":"じゃあ私立はどうなんだろう、公立のほうはどうなんだろうという、それに対して期待をして通わせているという方もいらっしゃる。委員の質問にもありましたけど、特別支援のお子さんに対しては、増額して考えていただきたいなと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"井上委員","kind":"質問・要望","question":"その辺はやっぱりバランスというものはしっかりとお考えをいただくということで、ほかのところで検討できる部分は検討してほしい。ましてや、２３区中５区ということでしたので、そういうことも視野に検討いただければいいなということを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"}]},{"id":"topic-04","title":"平成２２年請願第２１号、一人ひとりの子どもたちが大切にされる品川区を求める請願","agenda":"平成２２年請願第２１号、一人ひとりの子どもたちが大切にされる品川区を求める請願","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"ちょっと区の受けとめ方をお伺いしたいなと思うんですけれども、その辺、区としてどう受けとめているのかというあたりを一つお伺いしたい。多分自治体としても、今回は議会に求められているんですけれども、その辺を含めてお聞かせほしいと求めました。","respondent":"吉岡保育課長","answer":"考え方としては、またこれも「子ども・子育て新システム」の中の言葉ですけれども、子ども施設という新しい考え方の施設に指定をする。つい最近まで案が五つも出されて、どれにするかということを検討している段階ですので、いずれにしても。","id":"exchange-077"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひこの辺に対するお考えがあったら聞かせていただきたいんですが、ぜひ本当に聞かせていただかないと、ちょっと幾つかお聞きをしたい。直接選ぶ制度のことですから、保護者が機関を選択できる制度とすべきであるといったところでは、多様な形態が存在している。","respondent":"吉岡保育課長","answer":"国の方針自体が、先ほど言った５案を出されて、こうしてくれという話を区として申し上げるつもりはございません。幼稚園と保育園が連携をしながら、よりよい保育・教育を受けられるように努めてまいりましたので、その方向を堅持してまいるです。","id":"exchange-078"},{"speaker":"飯沼委員","kind":"提案","question":"認可保育園の直接契約方式を導入しないことを求める意見書というのが国に向けて、１０月１９日なんですが、出されています。先ほども平成２３年に国会に法案が出されて、平成２５年から実施をする中身においては、お伺いしたいなと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-079"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺がどうなっているのかというのを具体的に教えていただきたいのと、朝夕の時間帯だと、その辺も含めてお伺いをしたいと思います。この辺の提言とこの経過と今後のスケジュールが出されている中で今現在どのようにお考えなのか、もう一回お聞かせほしいと求めました。","respondent":"吉岡保育課長、田村庶務課長、和氣学務課長","answer":"先ほど待機児童対策担当課長からもお答えしましたように、一定保育を実施するに当たっては、保育園の面積の最低基準があります。ただし… 登録児童が大体決まって、学校の規模もありますけれども想定ができるので、基本的には登録児童に合わせて常勤と委託のところで対応する。… ３０人学級のスケジュールが示されたとありますが、これが決まって、私どもに提示されているわけではございません。","id":"exchange-080"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった中身が、先ほども私本当に詰め込みと言われるのは心外だというのは、これは反対に詰め込みを認めているということではないでしょうか。今のそういった専任職員を通しての責任を果たしてほしいということであると思うので、その辺、ちょっとお答えをいただきたいなと思います。","respondent":"田村庶務課長、吉岡保育課長","answer":"例えば保育園、採用計画でどのように見込んで、私どもがすまいるスクールだけの中で正規の職員を継続するとかしないとかということではなく。冒頭お話ししたように、そういう内容なのかどうかが不明だということで… 詰め込みか詰め込みでないかというのは、感覚の話ではなくて、保育園の施設の面積基準に基づくものであるということ。","id":"exchange-081"},{"speaker":"飯沼委員","kind":"質問","question":"私は１点目では皆さんのご意見をお伺いしたいという……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"飯沼委員","kind":"質問","question":"でも、項目がたくさんあるんだから、仕方がないんじゃないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、前から要望していますけれども、しっかりと継承してほしいということです。むしろ柔軟なクラス編成というんですかね、そっちのほうが重要ではないかなと思いますが、その意見に対してのご答弁をお願いします。","respondent":"田村庶務課長、和氣学務課長、吉岡保育課長","answer":"地域と連携をとってやっていますので、引き続き協力してやっていきたい、開かれたすまいるスクールにしていきたいと思っています。… 私どもは、私ども独自の教員を採用したりするなどして、質を確保しながらやっているところです。保育の実施の主体は区になりますけれども、今までも既に実施してきていることでありますので、ちょっとよく理解できない点があります。","id":"exchange-084"},{"speaker":"西本委員","kind":"質問・要望","question":"これからの大きな課題になるだろうと思っていますが、私はやっぱりすまいるスクールの専任は、区の職員であるべきだと思います。なぜかというと、中途採用がどうとか、ぜひ区の職員をしっかりと採用してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"金野委員","kind":"質問・要望","question":"そこら辺はしっかりこれからも頑張っていただきたいなという思いがありますので、品川区はこうだったんですというような一つ答弁をいただきたい。現状をちょっと確認させていただきたいんですけれども、学校の中ですまいるスクールをやっているので、そこら辺をちょっと説明を求めました。","respondent":"吉岡保育課長、田村庶務課長","answer":"幼保一体化の推進ですとか、あるいは保幼小の連携あるいは交流事業、そういうような形で進めてまいりました。今後につきましても、その流れをしっかり継続しながら取り組んでいきたいというように考えているところです。事故が起きたときも保護者の対応も、やはり日々学校と連携をとっているというのが実態ですし、それは日々の仕事の中で形ができています。","id":"exchange-086"},{"speaker":"金野委員","kind":"質問・要望","question":"学童というのは、学校の中で見えない部分を今見えているお子さん、これはすごくいいことであろうというふうに思う。学校との連携で、よりお子さんの心配なところなどがあればしっかりと見てほしいと求めましたので、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"},{"speaker":"井上委員","kind":"質問・要望","question":"文面はさておき、もうちょっとちゃんとそのための影響というのをしっかりと把握していただく必要があるなというふうに思っております。どういうふうにこのシステムを評価しているのか、通ったとすればどういうことが、ちょっとお知らせをほしいと求めました。","respondent":"吉岡保育課長","answer":"今の時点でいろんな案を検討していることに対して、Ｂ案はどうだということを区の立場として言うこと自体意味があることなのかということです。そのように思っております。","id":"exchange-088"},{"speaker":"井上委員","kind":"質問","question":"法案の内容がどうこうということではなくて、そういうことで品川区の裁量でそうではないですよということができるということなんでしょうか。自治体は責任として、そこのところをちょっと私たちは素人でよくわかりませんから、どういう影響があるとお考えなのか説明を求めました。","respondent":"吉岡保育課長","answer":"このような中で、こうなんじゃないか、ああなんじゃないかという過程をもとにして議論すること自体がふさわしい状況だというようには考えていないです。","id":"exchange-089"},{"speaker":"井上委員","kind":"質問・要望","question":"こういうことに対して品川区としてはどういう対応をとっていかれるつもりですかということをお知らせいただきたいということなので、そこのところを品川区としてはどう考えているんですかということを、もう少しピントに合って答弁していただきたいなと思います。","respondent":"吉岡保育課長","answer":"Ｂ、Ｃの可能性自体が、こういうものだということ自体が見えてきていないわけですね。その中で今おっしゃったような議論をすること自体がふさわしいことではないというように考えております。","id":"exchange-090"},{"speaker":"井上委員","kind":"質問","question":"児童福祉法第２４条に基づく、どういった制度がどういうふうになっても、国の動向に対して区はどういうふうに保障していこうと思っているんか尋ねました。","respondent":"吉岡保育課長","answer":"基本的には区の保育事業については、児童福祉法に基づいて実施していますので、今後第２４条が変わらない限りは、市区町村の責務として実施してまいるです。","id":"exchange-091"},{"speaker":"飯沼委員","kind":"質問","question":"そこのところ、部長いかがでしょうか。〔「それは行政だもの、当然でしょう」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"飯沼委員","kind":"質問","question":"いろいろあるはずで、その守りたいところが守れない状態になるような事態を招かないように、事前にやっておくべきことも当然あると思うんですね。法律が変わったらどうかわかりませんよというようでは、区の指し示す方向がどうなのかと、いかがか尋ねました。","respondent":"古川子ども未来事業部長","answer":"現時点での児童福祉法第２４条については当然にそれを前提にさまざまな保育の実施責任を果たしているところであります。それはあくまでも品川区ができる範囲の中での保育政策であると、そのように考えております。","id":"exchange-093"},{"speaker":"飯沼委員","kind":"質問","question":"意見を上げてほしいというところなので、その辺を質問したんであって、やはりその法案が先に行かないように歯どめをかけておく。だから、これには拙速な導入をしないようにということですから、この範囲は私は区民として当然だと思うんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-094"},{"speaker":"井桁委員","kind":"質問・要望","question":"それから３番目、いずれにしてもすまいるスクールは大変評判のいい事業の一つでもありますので、しっかりと行っていっていただきたいと思っています。それから４番目、やはり一人ひとりの教員の方の質というのをこれからは考えていっていただきたいなと思いますので、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"金野委員","kind":"意見","question":"公明党としては、結論としては不採択。それから学校のすまいるスクールにしても、この請願に関しては、不採択ということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-096"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ本当に認可の保育園を必要数つくっていただきたいという意味では、これも主張を採択すべきである。ぜひ一体になって３０人学級、少人数学級を進めていただきたいなと思っていますので、ぜひ採択をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"本間委員","kind":"意見","question":"そして、３０人学級だからという数だけで、あまり３０人というような形にこだわらないでいったらどうかなというふうに思います。１、２、３、４項目について、不採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-098"},{"speaker":"西本委員","kind":"質問・要望","question":"補助金等々、助成金に対してどういうふうに考えてやっていくのかというところは、先々を見ながらやっていくべきだろうなというふうに思っています。３０人学級は、やっぱり教育現場、その状況に合わせた体制がとれるような柔軟性を持っていただきたいというような意見を持っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"井上委員","kind":"質問・要望","question":"児童センター、ノウハウはぜひ単年度契約で非常勤を雇うということではなくて、検討いただきたいなというふうに思っています。３０人学級のところは、ぜひ１番に対しては議会としてしっかりと文教委員会として学習をし、その上で判断をさせていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"}]},{"id":"topic-05","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺をもうちょっと詳しくご答弁いただきたいのと、さらに増設を」の中で、４８７人のところの内訳をもう一回きちんとお伺いしたいなと思います。繰り返しにならないようにしますから、今後のことについてちょっとプラスアルファでお伺いしたいなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-101"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/746735?Template=document&Id=4718#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":71091,"voices":237}},{"id":"h22-20101213-5","meetingId":"h22-cm12","date":"2010年12月13日","dateIso":"2010-12-13","committee":"総務委員会","time":"午前１０時０５分～午前１１時３１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"審査、調査等の支障にならない範囲で許可していいんじゃないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"林委員","kind":"質問","question":"そういうのは念押しというか、条件付きというか、それはできるんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"林委員","kind":"質問","question":"そうすると、委員長から申請があった人にそういうお話を事前にするということは可能なんですか。始まってから「ちょっと待って、今聞いてきて」というのもおかしな話だから、始まる前にそういうことを聞いておくというのもできるんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"土井委員","kind":"質問","question":"最初のあいさつのところだけ撮っていただいて、「ここから先はご遠慮ください」というようなことでやりますので、その形が一番よろしいんじゃないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"林委員","kind":"確認","question":"問い合わせという言葉でいいかどうかわからないけれども、それで、各区ごとに委員会がいつ付で認めますよという仕組みなんですか。私たちも何十回ともらったことがあるんだけれども、改めて確認をします。","respondent":"桑村区議会事務局長","answer":"今の人事委員会への申請につきましては、区議会事務局の方から送っているものですので、私の方からお答えさせていただきたいと思います。","id":"exchange-005"},{"speaker":"宮崎委員","kind":"提案","question":"この条例提案というのが形としていきなり出てくるということになるのか。そこら辺、手続き上どういうふうになるのかと思うんですけれどもとの意見を述べました。","respondent":"伊勢総務課長","answer":"区長の期末手当を引き下げると、その条文を引用している区議会の議員の方々の分も変わりますし、それから常勤監査委員も変わるということで、単に条文がすっと変わるだけではなくて、事前にお話をしまして、その内容についてご意向を伺っているという状況です。","id":"exchange-006"},{"speaker":"宮崎委員","kind":"質問","question":"そういうふうに事前にはあるんだろうと思うんですけれども、具体的な形として、手続きとしてはどういう形になるのかなというのをちょっと聞きたかったものですから。","respondent":"伊勢総務課長","answer":"書面とか、形とかというのは特にございません。","id":"exchange-007"},{"speaker":"土井委員","kind":"質問","question":"区長、副区長等について、我々も含めて、報酬審議会というのがあるんですけれども、これとの関連、関係はどうなんか尋ねました。","respondent":"伊勢総務課長","answer":"それから区長、副区長の給料について審議しているものでございまして、期末手当については審議対象としていないです。来年１月に予定してございまして、そこでは期末手当は審議対象ではございませんが、その場で報告をしたいというふうに考えてあります。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問・要望","question":"常勤監査委員の期末手当が引き下げられるということは、流れとしては、私はこれに賛成です。私は少ないと思いますので、その点、そういう報告を私はぜひ区議会事務局からも求めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"}]},{"id":"topic-02","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"宮崎委員","kind":"質問・要望","question":"そうしたことを行政はどういうふうに見ているのか、考え方を聞かせてほしいと求めました。家族の労賃との関係で、今回３回目の請願なんですけれども、どういうふうにお考えなのかなと思うんです。","respondent":"武内税務課長","answer":"第５６条については、それを今、品川区として住民税の関係をどうするのかというところまでまだ至っていないということでよろしくお願いします。今の説明のとおり、それぞれ家族従業者であっても、ぜひそういう青色申告の方法で申請していただければと考えております。","id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問","question":"所得税法第５６条の廃止についてはどうなんだという質問をしまして、横断的に扱ってみたい、検討してみたいという趣旨の発言があったんですね。そうなると、地方自治体としても一定程度考え方が問われてくるのではないかと思うんですが、その辺についてはどうでしょう。","respondent":"武内税務課長","answer":"この８６万円、５０万円という部分については、私としてはそういうとらえ方をしていただきたいと考えています。今回の第５６条につきましては、国からそういう方向だという公文書が来ているわけではありませんので、そこまでの情報はつかんでおりません。","id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問","question":"工場数で２,６６５事業所から１,５２４事業所と、１人から３人の工場も、また商店数も２００２年から２００７年で約５００店近く減ってきている。ですから、今回もぜひ、議会としても採択して、意見を言っていくというのが必要ではないかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"土井委員","kind":"質問・要望","question":"今日出されております請願は、廃止を求めるという形になっておりますので、見直しとは違うニュアンスを含んだ中身です。人としての、法人という人格のものが納めるべき責務との間の、ちょうどその中間みたいなところでどうすべきかということでいろいろ問題があった。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問・要望","question":"白色から青色申告の方にもっとコマーシャルし、また、もっと「簡単にこういうふうに移行できますよ」と指導する方に力を入れるべきではないかと。ですから、それを起点にして、白色の人を青色に誘導するような施策を率先して進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"林委員","kind":"質問","question":"この８６万円と５０万円というのは、事業主が申告するときに控除されるという性質の金額なんですか。事業主が商売をやっていて、給与が出ないからこういう基礎控除みたいなものを認めているというのが基本的な考え方なんか尋ねました。","respondent":"武内税務課長","answer":"自分の子どもにこれだけ支払いましたよという限度額が８６万円、５０万円と決められていまして、認められるものではありません。","id":"exchange-015"},{"speaker":"林委員","kind":"質問","question":"そうなんですか。そうすると、奥さんが事業をやっている場合もあるだろうけれども、その人の所得から控除されるという性質のものではないと。","respondent":"武内税務課長","answer":"ですから、収入を得まして、奥さんがご主人の仕事をお手伝いして、それを給料に換算して１カ月幾らといったときに、それが白色申告の場合については８６万円しか経費として認めませんよという控除になります。","id":"exchange-016"},{"speaker":"林委員","kind":"意見","question":"奥さんも店番をやっているとか、そういうことでご主人が奥さんに８６万円までは払っていいですよと、そういうものではないんでしょう。ここに必要経費には認めないと書いてあるからとの意見を述べました。","respondent":"武内税務課長","answer":"ですから、それ以上をその文房具屋のご主人が奥さんに対して給与として例えば１２０万円を払ったときは、青色申告をしてくださいと。奥さんにこれだけ払いますというのが８６万円以上になる場合については、そういう中身です。","id":"exchange-017"},{"speaker":"林委員","kind":"質問","question":"一般的に考えると、売り上げとして入ってきた中から奥さんに８６万円あげると経費でしょう。そういう考え方ではないんか尋ねました。","respondent":"武内税務課長","answer":"ただ、その限度額が、人によって場合によっては８６万円以上払うという可能性が出てくると思うんです。それが、白色申告の場合については８６万円しか経費として認められませんよというものです。","id":"exchange-018"},{"speaker":"林委員","kind":"質問","question":"例えば、奥さんとご主人の相談で、「私も１５０万円欲しいわよ」と言うと、６４万円分はご主人のポケットマネーという考え方に立つんか尋ねました。","respondent":"武内税務課長","answer":"ですから、それだけ収入が増えている状況の場合でしたら、原則的には青色申告をしていただければ奥さんに対して１５０万円支払ったとしましたら、その帳簿等を確認することによって、１５０万円を必要経費として認められるということになります。","id":"exchange-019"},{"speaker":"林委員","kind":"質問","question":"それでさっきから青とか白とか混乱するような話を繰り返しているわけですね。例えば、これは所得税に関する話をしているんだけど、品川区に払っていただいている住民税には全く関係がないんか尋ねました。","respondent":"武内税務課長","answer":"自己申告をしていただきまして、これが現実的に第５６条の廃止になりますと、それに基づいて住民税の額も下がるという状況が出てくるのかなと。事業主の方の必要経費を認めるということになりますので、住民税も低くなるということは想定されます。","id":"exchange-020"},{"speaker":"土井委員","kind":"質問","question":"そういう意味ではさまざまな会や団体がおありでしょうから、そういう団体等においても、ぜひともその方向で働いていただくということが適切なのではないかと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"宮崎委員","kind":"意見","question":"先ほど、青の方は記帳義務がある云々というお話があったんですけれども、白色の方も昭和５９年に記帳義務があるようになっていますから、そのときにそういうところは是正するのが本来のやり方だったのではないかなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"林委員","kind":"質問","question":"高い給料を払うのか、第５６条というものを定めた根拠というか、意味はあるわけですよね。所得税法の第５６条、これを廃止したときに弊害が起きるんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"林委員","kind":"質問","question":"今でもちょっとわからないのは、白というのは伝票とか何とか要らないわけでしょう。白色でも、申告するにはそれなりに計算の基軸があって届けるんか尋ねました。","respondent":"武内税務課長","answer":"は前々年が３００万円を超えている場合については、簡易的な内容の経費の内訳等の記帳義務というのは当然発生してきます。３００万円以下の方については自己申告という形の中で受付されていると聞いています。","id":"exchange-024"},{"speaker":"林委員","kind":"質問","question":"３００万円というのは商売の上がりが３００万円ということですか。それとも商売をやっている経営者というか、その人の所得が３００万円ということになるんか尋ねました。","respondent":"武内税務課長","answer":"日々１年間働いて、そこから税金の申告をするときには、所得ということでさまざまな控除があります。それによって白色申告についても申告の中身について若干変わってくるというふうになっています。","id":"exchange-025"},{"speaker":"林委員","kind":"質問","question":"何と言ったらいいのか、白色というのはそんなに几帳面に帳簿をつけて申告する必要はないだろうと思っていたんだけれども、そうではないんですか。商売をやっていたら、３人働いてもらっているから５００万円ずつ払ったら赤字になったとか、白色はそのぐらい適当な話ではないんか尋ねました。","respondent":"武内税務課長","answer":"申告される方が日々の１年間の収入においてしっかり計算をされて、税務署の方に３月１５日までにしっかり申告されていると私は考えております。あくまでも個人で、自分で商売をしているということです。","id":"exchange-026"},{"speaker":"堺委員","kind":"確認","question":"白色申告ではなくて青色申告に変えていただくならば改善されますよというふうに理解をしていいのかどうかという、その点を確認しておきたいんです。念を押すようで申しわけないですが、確認をしておきたいと思います。","respondent":"武内税務課長","answer":"委員言われるとおり、今の認識で間違いありません。ですから、全部がそういうものに該当しているというのはちょっと違うのではないかと思います。","id":"exchange-027"},{"speaker":"堺委員","kind":"質問","question":"それはどうなんですか。そこまで行くと、請願を出している人については大きなお世話だと言われてしまうのかもしれませんが、その辺、どういうふうに考えたらいいか尋ねました。","respondent":"武内税務課長","answer":"ぜひ、そういう団体を使ってやれば、複雑な税の申告等も若干なりともできるのかなと考えております。青色申告会と事務打ち合わせをする中で、会員の募集等は税務署の方でやられている、青色申告会独自でやられているというのが現状です。","id":"exchange-028"},{"speaker":"林委員","kind":"質問","question":"不採択でお願いしたいと思うんですけれども、その前に区議会事務局長に伺いたいんですが、何か意味合いがあるんか尋ねました。","respondent":"桑村区議会事務局長","answer":"基本的に趣旨が伝わって、請願内容がはっきりすれば、請願というものは基本的に受けるという立場です。何か違った意味にとらえられる、あるいはこれによって惑わされるようなことはないので、このままで受けることは可能だと思って受理しているものです。","id":"exchange-029"},{"speaker":"堺委員","kind":"意見","question":"第５７条というところで、第５６条の廃止ではなくて、必要ならば見直しということが出てくるのかもしれません。そういう意味では、第５６条を補足する第５７条が明確にありますから、この請願については不採択ということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今、不景気の中でこういう方々が商売をやっていけないという事態もあるわけですから、必要な方々にはちゃんと賃金を保障するという方向でやっていく。特にそういう不公平な扱いになっているのは早急に是正するということは当然だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"}]},{"id":"topic-03","title":"平成２２年請願第２７号、米軍普天間基地移設の日米合意の見直しを求めることに関する請願","agenda":"平成２２年請願第２７号、米軍普天間基地移設の日米合意の見直しを求めることに関する請願","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"ですから、アメリカの基地そのものがハーグ陸戦法規、要するに国際法上からも許されないつくり方をやっているんです。ですから私は、この請願については賛成して、ぜひ皆さんにもご賛同いただいて、意見書を出していきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"林委員","kind":"質問","question":"結論は、そんなに長く品川区議会で持っているということをしないで出すべきだと思います。日米の同盟が基軸になって安全保障だ何だといろいろやってきているわけですから、政府がきちんと、早く結論を出すことは大事なことだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"土井委員","kind":"意見","question":"ましてや、第９５条との兼ね合いだけでお話をされたのでは、ちょっと解釈上いかがなものかというふうにも思っております。ですので、この内容につきましては同意できないとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"堺委員","kind":"質問・要望","question":"１２月１０日ですか、県議会が開会されたようですが、その中で移設問題についても触れられているようです。しかし、移設までの対応としては、早期に、危険性の除去や騒音の軽減に取り組むように求めたい、このような趣旨のご発言があったやに伺っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"須貝委員","kind":"質問・要望","question":"ですが、本来、防衛・外交の問題は国会でどんどん議論していただきたい。今日、結論を出してください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/212618?Template=document&Id=1872#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":22266,"voices":106}},{"id":"h22-20101214-6","meetingId":"h22-cm12","date":"2010年12月14日","dateIso":"2010-12-14","committee":"区民委員会","time":"午前１０時０２分～午後１２時０２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件整理しています。","topics":[{"id":"topic-01","title":"を行います。 初めに、(1)在住外国人のための多言語ガイドツアー","agenda":"を行います。 初めに、(1)在住外国人のための多言語ガイドツアー","exchanges":[{"speaker":"菊地副委員長","kind":"質問","question":"賃金と言ったらおかしいですか、観光協会からそういうものがあったりとか、そういう話なのかどうか。そこだけ教えてくれますか。","respondent":"秋山協働・国際担当課長","answer":"観光協会の、ガイドＴＯＫＹＯ・しながわのご協力ということで、一応、ボランティアということで対応していただいて、それぞれの言語ができる方をお願いするという形になっております。","id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問","question":"そんな背景があれば教えてください。ちなみに、在住外国人の方の国籍の多い順というんですかね、参考までに伺えたらと思います。","respondent":"秋山協働・国際担当課長","answer":"言語の対応というのは、今回は、しながわ観光協会の中でこちらの言語が対応できるということでお願いをしたものです。ボランティアということなので、対応については、今回はこの４言語という形になります。","id":"exchange-002"},{"speaker":"山内委員","kind":"意見","question":"今、課長の説明で、韓国の方が多いといった中で、なぜ韓国語の対応がないのか。協力していただけないのかということですとの意見を述べました。","respondent":"秋山協働・国際担当課長","answer":"韓国の国籍の方なんですけれども、永住者の方が比較的多いので、日本語ができる方が多いです。","id":"exchange-003"},{"speaker":"山路委員","kind":"質問","question":"その辺も、話せる人を探してと言うとあれですけれど、表紙とかよく書いてありますよね。そういうのを書く人を選んで、こういうところで活用するというのは、どうなんか尋ねました。","respondent":"福島ものづくり・経営支援課長","answer":"すぐには難しいかと思います。よろしくお願いします。","id":"exchange-004"}]},{"id":"topic-02","title":"区民活動交流施設「こみゅにてぃぷらざ八潮」の開設","agenda":"区民活動交流施設「こみゅにてぃぷらざ八潮」の開設","exchanges":[{"speaker":"山内委員","kind":"質問・要望","question":"それから、これはよく目の当たりにするんですけれども、なぜこの「こみゅにてぃぷらざ」と、これは普通、横文字ではないですか。そのあたりを教えてほしいと求めました。","respondent":"堀越文化スポーツ振興課長","answer":"それで、これを決めるに当たって、地域の自治会長さんですとか、そういう方で愛称の決定の検討会を開きました。少しやわらかい感覚を出すとか、そういった観点で平仮名でどうかという意見があって、決定したという次第です。","id":"exchange-005"},{"speaker":"山内委員","kind":"質問・要望","question":"それはもう個人個人の感じるところだから、それはそれでいいんですけれども。少し見づらいのかなといったイメージがあったりしたんで、そこは意見として述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"渡辺委員","kind":"質問","question":"協働推進室のところなんですが、募集をされて、その経過だとか状況を伺えればと思います。明晴学園前があって、アクセスの中で、バス事業者とのやりとり等はどんな経過なのかを説明を求めました。","respondent":"秋山協働・国際担当課長、堀越文化スポーツ振興課長","answer":"前は、決定の手続中ですけれども、応募は１０団体ございました。その中から今、どの団体をです。 バス事業者とのやりとりというお問い合わせですけれども、バス停の名称というお尋ねでよろしいでしょうか。","id":"exchange-007"},{"speaker":"渡辺委員","kind":"質問","question":"定数８でしたか。それに対して、ほぼ埋まる見込みと考えているのか、説明を求めました。","respondent":"秋山協働・国際担当課長","answer":"それから社団法人が１団体です。それで１０団体です。","id":"exchange-008"},{"speaker":"渡辺委員","kind":"意見","question":"もし、言っていけないのであれば、これはいいです。お願いしますとの意見を述べました。","respondent":"秋山協働・国際担当課長","answer":"高齢者向けの団体、それからコミュニティビジネスの普及ということの団体、それから子育ての支援ですとか障害者の活動、それから地域の子ども向けのものが複数ありまして、です。","id":"exchange-009"},{"speaker":"山路委員","kind":"意見","question":"オープニングイベントについて、ここに出られる方は大体、若い人、地域の自治会の協力があってと思うんですけれど。長くはできないから、午前中に高齢者の人にやってもらうとか、そういうものもできたら交渉して加えたらと思うんですけれどとの意見を述べました。","respondent":"堀越文化スポーツ振興課長","answer":"ちょっとした簡単な出店みたいなものも考えて、まだ決定まで至っていないんですけれども、実際に話を進めながら準備を進めているという状況です。そういった委員のお話があったことも伝えたいと考えております。","id":"exchange-010"},{"speaker":"菊地副委員長","kind":"質問","question":"１月４日から受付開始ということなんですけれども、広報しながわを見ても、料金体系というのは出されていなかったような気がするんですけれども。その辺の周知というのはどうするんか尋ねました。","respondent":"堀越文化スポーツ振興課長","answer":"そのほか、八潮以外の文化センターなんかでも、キャンペーンといいますか、そういう配布等、ご案内はしていただいておりますので。そういう中で、料金についてもご案内していきたいと考えています。","id":"exchange-011"},{"speaker":"高橋委員","kind":"質問","question":"受付と清掃等を、ほかのところに出すんですけれど、これは１月から３月までなんでしょうか、また来年度も引き続きそこがやるのかどうかということと、今年度分で、それぞれ受付と清掃は予算はいくらなのか尋ねました。","respondent":"堀越文化スポーツ振興課長","answer":"１月から始まりまして、また来年度も継続して、同じ業者にお願いをする。設備保守点検で言うと１,１００万円ですとか、まだ大体の見込みとして、それぐらいで見積もっているです。","id":"exchange-012"},{"speaker":"高橋委員","kind":"確認","question":"平成２３年度の予算は置いておいて、平成２２年の３カ月で、受付だけですけれど、８００万円というのをもう一回確認します。","respondent":"堀越文化スポーツ振興課長","answer":"１２月からの準備業務も入っています。その部分を合わせていますので、４カ月間という形になるかと思います。","id":"exchange-013"}]},{"id":"topic-03","title":"新公益法人制度の概要","agenda":"新公益法人制度の概要","exchanges":[{"speaker":"菊地副委員長","kind":"質問・要望","question":"実際に認定をする主体はどこになるのかというのを１つ、教えていただきたい。その辺、考え方を教えていただけますか。","respondent":"堀越文化スポーツ振興課長","answer":"実際、３０人ぐらいいたところが、評議員で言うと１２、１３人という形で。理事で言うと、１０人程度という、そういう例が２３区の、既に公益認定をとったところの例で言うと、それぐらいの規模のところが多いと聞いています。","id":"exchange-014"},{"speaker":"菊地副委員長","kind":"意見","question":"そうすると、さっきあった選定委員会をつくって、理事や評議員を決めていくという話なんですけれども。そうすると、そこに何らかの形で、推薦をするとかという形式が生まれると思うんですけれども、その辺はどういう形式で行われているのかとの意見を述べました。","respondent":"堀越文化スポーツ振興課長","answer":"選定委員会は、それを加味しながら決定ということもあるでしょうし、選定委員会独自の判断で評議員を決めるということもあるでしょうし。最初の評議員については、外部の目も入れた形で、選定委員会でやりなさいというのが趣旨となっております。","id":"exchange-015"},{"speaker":"菊地副委員長","kind":"質問","question":"きのうの話で、定款そのものもある程度、手をつけていくということですから、そうした状況が生まれるのかどうか。最後にそこだけ説明を求めました。","respondent":"堀越文化スポーツ振興課長","answer":"法人格の変更と認められるのであれば、何と言いますか、適切にきちんとやらなくてはいけないという形になってくるかと。いずれにしても、詳細についてはこれからまた詰めて、ご報告をするという形になるかと思います。","id":"exchange-016"}]},{"id":"topic-04","title":"の議会閉会中継続審査調査事項","agenda":"の議会閉会中継続審査調査事項","exchanges":[{"speaker":"高橋委員","kind":"質問・要望","question":"要望なんですけれど。これは要望で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/397696?Template=document&Id=2598#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":14083,"voices":75}},{"id":"h22-20101214-7","meetingId":"h22-cm12","date":"2010年12月14日","dateIso":"2010-12-14","committee":"厚生委員会","time":"午前１０時０２分～午後０時３３分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"大沢委員","kind":"意見","question":"撮影は可としますが、通例に従っていただいて、審議に入る前の段階ということでお願いしたいと思います。これは通例に従っていただければ、混乱が生じないということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"山元委員","kind":"質問・要望","question":"１・２階の部分で介護予防事業を実施するということなんですが、具体的にどういうような活用をなされるのかをちょっと教えていただきたいのですが。それと、まず、ではそれを教えていただけますか。","respondent":"間部高齢者いきがい課長","answer":"りんし２１における介護予防事業ですが、今のところはまだ詳細については検討中ですが、マシンを使わない形の筋力トレーニング等を行う予定です。","id":"exchange-002"},{"speaker":"山元委員","kind":"質問","question":"実は、ちょっとこの意にそぐうかどうかわからないのですが、今、とても待機児童、いろいろありまして、何か保育ママ的な、そういう施設みたいなことは、お考えはなかったのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"２階部分を従来どおり地域住民が利用できるということですけれども、何というんですか、それとも違う位置づけなのか。この辺はどういう扱いになるのか、今後の運営についてご説明いただけますか尋ねました。","respondent":"冨岡高齢者福祉課長、間部高齢者いきがい課長","answer":"今も在宅介護支援センターの部分につきましては、運営に関して協定を結んでいるわけでありまして、それで社会福祉法人三徳会が管理をしています。利用については、その中で… 介護予防事業を実施するに当たっての改修の件ですけれども、面積をとられてしまうことと、今回についてはマシンを使わない形を検討しています。","id":"exchange-004"},{"speaker":"中塚副委員長","kind":"質問","question":"でも、建物は品川区のもののままでしょうから、どういう形の協定なのかと思います。そこのところをご説明いただけますか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"すみません、あくまでも業務を委託するという内容です。","id":"exchange-005"},{"speaker":"三上委員","kind":"質問","question":"地域的にそこの分室的な考え方でここのところを小山台の奥のほうまで担当するというような形で分けたというふうにとらえていいということですか。そこのところははっきりしてくれないと、先ほどの副委員長の質問にも的確に答えていないのではないかと、こう思うんですけれども。","respondent":"冨岡高齢者福祉課長","answer":"２０番目の在宅介護支援センターとはいいますけれども、やはり機能を分化したというところがもとの状況で社会福祉法人三徳会にもお願いしているというところになるかと思います。","id":"exchange-006"},{"speaker":"三上委員","kind":"意見","question":"要するに、ちょっとどこからどこまでかわからないけれども、それが全部小山台一丁目も二丁目も担当しているということなんでしょう。二丁目中心の地域の人についてはサービスを提供すると、こういうふうに理解していいのでしょうと、こういうことですとの意見を述べました。","respondent":"冨岡高齢者福祉課長","answer":"おっしゃるとおりです。","id":"exchange-007"},{"speaker":"稲川委員","kind":"質問・要望","question":"私からは、最後のこのページの個人情報保護法というんですか、これについてお伺いしたいと思います。これを見た知識がある方は、それはだめだよという話になるのか、どういう効力がこの活用ルールにあるのかを教えていただきたい。","respondent":"冨岡高齢者福祉課長","answer":"注意しなければならないというものがありますので、それについてあくまでもベースにしながら情報活用のルールを定めていきたいと考えています。それから管理の方法もしっかりと定めた上で利用していただくというふうに進めてまいりたいと、これからの話ですが、そういうことです。","id":"exchange-008"},{"speaker":"稲川委員","kind":"質問・要望","question":"例えば事例でちょっとお伺いしたいのですが、地域の方、あそこの家は例えばちょっとおかしいと。民生委員の人はどうすればいいのかと、その一文を入れるように、その辺を今後どうやられていくかということをちょっと教えていただきたい。","respondent":"冨岡高齢者福祉課長","answer":"その場合、行政機関がやはり対応していくということで、それは区民の方から情報をいただいて早く公的な機関が対応するという。ですから、その辺はちょっと慎重にまた検討してまいりたいと思います。","id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"ＮＰＯなり、その辺についてどういうふうに話し合いが進んでいるのか、ちょっとその辺も伺っておきたいと思います。策定委員会が、このメンバーはどういう方々が策定委員になっておられるのか、それも教えてほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"ほかのところに展開できませんので、それをまず３年の期間でやっていきたいという、そこから出発したいというところの検証も含めてという意味です。それから商業関係、商工関係の代表の方、それから福祉団体の代表の方等々です。","id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"１０年に限らず、そういう認識でしっかりした検証をしていただきたいと考えていますので、ちょっと期待して見ていきたいと思います。充実した内容にしていただきたいと思っていますので、別に答弁は要りませんけれども、受けとめてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"大沢委員","kind":"質問・要望","question":"１ページで２つ伺います。ちょっとここのところは具体的にどのようなことをおっしゃっているのかを教えていただきたいのが１つと、そこのところ、２点説明を求めました。","respondent":"冨岡高齢者福祉課長","answer":"今後のサービスを考えた場合に保険料の問題もありますので、公的なサービスについては選択と集中をせざるを得ない方向に行くだろうという内容です。","id":"exchange-012"},{"speaker":"大沢委員","kind":"質問・要望","question":"前段のことからもう１回お尋ねしますが、この３番目だけはちょっと僕は読んでいても、ちょっとそこら辺のところをお願いしたいという部分があります。ぜひとも「気づき」という言葉、そこのところはご配慮のほどを、骨子案から本案につくるまでの作業の中でご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"中塚副委員長","kind":"質問","question":"最近お元気かしら」とお伺いする、具合を伺う、何かその辺がよくわからないんです。改めて伺いたいんですけれども、そういう定めがあるのか、ちょっとそこをご説明いただけますか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"こういうところをベースに考えながら地域の福祉活動をする上において活用できるということで今後の活用のルールを研究し、まとめてまいりたいです。","id":"exchange-014"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"いや、やっぱりしっかりと根拠があることとして示していくことは大事だと思いますので、その１点をもう一度伺いたいと思います。要するに何箇所、どんな対象で行うのか、その位置づけや規模についてご説明いただけますか尋ねました。","respondent":"木下健康福祉事業部長、冨岡高齢者福祉課長","answer":"この辺が地域の方々に言葉で説明してもなかなかおわかりいただけない部分があって、町会の方々を中心に大変複雑な気持ちでおられるわけですね。今回は地区懇談会を歩きまして、このようなやり方をきちんとやることによって… 今、部長からも話がありましたように、２ページの「検討状況」の中にありますふれあいサポート活動等におきまして。","id":"exchange-015"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"で、意見を求める、これをしっかりと制度としてより充実してほしいと求めました。品川区としてのこの品川区地域福祉計画の中の品川区の役割、位置づけはどこにあるのか、そのお考えをちょっとご説明いただけますか尋ねました。","respondent":"木下健康福祉事業部長","answer":"この２番目は、４番目の地域力を上げるということ、この辺は全く異論がないことだと思います。１０年たってもあまり社会的背景としてそごがないといいますか、さらにいろいろなご意見をいただきながら修正していきたいと思っているところです。","id":"exchange-016"},{"speaker":"稲川委員","kind":"質問・要望","question":"１回ちょっと確認したいんですけれども、そういうことも聞いたことがあるので、それを規制したのがこの活用ルールということでいいのかどうなのか。そこには個人情報保護条例があって、それがあれば、その辺はもう品川区が立ち入るすきが全くないのかどうなのかを教えていただきたいんですけれども。","respondent":"冨岡高齢者福祉課長","answer":"多分、今おっしゃった前段ですが、おっしゃるとおり、これはあくまでも品川区の情報を活用していくです。同意をいただいておければいいと思いますが、それはちょっとそこのそれぞれのほうを読んでみないとわからないという状況があるかと思います。","id":"exchange-017"},{"speaker":"山元委員","kind":"質問","question":"４番目のこの「計画改定の視点」の、それのまた４番目なんですけれども、町内会を見ても連帯感は本当に希薄化しているわけです。その「意識を育てる」ということはどのように具体的にこうやっていこうとかと、そういう何か計画ではないんですけれども、何かおありなんか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"結局、こういうさまざまな支援、地道に取り組んで少しずつ意識を高めていただくという方法がやっぱりとり得る方法かなと考えています。そういうつくり方をしたいと考えていますが、これを機に、そういう高められるようないい計画にしていきたいと思っているところです。","id":"exchange-018"},{"speaker":"三上委員","kind":"質問・要望","question":"一般質問の所管質問ということで通告してあるので、ここの部分についてかなり関係しているんです。後ほどそういう形でちょっとまた逆戻りの質問になるかわかりませんが、ご了解しておいていただきたいと、こう思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"そして求められる質がもっと向上していくというところで「選択と集中」というふうになっているわけで、品川区のほうも同じだと思うんですけれども。そこのところがちょっと確認しておかなければいけないかなと思ったので、ちょっとそういうところを改めて伺いたいと思います。","respondent":"木下健康福祉事業部長","answer":"行政はその必要な部分について責任を持ってやっていくという基本的な考え方は変わりありませんけれども、その境目の部分については。","id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、時代とともに変わるから、財源の問題についても一つ変わる要因なのだという、そういうくくり方をしていただきたくないと思っています。公助という基本的な部分はしっかり貫いて、ちょっとそのことを強く思いとして申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"南委員","kind":"質問・要望","question":"国の負担割合というか、１９８４年当時から比較してどういうふうになっているのかを、ちょっと数字を具体的に額を教えてほしいと求めました。先ほどの質問ともダブるかもしれませんけれども、あるいは２人世帯でやっぱり６５歳以上、その具体的な数字も教えてほしいと求めました。","respondent":"本城国保医療年金課長","answer":"１つ目が、経過措置が終わった後どうなるかですが、現在のところ、あくまでも経過措置ですので、２年間の経過措置として予定しています。手元にちょっと持ち合わせておりませんので、申しわけございませんが、お願いします。","id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひこれはちょっと数字を教えていただかないと、この影響、そういう点でぜひ教えてほしいと求めました。それから、今回がどういういろいろな部分で影響が出てくるのかを見たいと思うので質問したところですので、ちょっとよろしくお願いしたいと思います。","respondent":"本城国保医療年金課長","answer":"先ほどご説明させていただいたのは、今の想定では３％強の人が、今まで均等割のみだった方が所得割も賦課されることになるという想定です。","id":"exchange-023"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"１つ伺いたいのは、払える国民健康保険料に引き下げていただきたい、そのお考えを聞かせてほしいと求めました。私は、ますます滞納者が増えてしまうのではないかと心配するんですけれども、いかがか尋ねました。","respondent":"本城国保医療年金課長","answer":"ただ、平成２３年の保険料はまだこれから正式には決まるので、正確なところはこれからということにはなります。品川区、国としても財政的責任はきちんと果たしてもらいたいということは、全国市長会等を通じてかねてより要望・主張しています。","id":"exchange-024"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"先ほどお伺いしたら、要するに国民健康保険加入者のうち滞納世帯が２２.６％、その滞納者がどのように推移していると思うのか。国庫負担については品川区も求めているとたびたび伺いますけれども、そういう方向が必要だと思うんですけれども、あわせてご説明ください。","respondent":"本城国保医療年金課長","answer":"滞納世帯がどういうふうに推移するかの見込みですが、その前が２１.６１％、その前が２０.６２％ということで。先ほどご質問がありました７割・５割の軽減のほかに、新たに２割軽減措置を設けたり、そういうような制度の変遷にはなっていると理解しています。","id":"exchange-025"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"この１年間で５万円、６万円、７万円と負担が上がるわけです。国にしっかりと責任を求めることと、あらゆる保険料へ引き下げること、やっぱりその方向が私は必要だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"南委員","kind":"質問","question":"時間にきちんと仕切りたいという思いはあるんですけれども、一つは、そういうところが影響がやっぱり少なくないと思うんです。先ほど申し上げたこの質問の数字と１９８０年当時の国庫負担の額を教えていただいて、それから伺ってこの質問を終わりにしたいと考えていますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"南委員","kind":"質問・要望","question":"品川区の場合は、６５歳以上のひとり暮らし高齢者の方は加入世帯の全体で３割程度という、そういうことなんですか。ちょっとその辺、正確に教えてほしいと求めました。","respondent":"本城国保医療年金課長","answer":"同じ「調整交付金」という名前で、東京都の交付金と国の交付金、両方ございまして、先ほど９％と申し上げましたのは、国の調整交付金のものです。","id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"２年で終わってしまうということと、それから、むしろ減らしていけるような払える保険料をしっかり追求していかなければいけないと思うんです。所得の低い方々への対策をしっかり強化するという、そういうことをぜひやっていただきたいということを改めて申し上げて終わりにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"}]},{"id":"topic-02","title":"続きまして、次に予定表の２「その他」","agenda":"続きまして、次に予定表の２「その他」","exchanges":[{"speaker":"三上委員","kind":"質問","question":"一般質問の中でお尋ねしたのは、要するに基本的に代読・代筆サービスの提供が基本的には図書館の中での質問ということでやっていた。そして、そこのところをちょっとお伺いしたいと、こう思います。","respondent":"冨岡高齢者福祉課長","answer":"例えば、在宅介護支援センターでも高齢者の方が、やはり地域福祉の広い意味の生活の支援のサービスになるのかなと考えられると思います。","id":"exchange-030"},{"speaker":"三上委員","kind":"質問・要望","question":"ですから、それはもう本当にやっていっていただきたいということは、これはお願いしなければならないと、こう思います。こういうふうに言っているわけですから、ぜひ手を挙げて取り組んでいっていただきたいと、こう思うんです。","respondent":"木下健康福祉事業部長","answer":"基本的には例えば地域センターとか在宅介護支援センターなどがそういう部分については適宜お気軽にご相談いただいてご説明する。財源については常に有利なものを取捨選択するという考え方でいきたいと思いますので、その際の一つの検討材料とさせていただきたいと思います。","id":"exchange-031"},{"speaker":"三上委員","kind":"質問・要望","question":"こういうことになってくるでしょうから、それは最大限ご努力いただいて、それは探していってほしいと求めました。副区長がいらっしゃるのでぜひ取り組んでいっていただくように、これはお願いしたいと思いますが、いかがか尋ねました。","respondent":"山田副区長","answer":"個人情報保護というよりは区民の皆様方のそれぞれご提供された情報については守秘義務、これは当然かかってありますので、クリアできるかと思います。いろいろな方が来たときにきちんと対応できるというところの部分と、今後、検討を十分にさせていただきたいと考えています。","id":"exchange-032"},{"speaker":"三上委員","kind":"意見","question":"ぜひご努力いただいて、早い段階で実現していただけるようお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/360687?Template=document&Id=3286#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":47025,"voices":103}}]);
